/** Author-written bilingual curriculum. Deterministic task parameters are checked at build time.
 * Russian/Kazakh terminology and pedagogical quality still require human editorial review. */
export type Language = 'ru' | 'kk';
export type Track = 'base' | 'profile' | 'literacy';
export type Bilingual = { ru: string; kk: string };
export type BilingualSteps = { ru: string[]; kk: string[] };
export type TaskType = 'number' | 'single' | 'multiple' | 'matching' | 'expression';
export interface Task {
  id: string; topicId: string; type: TaskType; level: 1 | 2 | 3; prompt: Bilingual;
  answer: string | string[]; options?: string[]; pairs?: { left: string; right: string }[];
  solution: BilingualSteps; hints: BilingualSteps; skill: string; commonError: Bilingual;
  unit?: string; tolerance?: number;
}
export interface Example { problem: Bilingual; steps: BilingualSteps; answer: string; }
export interface Lesson {
  goal: Bilingual; explanation: Bilingual; simpler: Bilingual; formula: Bilingual; terms: Bilingual;
  examples: Example[]; mistakes: BilingualSteps; recap: BilingualSteps; guided: Example;
}
export interface Topic {
  id: string; module: string; track: Track; title: Bilingual; spec: string | null;
  prerequisites: string[]; minutes: number; description: Bilingual; lesson: Lesson; tasks: Task[];
}
export const programVersion = {
  year: 2026, checkedAt: '2026-10-05', contentVersion: 'ent-math-2026.1',
  profileSource: 'https://testcenter.kz/wp-content/uploads/2025/10/10_%D0%9C%D0%B0%D1%82%D0%B5%D0%BC%D0%B0%D1%82%D0%B8%D0%BA%D0%B0_%D1%80%D1%83%D1%81.pdf',
  literacySource: 'https://testcenter.kz/wp-content/uploads/2025/10/08_%D0%9C%D0%B0%D1%82%D0%B5%D0%BC%D0%B0%D1%82%D0%B8%D1%87%D0%B5%D1%81%D0%BA%D0%B0%D1%8F-%D0%B3%D1%80%D0%B0%D0%BC%D0%BE%D1%82%D0%BD%D0%BE%D1%81%D1%82%D1%8C.pdf',
  mathematicalValidation: 'deterministic arithmetic and substitution checks',
  editorialStatus: 'Kazakh translation and teaching materials await human review',
};
const b = (ru: string, kk: string): Bilingual => ({ ru, kk });
const bs = (...s: Bilingual[]): BilingualSteps => ({ ru: s.map(x => x.ru), kk: s.map(x => x.kk) });
const f = (n: number) => Number(n.toFixed(8)).toString();
const checks: { label: string; valid: boolean }[] = [];
function verify(label: string, valid: boolean) { checks.push({ label, valid }); }
function equal(a: number, c: number) { return Number.isFinite(a) && Math.abs(a - c) < 1e-7; }
type Draft = Omit<Task, 'id' | 'topicId' | 'level' | 'skill' | 'commonError'>;
function num(prompt: Bilingual, answer: number, steps: Bilingual[], unit?: string, hint?: Bilingual): Draft {
  verify(prompt.ru, Number.isFinite(answer));
  if(Math.abs(answer-Number(answer.toFixed(6)))>1e-10) prompt=b(`${prompt.ru} Округли до 6 знаков после запятой.`,`${prompt.kk} Үтірден кейінгі 6 таңбаға дейін дөңгелекте.`);
  return { type: 'number', prompt, answer: f(answer), solution: bs(...steps), unit,
    tolerance: 0.000001,
    hints: bs(hint ?? b('Найди, что известно и что нужно получить. Выбери формулу из памятки урока.', 'Берілген және ізделетін шаманы анықта. Сабақтың формуласын таңда.'),
      steps[0] ?? b('Запиши первый шаг отдельно.', 'Бірінші қадамды бөлек жаз.'),
      b('Продолжи вычисления и проверь ответ подстановкой или обратным действием.', 'Есептеуді жалғастырып, жауабыңды орнына қою немесе кері амал арқылы тексер.')) };
}
function expr(prompt: Bilingual, answer: string, steps: Bilingual[], hint: Bilingual): Draft {
  return { type: 'expression', prompt, answer, solution: bs(...steps), hints: bs(hint, steps[0], b('Подставь простое допустимое число в исходное и итоговое выражение.', 'Бастапқы және соңғы өрнекке қарапайым рұқсат етілген санды қой.')) };
}
function select(prompt: Bilingual, answer: string[], options: string[], steps: Bilingual[]): Draft {
  return { type: 'multiple', prompt, answer, options, solution: bs(...steps), hints: bs(
    b('Проверь каждый вариант независимо. Правильных может быть несколько.', 'Әр нұсқаны жеке тексер. Бірнеше дұрыс жауап болуы мүмкін.'), steps[0],
    b('Отметь все подходящие варианты и исключи остальные.', 'Барлық сәйкес нұсқаларды белгіле, қалғандарын алып таста.')) };
}
function matching(prompt: Bilingual, pairs: { left: string; right: string }[], steps: Bilingual[]): Draft {
  return { type: 'matching', prompt, pairs, options: [...pairs.map(x => x.right)].reverse(), answer: pairs.map(x => x.right), solution: bs(...steps), hints: bs(
    b('Начни с самого простого левого элемента.', 'Ең қарапайым сол жақ элементтен баста.'), steps[0],
    b('Каждое соответствие проверь отдельно.', 'Әр сәйкестікті жеке тексер.')) };
}
type TopicDef = {
  id: string; module: string; track: Track; title: Bilingual; spec: string | null; prerequisites: string[];
  goal: Bilingual; explanation: Bilingual; simpler: Bilingual; formula: Bilingual; terms: Bilingual;
  error: Bilingual; recap: Bilingual; build: (i: number, n: number, level: number) => Draft;
};
const definitions: TopicDef[] = [];
function add(d: TopicDef) { definitions.push(d); }
const step = (ru: string, kk: string) => b(ru, kk);

add({ id: 'numbers', module: 'Числа и вычисления', track: 'base', title: b('Порядок действий', 'Амалдардың орындалу реті'), spec: null, prerequisites: [],
  goal: b('Вычислять выражения и проверять результат — например, стоимость нескольких покупок.', 'Өрнектерді есептеп, нәтижені тексеру — мысалы, бірнеше сатып алудың құнын.'),
  explanation: b('Числовое выражение — запись чисел и действий. Скобки объединяют действия: сначала считаем внутри них. Потом выполняем умножение и деление слева направо, затем сложение и вычитание. Поэтому 2 + 3 · 4 = 14, а (2 + 3) · 4 = 20.', 'Сандық өрнек — сандар мен амалдардың жазылуы. Алдымен жақша ішін есептейміз. Одан кейін көбейту мен бөлуді солдан оңға, соңында қосу мен азайтуды орындаймыз. Сондықтан 2 + 3 · 4 = 14, ал (2 + 3) · 4 = 20.'),
  simpler: b('Скобки — первая очередь. Умножение и деление — вторая. Сложение и вычитание — третья.', 'Алдымен жақша. Содан кейін көбейту мен бөлу. Соңында қосу мен азайту.'),
  formula: b('a + b · c: сначала b · c, затем прибавить a. Буквы a, b, c обозначают числа.', 'a + b · c: алдымен b · c, содан кейін a қосылады. a, b, c — сандар.'),
  terms: b('Выражение — запись вычисления; значение выражения — результат.', 'Өрнек — есептеудің жазылуы; өрнектің мәні — нәтижесі.'),
  error: b('Сложение выполнено раньше умножения.', 'Қосу көбейтуден бұрын орындалған.'), recap: b('Отметь порядок действий до вычислений.', 'Есептеуге дейін амалдардың ретін белгіле.'),
  build: (i,n,l) => l===1 ? num(b(`Вычисли ${n} + 3 · ${n+2}.`, `${n} + 3 · ${n+2} мәнін есепте.`), n+3*(n+2), [step(`Сначала 3 · ${n+2} = ${3*(n+2)}.`, `Алдымен 3 · ${n+2} = ${3*(n+2)}.`),step(`Прибавляем ${n}: ${n+3*(n+2)}.`, `${n} қосамыз: ${n+3*(n+2)}.`)]) : l===2 ? num(b(`Вычисли (${n+7} − ${n}) · 4 + 18 : 3.`, `(${n+7} − ${n}) · 4 + 18 : 3 мәнін есепте.`),34,[step('Скобки: разность равна 7.','Жақшадағы айырма 7-ге тең.'),step('7 · 4 = 28; 18 : 3 = 6.','7 · 4 = 28; 18 : 3 = 6.'),step('28 + 6 = 34.','28 + 6 = 34.')]) : num(b(`${n+1} тетрадей стоят по 180 ₸; скидка на всю покупку 100 ₸. Сколько заплатят?`, `${n+1} дәптердің әрқайсысы 180 ₸. Барлық сатып алуға 100 ₸ жеңілдік берілді. Қанша төлейді?`),(n+1)*180-100,[step(`Стоимость без скидки: ${n+1} · 180 = ${(n+1)*180}.`,`Жеңілдіксіз құны: ${n+1} · 180 = ${(n+1)*180}.`),step('Вычитаем 100 ₸.','100 ₸ азайтамыз.')],'₸') });

add({ id:'fractions', module:'Числа и вычисления', track:'base', title:b('Дроби без страха','Бөлшектерді түсіну'), spec:null, prerequisites:['numbers'],
  goal:b('Складывать, умножать и делить дроби, понимать долю целого.','Бөлшектерді қосу, көбейту, бөлу және бүтіннің бөлігін түсіну.'),
  explanation:b('Дробь a/b означает: целое разделили на b равных частей и взяли a. Нижнее число — знаменатель, верхнее — числитель. Складывать можно одинаковые части: 1/3 + 1/6 = 2/6 + 1/6. При умножении перемножаем верх и низ. Чтобы разделить на ненулевую дробь, умножаем на перевёрнутую.','a/b бөлшегі: бүтін b тең бөлікке бөлінді, оның a бөлігі алынды. Төменгі сан — бөлім, жоғарғы сан — алым. Қосу үшін бірдей бөліктер керек: 1/3 + 1/6 = 2/6 + 1/6. Көбейткенде алымдарды және бөлімдерді көбейтеміз. Нөл емес бөлшекке бөлу үшін кері бөлшекке көбейтеміз.'),
  simpler:b('Половина пиццы и четверть — это две четверти и ещё одна: три четверти.','Пиццаның жартысы мен ширегі — екі ширек және тағы бір ширек: үш ширек.'),
  formula:b('a/b + c/d = (ad+bc)/(bd); a/b : c/d = ad/(bc). b,d,c ≠ 0 при делении.','a/b + c/d = (ad+bc)/(bd); a/b : c/d = ad/(bc). Бөлгенде b,d,c ≠ 0.'), terms:b('Числитель — сколько частей взято. Знаменатель — на сколько частей разделено целое.','Алым — алынған бөліктер саны. Бөлім — бүтін бөлінген бөліктер саны.'),error:b('Сложены знаменатели или сокращены слагаемые вместо множителей.','Бөлімдер қосылған немесе көбейткіш орнына қосылғыш қысқартылған.'),recap:b('Приведи к общему знаменателю; сокращай только общие множители.','Ортақ бөлімге келтір; тек ортақ көбейткішті қысқарт.'),
  build:(i,n,l)=> l===1?num(b(`Вычисли ${n}/8 + 1/4. Ответ запиши десятичной дробью.`,`${n}/8 + 1/4 мәнін есепте. Жауапты ондық бөлшекпен жаз.`),(n+2)/8,[step('1/4 = 2/8.','1/4 = 2/8.'),step(`Складываем числители: (${n}+2)/8 = ${f((n+2)/8)}.`,`Алымдарды қосамыз: (${n}+2)/8 = ${f((n+2)/8)}.`)]) : l===2?num(b(`Вычисли (${n}/3) : (2/3). Ответ — число.`,`(${n}/3) : (2/3) мәнін есепте. Жауап — сан.`),n/2,[step('Деление заменяем умножением на 3/2.','Бөлуді 3/2-ге көбейтумен алмастырамыз.'),step(`${n}/3 · 3/2 = ${n}/2 = ${f(n/2)}.`,`${n}/3 · 3/2 = ${n}/2 = ${f(n/2)}.`)]) : num(b(`В бутылке ${n+3} литров. Выпили 3/8 содержимого. Сколько литров осталось?`,`Бөтелкеде ${n+3} литр бар. Оның 3/8 бөлігі ішілді. Неше литр қалды?`),(n+3)*5/8,[step('Осталось 1 − 3/8 = 5/8.','1 − 3/8 = 5/8 бөлігі қалды.'),step(`Умножаем ${n+3} на 5/8.`,`${n+3} санын 5/8-ге көбейтеміз.`)],'л') });

add({ id:'negatives',module:'Числа и вычисления',track:'base',title:b('Отрицательные числа и знаки','Теріс сандар және таңбалар'),spec:null,prerequisites:['numbers'],goal:b('Считать с отрицательными числами и объяснять знак результата.','Теріс сандармен есептеу және нәтиженің таңбасын түсіндіру.'),
  explanation:b('Отрицательное число находится слева от нуля: −5 меньше −2. Сумма одинаковых знаков сохраняет знак. Для разных знаков сравни модули (расстояния от нуля) и вычти меньший из большего. При умножении одинаковые знаки дают плюс, разные — минус. Вычесть отрицательное число означает прибавить положительное.','Теріс сан нөлдің сол жағында орналасады: −5 саны −2-ден кіші. Бірдей таңбалы сандардың қосындысы таңбасын сақтайды. Әртүрлі таңбада модульдерді салыстыр (нөлден қашықтық) және кішісін үлкенінен азайт. Көбейтуде бірдей таңба плюс, әртүрлі таңба минус береді. Теріс санды азайту — оң санды қосу.'),
  simpler:b('Долг 7 ₸ и прибавка 10 ₸ дают 3 ₸: −7 + 10 = 3.','7 ₸ қарыз және 10 ₸ кіріс 3 ₸ береді: −7 + 10 = 3.'),formula:b('a − (−b) = a+b; (−a)(−b) = ab; (−a)b = −ab.','a − (−b) = a+b; (−a)(−b) = ab; (−a)b = −ab.'),terms:b('Модуль |a| — расстояние от a до нуля; он неотрицателен.','|a| модулі — a санынан нөлге дейінгі қашықтық; ол теріс емес.'),error:b('Правило знаков умножения применено к сложению.','Көбейту таңбаларының ережесі қосуға қолданылған.'),recap:b('Отдельно выбери знак и выполни действие с модулями.','Таңбаны бөлек анықтап, модульдерге амал орында.'),
  build:(i,n,l)=>l===1?num(b(`Вычисли −${n+6} + ${n+2}.`,`−${n+6} + ${n+2} мәнін есепте.`),-4,[step(`Модуль отрицательного числа больше на 4.`,`Теріс санның модулі 4-ке артық.`),step('Результат −4.','Нәтиже −4.')]):l===2?num(b(`Вычисли (−${n}) · (−3) − ${n+4}.`,`(−${n}) · (−3) − ${n+4} мәнін есепте.`),2*n-4,[step(`Два минуса при умножении дают ${3*n}.`,`Көбейтудегі екі минус ${3*n} береді.`),step(`Вычитаем ${n+4}.`,`${n+4} санын азайтамыз.`)]):num(b(`Температура была −${n+3} °C, выросла на 7 °C и упала на 2 °C. Какой стала?`,`Температура −${n+3} °C болды, 7 °C көтеріліп, 2 °C төмендеді. Енді неше?`),2-n,[step(`Записываем −${n+3}+7−2.`,`−${n+3}+7−2 жазамыз.`),step(`Изменение всего +5; итог ${2-n}.`,`Жалпы өзгеріс +5; нәтиже ${2-n}.`)],'°C') });

add({id:'percentages',module:'Практические расчёты',track:'base',title:b('Проценты в жизни','Өмірдегі пайыздар'),spec:null,prerequisites:['fractions'],goal:b('Найти процент числа, исходную цену и результат двух изменений.','Санның пайызын, бастапқы бағаны және екі өзгерістің нәтижесін табу.'),explanation:b('Процент — одна сотая целого. 20% = 20/100 = 0,2. Сначала выясни, какое число принято за 100%. После изменения база может стать другой: скидка 20%, затем повышение 20% не возвращают исходную цену.','Пайыз — бүтіннің жүзден бір бөлігі. 20% = 20/100 = 0,2. Алдымен 100% деп қай сан алынғанын анықта. Өзгерістен кейін негіз өзгереді: 20% жеңілдік, одан кейін 20% өсім бастапқы бағаны қайтармайды.'),simpler:b('1% от 500 — это 5. Тогда 10% — 50.','500-дің 1%-ы — 5. Сондықтан 10%-ы — 50.'),formula:b('Часть = целое · p/100. Новое = старое · (1±p/100). p — процент.','Бөлік = бүтін · p/100. Жаңа = ескі · (1±p/100). p — пайыз.'),terms:b('База процента — величина, соответствующая 100%.','Пайыздың негізі — 100%-ға сәйкес шама.'),error:b('Второй процент посчитан от первоначальной цены.','Екінші пайыз бастапқы бағадан есептелген.'),recap:b('Для каждого изменения подпиши своё 100%.','Әр өзгеріс үшін 100%-ын белгіле.'),build:(i,n,l)=>l===1?num(b(`Найди ${n*5}% от 800.`,`800-дің ${n*5}%-ын тап.`),40*n,[step(`${n*5}% = ${f(n*.05)}.`,`${n*5}% = ${f(n*.05)}.`),step(`800 · ${f(n*.05)} = ${40*n}.`,`800 · ${f(n*.05)} = ${40*n}.`)]):l===2?num(b(`После скидки 20% цена стала ${800*n} ₸. Найди исходную цену.`,`20% жеңілдіктен кейін баға ${800*n} ₸ болды. Бастапқы бағаны тап.`),1000*n,[step('Осталось 80% = 0,8 исходной цены.','Бастапқы бағаның 80%-ы = 0,8 қалды.'),step(`${800*n} : 0,8 = ${1000*n}.`,`${800*n} : 0,8 = ${1000*n}.`)],'₸'):num(b(`Цена ${1000*n} ₸ выросла на 10%, затем снизилась на 10%. Найди итог.`,`${1000*n} ₸ баға 10% өсті, кейін 10% төмендеді. Соңғы бағаны тап.`),990*n,[step(`После роста: ${1000*n} · 1,1 = ${1100*n}.`,`Өскеннен кейін: ${1000*n} · 1,1 = ${1100*n}.`),step(`После снижения: ${1100*n} · 0,9 = ${990*n}.`,`Төмендегеннен кейін: ${1100*n} · 0,9 = ${990*n}.`)],'₸')});

add({id:'proportions',module:'Практические расчёты',track:'base',title:b('Пропорции и масштаб','Пропорциялар және масштаб'),spec:null,prerequisites:['fractions'],goal:b('Сравнивать величины и решать задачи на одинаковое отношение.','Шамаларды салыстыру және бірдей қатынасқа есептер шығару.'),explanation:b('Отношение a:b показывает, сколько единиц b приходится на a. Пропорция — равенство отношений. При одинаковой цене больше товара стоит пропорционально больше. При одинаковой работе больше работников сокращают время: это обратная зависимость.','a:b қатынасы a-ға b-ның қанша бірлігі сәйкес келетінін көрсетеді. Пропорция — қатынастардың теңдігі. Баға бірдей болса, тауар көбірек болғанда құны пропорционал өседі. Жұмыс бірдей болса, жұмысшы көбейгенде уақыт азаяды: бұл кері тәуелділік.'),simpler:b('Если 2 кг стоят 600 ₸, то 1 кг — 300 ₸, а 5 кг — 1500 ₸.','2 кг 600 ₸ тұрса, 1 кг — 300 ₸, 5 кг — 1500 ₸.'),formula:b('a/b=c/d ⇒ ad=bc (b,d ≠ 0). Масштаб 1:k: реальная длина = длина на карте · k.','a/b=c/d ⇒ ad=bc (b,d ≠ 0). 1:k масштабында нақты ұзындық = картадағы ұзындық · k.'),terms:b('Пропорция — равенство двух отношений; масштаб — отношение изображения к реальности.','Пропорция — екі қатынастың теңдігі; масштаб — кескіннің нақты шамасына қатынасы.'),error:b('Перепутана прямая и обратная зависимость.','Тура және кері тәуелділік шатастырылған.'),recap:b('Сначала реши: вместе растут величины или одна убывает?','Алдымен анықта: шамалар бірге өсе ме, әлде бірі кеми ме?'),build:(i,n,l)=>l===1?num(b(`Реши x/3 = ${n}/2.`,`x/3 = ${n}/2 теңдеуін шеш.`),1.5*n,[step(`2x = ${3*n}.`,`2x = ${3*n}.`),step(`x = ${f(1.5*n)}.`,`x = ${f(1.5*n)}.`)]):l===2?num(b(`На карте масштаба 1:100000 длина ${n+2} см. Сколько это километров?`,`1:100000 масштабты картада ұзындық ${n+2} см. Бұл неше километр?`),n+2,[step('1 см соответствует 100000 см = 1 км.','1 см 100000 см-ге = 1 км-ге сәйкес.'),step(`Значит ${n+2} см → ${n+2} км.`,`Сонда ${n+2} см → ${n+2} км.`)],'км'):num(b(`6 рабочих делают работу за ${n+3} дней. За сколько дней сделают 3 рабочих при одинаковой производительности?`,`6 жұмысшы жұмысты ${n+3} күнде бітіреді. Өнімділігі бірдей 3 жұмысшы неше күнде бітіреді?`),2*(n+3),[step(`Объём: 6 · ${n+3} человеко-дней.`,`Көлемі: 6 · ${n+3} адам-күн.`),step('Рабочих вдвое меньше, время вдвое больше.','Жұмысшы екі есе аз, уақыт екі есе көп.')],'дн')});

add({id:'units',module:'Практические расчёты',track:'base',title:b('Единицы измерения','Өлшем бірліктері'),spec:null,prerequisites:['numbers'],goal:b('Переводить длину, площадь, объём и скорость без потери смысла.','Ұзындық, аудан, көлем және жылдамдық бірліктерін дұрыс түрлендіру.'),explanation:b('Единица сообщает, что измерено. 1 м = 100 см. Для площади квадрат содержит 100 · 100 маленьких квадратов, поэтому 1 м² = 10000 см². Для объёма множитель действует три раза. Перед сложением или подстановкой в формулу приведи величины к одним единицам.','Бірлік не өлшенгенін көрсетеді. 1 м = 100 см. Аудан үшін шаршыда 100 · 100 кіші шаршы бар, сондықтан 1 м² = 10000 см². Көлемде көбейткіш үш рет қолданылады. Қосу немесе формулаға қою алдында шамаларды бірдей бірлікке келтір.'),simpler:b('Метр — длина стороны, квадратный метр — площадь пола. Это разные величины.','Метр — қабырға ұзындығы, шаршы метр — еден ауданы. Бұлар әртүрлі шамалар.'),formula:b('1 м²=10000 см²; 1 м³=1000 л; v км/ч = v/3,6 м/с.','1 м²=10000 см²; 1 м³=1000 л; v км/сағ = v/3,6 м/с.'),terms:b('Площадь измеряет поверхность, объём — место внутри тела.','Аудан бетті өлшейді, көлем дененің ішіндегі кеңістікті өлшейді.'),error:b('Для площади использован множитель длины вместо его квадрата.','Аудан үшін ұзындық көбейткішінің квадраты алынбаған.'),recap:b('Проверь размерность и подпиши единицу в ответе.','Өлшемді тексеріп, жауапта бірлігін жаз.'),build:(i,n,l)=>l===1?num(b(`Переведи ${n+2} м в сантиметры.`,`${n+2} м-ді сантиметрге айналдыр.`),100*(n+2),[step('В одном метре 100 см.','Бір метрде 100 см.'),step(`Умножаем ${n+2} на 100.`,`${n+2} санын 100-ге көбейтеміз.`)],'см'):l===2?num(b(`Переведи ${n+2} м² в см².`,`${n+2} м²-ді см²-ге айналдыр.`),10000*(n+2),[step('1 м² = 100 · 100 = 10000 см².','1 м² = 100 · 100 = 10000 см².'),step(`Умножаем ${n+2} на 10000.`,`${n+2} санын 10000-ға көбейтеміз.`)],'см²'):num(b(`Скорость ${36*n} км/ч. Найди скорость в м/с.`,`${36*n} км/сағ жылдамдықты м/с-ке айналдыр.`),10*n,[step('1 км = 1000 м; 1 ч = 3600 с.','1 км = 1000 м; 1 сағ = 3600 с.'),step(`${36*n} : 3,6 = ${10*n}.`,`${36*n} : 3,6 = ${10*n}.`)],'м/с')});

add({id:'brackets',module:'Алгебраические выражения',track:'base',title:b('Скобки и подобные слагаемые','Жақшалар және ұқсас мүшелер'),spec:null,prerequisites:['negatives'],goal:b('Упрощать буквенное выражение и объяснять каждый переход.','Әріпті өрнекті ықшамдау және әр қадамды түсіндіру.'),explanation:b('Буква может обозначать любое допустимое число. Подобные слагаемые содержат одну и ту же буквенную часть: 3x+2x=5x. Число перед буквой — коэффициент. Множитель перед скобкой умножает каждое слагаемое. Минус перед скобкой — умножение на −1, поэтому все знаки меняются.','Әріп кез келген рұқсат етілген санды белгілейді. Ұқсас мүшелердің әріпті бөлігі бірдей: 3x+2x=5x. Әріптің алдындағы сан — коэффициент. Жақша алдындағы көбейткіш әр мүшеге көбейтіледі. Жақша алдындағы минус −1-ге көбейту, сондықтан барлық таңба өзгереді.'),simpler:b('Три яблока и два яблока — пять яблок. Так же 3x+2x=5x.','Үш алма мен екі алма — бес алма. Сол сияқты 3x+2x=5x.'),formula:b('a(b+c)=ab+ac; −(b−c)=−b+c. a,b,c — числа или выражения.','a(b+c)=ab+ac; −(b−c)=−b+c. a,b,c — сандар не өрнектер.'),terms:b('Коэффициент — числовой множитель буквенной части.','Коэффициент — әріпті бөліктің сандық көбейткіші.'),error:b('Минус перед скобкой изменил только первый знак.','Жақша алдындағы минус тек бірінші таңбаны өзгерткен.'),recap:b('Умножай на каждый член; объединяй только подобные.','Әр мүшеге көбейт; тек ұқсас мүшелерді біріктір.'),build:(i,n,l)=>l===1?expr(b(`Упрости ${n+2}x + ${n}x.`,`${n+2}x + ${n}x өрнегін ықшамда.`),`${2*n+2}*x`,[step(`Складываем коэффициенты: ${n+2}+${n}=${2*n+2}.`,`Коэффициенттерді қосамыз: ${n+2}+${n}=${2*n+2}.`),step('Буквенная часть x сохраняется.','x әріпті бөлігі сақталады.')],b('Оба слагаемых содержат x.','Екі мүшеде де x бар.')):l===2?expr(b(`Раскрой скобки ${n}(x+3).`,`${n}(x+3) жақшасын аш.`),`${n}*x+${3*n}`,[step(`${n} · x + ${n} · 3.`,`${n} · x + ${n} · 3.`),step(`Получаем ${n}x+${3*n}.`,`${n}x+${3*n} шығады.`)],b('Умножь число на каждое слагаемое.','Санды әр мүшеге көбейт.')):expr(b(`Упрости ${n+3}x − (${n}x − 5).`,`${n+3}x − (${n}x − 5) өрнегін ықшамда.`),'3*x+5',[step(`Минус меняет оба знака: ${n+3}x−${n}x+5.`,`Минус екі таңбаны өзгертеді: ${n+3}x−${n}x+5.`),step('Разность коэффициентов равна 3.','Коэффициенттердің айырмасы 3.')],b('Минус перед скобкой означает умножение на −1.','Жақша алдындағы минус −1-ге көбейтуді білдіреді.'))});

add({id:'identities',module:'Алгебраические выражения',track:'profile',title:b('Формулы сокращённого умножения','Қысқаша көбейту формулалары'),spec:'04',prerequisites:['brackets'],goal:b('Раскрывать квадрат суммы и узнавать разность квадратов.','Қосындының квадратын ашу және квадраттар айырмасын тану.'),explanation:b('Квадрат суммы — умножение всей суммы на себя. При раскрытии (a+b)(a+b) появляются два одинаковых произведения ab. Поэтому средний член 2ab нельзя пропускать. Формулы позволяют считать быстро и преобразовывать выражения, но не отменяют обычное распределительное правило.','Қосындының квадраты — бүкіл қосындыны өзіне көбейту. (a+b)(a+b) ашқанда екі бірдей ab көбейтіндісі шығады. Сондықтан ортаңғы 2ab мүшесін қалдыруға болмайды. Формулалар тез есептеу мен түрлендіру үшін қолданылады.'),simpler:b('(x+2)² содержит x², две полоски 2x и квадрат 4: всего x²+4x+4.','(x+2)² ішінде x², екі 2x жолақ және 4 шаршысы бар: барлығы x²+4x+4.'),formula:b('(a±b)²=a²±2ab+b²; a²−b²=(a−b)(a+b), для любых действительных a,b.','(a±b)²=a²±2ab+b²; a²−b²=(a−b)(a+b), кез келген нақты a,b үшін.'),terms:b('Тождество — равенство, верное для всех допустимых значений букв.','Тепе-теңдік — әріптердің барлық рұқсат етілген мәнінде дұрыс теңдік.'),error:b('Пропущено удвоенное произведение 2ab.','2ab екі еселенген көбейтіндісі қалдырылған.'),recap:b('Квадрат первого ± двойное произведение + квадрат второго.','Біріншінің квадраты ± екі еселенген көбейтінді + екіншінің квадраты.'),build:(i,n,l)=>l===1?expr(b(`Раскрой (x+${n})².`,`(x+${n})² жақшасын аш.`),`x^2+${2*n}*x+${n*n}`,[step(`a=x, b=${n}.`,`a=x, b=${n}.`),step(`x²+2·x·${n}+${n*n}.`,`x²+2·x·${n}+${n*n}.`)],b('Нужны три слагаемых.','Үш мүше қажет.')):l===2?num(b(`Вычисли (${n+20})² − (${n+10})² без возведения в квадрат.`,`Квадраттамай (${n+20})² − (${n+10})² мәнін тап.`),10*(2*n+30),[step('Разность квадратов — произведение разности и суммы.','Квадраттар айырмасы — айырма мен қосындының көбейтіндісі.'),step(`10 · ${2*n+30} = ${10*(2*n+30)}.`,`10 · ${2*n+30} = ${10*(2*n+30)}.`)]):matching(b(`Сопоставь выражения при a=${n} с развёрнутой формой.`,`a=${n} болғанда өрнектерді ашылған түрімен сәйкестендір.`),[{left:`(x+${n})²`,right:`x²+${2*n}x+${n*n}`},{left:`(x−${n})²`,right:`x²−${2*n}x+${n*n}`},{left:`(x−${n})(x+${n})`,right:`x²−${n*n}`}],[step('У квадратов суммы и разности одинаковый свободный член.','Қосынды мен айырма квадраттарының бос мүшесі бірдей.'),step('Средние члены имеют разные знаки; в разности квадратов среднего члена нет.','Ортаңғы мүшелердің таңбалары әртүрлі; квадраттар айырмасында ортаңғы мүше жоқ.')])});

add({id:'factoring',module:'Алгебраические выражения',track:'profile',title:b('Разложение на множители','Көбейткіштерге жіктеу'),spec:'04',prerequisites:['identities'],goal:b('Представить сумму произведением для сокращения и решения уравнения.','Қысқарту мен теңдеу шешу үшін қосындыны көбейтінді түрінде жазу.'),explanation:b('Разложить на множители — заменить сумму произведением с тем же значением. Сначала ищи общий множитель. Затем узнай знакомую формулу: квадрат или разность квадратов. Проверка проста: раскрой полученные скобки и верни исходную запись.','Көбейткіштерге жіктеу — қосындыны мәні бірдей көбейтіндімен алмастыру. Алдымен ортақ көбейткіш ізде. Содан кейін квадрат немесе квадраттар айырмасы формуласын таны. Тексеру үшін алынған жақшаларды аш.'),simpler:b('6x+9 — это 3 одинаковые группы (2x+3).','6x+9 — бірдей (2x+3) тобының үшеуі.'),formula:b('ab+ac=a(b+c); x²−a²=(x−a)(x+a).','ab+ac=a(b+c); x²−a²=(x−a)(x+a).'),terms:b('Множитель — часть произведения; общий множитель есть в каждом слагаемом.','Көбейткіш — көбейтіндінің бөлігі; ортақ көбейткіш әр мүшеде бар.'),error:b('Общий множитель вынесен не из всех членов.','Ортақ көбейткіш барлық мүшеден шығарылмаған.'),recap:b('Проверь обратным раскрытием скобок.','Жақшаларды қайта ашып тексер.'),build:(i,n,l)=>l===1?expr(b(`Разложи ${n+2}x+${3*(n+2)} на множители.`,`${n+2}x+${3*(n+2)} өрнегін көбейткіштерге жікте.`),`${n+2}*(x+3)`,[step(`Общий множитель ${n+2}.`,`Ортақ көбейткіш ${n+2}.`),step('После деления каждого члена остаётся x+3.','Әр мүшені бөлгенде x+3 қалады.')],b('Найди общее число в двух слагаемых.','Екі мүшедегі ортақ санды тап.')):l===2?expr(b(`Разложи x²−${n*n}.`,`x²−${n*n} өрнегін жікте.`),`(x-${n})*(x+${n})`,[step(`${n*n} = ${n}².`,`${n*n} = ${n}².`),step('Применяем разность квадратов.','Квадраттар айырмасын қолданамыз.')],b('Оба члена являются квадратами.','Екі мүше де квадрат.')):num(b(`Какова сумма всех корней x²−${2*n+3}x+${n*(n+3)}=0?`,`x²−${2*n+3}x+${n*(n+3)}=0 теңдеуінің барлық түбірінің қосындысы неше?`),2*n+3,[step(`Нужны два числа с суммой ${2*n+3} и произведением ${n*(n+3)}: ${n}, ${n+3}.`,`Қосындысы ${2*n+3}, көбейтіндісі ${n*(n+3)} екі сан: ${n}, ${n+3}.`),step(`(x−${n})(x−${n+3})=0; сумма ${2*n+3}.`,`(x−${n})(x−${n+3})=0; қосындысы ${2*n+3}.`)])});

add({id:'algebra-fractions',module:'Алгебраические выражения',track:'profile',title:b('Алгебраические дроби и ОДЗ','Алгебралық бөлшектер және ММЖ'),spec:'01,04',prerequisites:['factoring','fractions'],goal:b('Сокращать дробь и сохранять ограничения исходного выражения.','Бөлшекті қысқарту және бастапқы өрнектің шектеулерін сақтау.'),explanation:b('В алгебраической дроби числитель и знаменатель содержат буквы. Знаменатель не может быть нулём: деление на ноль не определено. Сокращаем одинаковые множители, а не отдельные слагаемые. Даже если множитель исчез, его запрещённое значение остаётся запрещённым в исходной задаче.','Алгебралық бөлшектің алымы мен бөлімінде әріптер бар. Бөлім нөл бола алмайды: нөлге бөлу анықталмаған. Бірдей көбейткіштерді қысқартамыз, жеке қосылғыштарды емес. Көбейткіш қысқарса да, бастапқы есепте тыйым салынған мән тыйым салынған болып қалады.'),simpler:b('(x²−1)/(x−1)=x+1 только при x≠1. При x=1 исходная дробь не существует.','(x²−1)/(x−1)=x+1 тек x≠1 болғанда. x=1 кезінде бастапқы бөлшек жоқ.'),formula:b('(ab)/(ac)=b/c при a≠0,c≠0. ОДЗ определяется до сокращения.','(ab)/(ac)=b/c, a≠0,c≠0 болғанда. ММЖ қысқартуға дейін анықталады.'),terms:b('ОДЗ — область допустимых значений, все значения, при которых исходная запись имеет смысл.','ММЖ — мүмкін мәндер жиыны, бастапқы өрнек мағыналы болатын барлық мәндер.'),error:b('Забыто ограничение после сокращения.','Қысқартудан кейін шектеу ұмытылған.'),recap:b('Запиши ОДЗ → разложи → сократи → сохрани ОДЗ.','ММЖ жаз → жікте → қысқарт → ММЖ сақта.'),build:(i,n,l)=>l===1?num(b(`При каком x не определена дробь ${n+1}/(x−${n})?`,`Қай x мәнінде ${n+1}/(x−${n}) бөлшегі анықталмаған?`),n,[step('Знаменатель равен нулю.','Бөлім нөлге тең.'),step(`x−${n}=0 ⇒ x=${n}.`,`x−${n}=0 ⇒ x=${n}.`)]):l===2?expr(b(`Сократи (x²−${n*n})/(x−${n}) при x≠${n}.`,`x≠${n} кезінде (x²−${n*n})/(x−${n}) бөлшегін қысқарт.`),`x+${n}`,[step(`Числитель (x−${n})(x+${n}).`,`Алымы (x−${n})(x+${n}).`),step(`Сокращаем x−${n}; остаётся x+${n}, x≠${n}.`,`x−${n} қысқартамыз; x+${n} қалады, x≠${n}.`)],b('Используй разность квадратов.','Квадраттар айырмасын қолдан.')):num(b(`Найди значение (x²−${n*n})/(x−${n}) при x=${n+2}.`,`x=${n+2} кезінде (x²−${n*n})/(x−${n}) мәнін тап.`),2*n+2,[step(`x=${n+2} допустимо, так как не равно ${n}.`,`x=${n+2} рұқсат етілген, себебі ${n}-ге тең емес.`),step(`Сокращённое выражение x+${n}, его значение ${2*n+2}.`,`Қысқартылған өрнек x+${n}, оның мәні ${2*n+2}.`)])});

add({id:'powers',module:'Степени, корни, логарифмы',track:'profile',title:b('Свойства степеней','Дәрежелердің қасиеттері'),spec:'02',prerequisites:['fractions'],goal:b('Преобразовывать степени с одинаковым основанием, включая отрицательный показатель.','Бірдей негізді дәрежелерді, теріс көрсеткішпен қоса, түрлендіру.'),explanation:b('Степень aⁿ при натуральном n — произведение n одинаковых множителей a. При умножении степеней с одинаковым основанием складываем показатели. При делении вычитаем. Нулевой показатель даёт 1 при ненулевом основании. Отрицательный показатель означает обратное число, а не отрицательный результат.','Натурал n үшін aⁿ — n бірдей a көбейткіштің көбейтіндісі. Бірдей негізді дәрежелерді көбейткенде көрсеткіштерді қосамыз, бөлгенде азайтамыз. Нөл емес негіздің нөлінші дәрежесі 1. Теріс көрсеткіш теріс нәтижені емес, кері санды білдіреді.'),simpler:b('2³ · 2² содержит пять двоек: 2⁵. 2⁻² = 1/4.','2³ · 2² ішінде бес екі бар: 2⁵. 2⁻² = 1/4.'),formula:b('aᵐaⁿ=aᵐ⁺ⁿ; aᵐ/aⁿ=aᵐ⁻ⁿ (a≠0); (aᵐ)ⁿ=aᵐⁿ; a⁻ⁿ=1/aⁿ.','aᵐaⁿ=aᵐ⁺ⁿ; aᵐ/aⁿ=aᵐ⁻ⁿ (a≠0); (aᵐ)ⁿ=aᵐⁿ; a⁻ⁿ=1/aⁿ.'),terms:b('Основание — число a; показатель — число n над ним.','Негіз — a саны; көрсеткіш — оның үстіндегі n саны.'),error:b('При умножении умножены показатели вместо сложения.','Көбейткенде көрсеткіштер қосылмай, көбейтілген.'),recap:b('Проверь одинаковое основание и ненулевую основу при делении.','Бірдей негізді және бөлгендегі нөл емес негізді тексер.'),build:(i,n,l)=>l===1?num(b(`Вычисли 2^${n} · 2².`,`2^${n} · 2² мәнін есепте.`),2**(n+2),[step(`Показатели складываем: ${n}+2.`,`Көрсеткіштерді қосамыз: ${n}+2.`),step(`Получаем 2^${n+2}=${2**(n+2)}.`,`2^${n+2}=${2**(n+2)} шығады.`)]):l===2?num(b(`Вычисли 2^${n+3} / 2^${n+1}.`,`2^${n+3} / 2^${n+1} мәнін есепте.`),4,[step(`Разность показателей (${n+3})−(${n+1})=2.`,`Көрсеткіштер айырмасы (${n+3})−(${n+1})=2.`),step('2²=4.','2²=4.')]):num(b(`Вычисли (2^${n})² · 2^${-n}.`,`(2^${n})² · 2^${-n} мәнін есепте.`),2**n,[step(`Сначала степень степени: 2^${2*n}.`,`Алдымен дәреженің дәрежесі: 2^${2*n}.`),step(`Показатель ${2*n}−${n}=${n}.`,`Көрсеткіш ${2*n}−${n}=${n}.`)])});

add({id:'radicals',module:'Степени, корни, логарифмы',track:'profile',title:b('Квадратные корни и ограничения','Квадрат түбірлер және шектеулер'),spec:'01',prerequisites:['powers'],goal:b('Вычислять и упрощать корни, не забывая знак и область определения.','Таңба мен анықталу облысын ескеріп, түбірлерді есептеу және ықшамдау.'),explanation:b('√a — неотрицательное число, квадрат которого равен a. В действительных числах a должно быть неотрицательным. √(x²)=|x|: если x отрицателен, корень всё равно положительный. Для упрощения ищи квадратный множитель под корнем.','√a — квадраты a-ға тең теріс емес сан. Нақты сандарда a теріс емес болуы керек. √(x²)=|x|: x теріс болса да, түбір оң. Ықшамдау үшін түбір астынан квадрат көбейткіш ізде.'),simpler:b('√36=6, потому что 6²=36. Корень не равен −6.','√36=6, себебі 6²=36. Түбір −6-ға тең емес.'),formula:b('√(ab)=√a√b при a,b≥0; √(x²)=|x|. Для √g(x) нужно g(x)≥0.','a,b≥0 кезінде √(ab)=√a√b; √(x²)=|x|. √g(x) үшін g(x)≥0 қажет.'),terms:b('Радикал — знак корня; подкоренное выражение — то, что находится под ним.','Радикал — түбір белгісі; түбір астындағы өрнек — оның астында тұрған өрнек.'),error:b('√(x²) заменено на x без учёта знака.','√(x²) x таңбасын ескермей x-пен алмастырылған.'),recap:b('Подкоренное неотрицательно, арифметический корень неотрицателен.','Түбір астындағы сан теріс емес, арифметикалық түбір теріс емес.'),build:(i,n,l)=>l===1?num(b(`Вычисли √${(n+3)**2}.`,`√${(n+3)**2} мәнін есепте.`),n+3,[step(`${n+3}²=${(n+3)**2}.`,`${n+3}²=${(n+3)**2}.`),step('Берём неотрицательный корень.','Теріс емес түбірді аламыз.')]):l===2?num(b(`Найди коэффициент перед √2 в √${2*(n+2)**2}.`,`√${2*(n+2)**2} өрнегіндегі √2 алдындағы коэффициентті тап.`),n+2,[step(`${2*(n+2)**2}=${(n+2)**2}·2.`,`${2*(n+2)**2}=${(n+2)**2}·2.`),step(`Выносим ${n+2}: ${n+2}√2.`,`${n+2} сыртқа шығарамыз: ${n+2}√2.`)]):num(b(`При x=−${n+2} вычисли √(x²)+x.`,`x=−${n+2} кезінде √(x²)+x мәнін есепте.`),0,[step(`√(x²)=|x|=${n+2}.`,`√(x²)=|x|=${n+2}.`),step(`${n+2}−${n+2}=0.`,`${n+2}−${n+2}=0.`)])});

add({id:'logarithms',module:'Степени, корни, логарифмы',track:'profile',title:b('Логарифм как показатель степени','Логарифм — дәреженің көрсеткіші'),spec:'07',prerequisites:['powers'],goal:b('Читать логарифм и применять свойства только на допустимых значениях.','Логарифмді түсіну және қасиеттерін тек рұқсат етілген мәндерде қолдану.'),explanation:b('logₐ b отвечает на вопрос: в какую степень возвести a, чтобы получить b? Например, log₂ 8=3. В действительных числах основание a>0 и a≠1, аргумент b>0. Логарифм произведения превращается в сумму, но логарифм суммы так не раскладывается.','logₐ b: b алу үшін a-ны қандай дәрежеге шығару керек? Мысалы, log₂ 8=3. Нақты сандарда a>0, a≠1 негізі және b>0 аргументі қажет. Көбейтіндінің логарифмі қосындыға айналады, бірақ қосындының логарифмі олай жіктелмейді.'),simpler:b('Логарифм — поиск пропущенного показателя: 2^?=8, значит ?=3.','Логарифм — белгісіз көрсеткішті табу: 2^?=8, демек ?=3.'),formula:b('logₐ b=c ⇔ aᶜ=b; logₐ(uv)=logₐu+logₐv при u,v>0, a>0,a≠1.','logₐ b=c ⇔ aᶜ=b; u,v>0, a>0,a≠1 үшін logₐ(uv)=logₐu+logₐv.'),terms:b('Аргумент логарифма — число под знаком log; основание — нижний индекс.','Логарифм аргументі — log таңбасындағы сан; негізі — төменгі индекс.'),error:b('log(u+v) ошибочно заменён на log u + log v.','log(u+v) қате түрде log u + log v-мен алмастырылған.'),recap:b('До свойства проверь положительность аргументов.','Қасиетті қолдануға дейін аргументтердің оң екенін тексер.'),build:(i,n,l)=>l===1?num(b(`Найди log₂ ${2**n}.`,`log₂ ${2**n} мәнін тап.`),n,[step(`2^${n}=${2**n}.`,`2^${n}=${2**n}.`),step(`Искомый показатель ${n}.`,`Ізделетін көрсеткіш ${n}.`)]):l===2?num(b(`Вычисли log₂ ${2**n} + log₂ 8.`,`log₂ ${2**n} + log₂ 8 мәнін есепте.`),n+3,[step(`Логарифмы равны ${n} и 3.`,`Логарифмдер ${n} және 3-ке тең.`),step(`Сумма ${n+3}.`,`Қосынды ${n+3}.`)]):select(b(`Какие значения x допустимы для log₂(x−${n})? Выбери все.`,`log₂(x−${n}) үшін қай x мәндері мүмкін? Барлығын таңда.`),[`${n+1}`,`${n+4}`],[`${n-1}`,`${n}`,`${n+1}`,`${n+4}`],[step(`Аргумент положителен: x−${n}>0 ⇒ x>${n}.`,`Аргумент оң: x−${n}>0 ⇒ x>${n}.`),step(`Подходят ${n+1} и ${n+4}.`,`${n+1} және ${n+4} сәйкес келеді.`)])});

add({id:'functions',module:'Функции и графики',track:'profile',title:b('Функции и область определения','Функциялар және анықталу облысы'),spec:'13',prerequisites:['brackets'],goal:b('Найти значение функции и понять, где формула имеет смысл.','Функцияның мәнін табу және формуланың мағыналы болатын аймағын анықтау.'),explanation:b('Функция — правило, которое каждому допустимому входу x ставит в соответствие единственный выход y. Область определения — все допустимые x. График — точки (x,y). У дроби знаменатель не ноль, у квадратного корня подкоренное выражение неотрицательно.','Функция — әрбір мүмкін x кірісіне бір ғана y шығысын сәйкестендіретін ереже. Анықталу облысы — барлық мүмкін x. График — (x,y) нүктелері. Бөлшектің бөлімі нөл емес, квадрат түбірдің астындағы өрнек теріс емес.'),simpler:b('Функция как автомат: положил x, по правилу получил y.','Функция автомат сияқты: x енгізсең, ереже бойынша y аласың.'),formula:b('y=f(x); для y=kx+b, k — наклон, b — значение при x=0.','y=f(x); y=kx+b үшін k — көлбеулік, b — x=0 кезіндегі мән.'),terms:b('Аргумент — вход x; значение функции — выход y; график — множество соответствующих точек.','Аргумент — x кірісі; функция мәні — y шығысы; график — сәйкес нүктелер жиыны.'),error:b('В дробную функцию подставлено запрещённое значение.','Бөлшек функцияға тыйым салынған мән қойылған.'),recap:b('Сначала допустимость x, затем подстановка.','Алдымен x мүмкіндігін тексер, содан кейін орнына қой.'),build:(i,n,l)=>l===1?num(b(`Для f(x)=2x+${n} найди f(3).`,`f(x)=2x+${n} үшін f(3) тап.`),6+n,[step(`Подставляем x=3: 2·3+${n}.`,`x=3 қоямыз: 2·3+${n}.`),step(`Получаем ${6+n}.`,`${6+n} шығады.`)]):l===2?num(b(`Какое единственное x исключено из области y=1/(x−${n+2})?`,`y=1/(x−${n+2}) облысынан қай жалғыз x шығарылады?`),n+2,[step('Знаменатель не должен быть нулём.','Бөлім нөл болмауы керек.'),step(`x−${n+2}=0 ⇒ x=${n+2}.`,`x−${n+2}=0 ⇒ x=${n+2}.`)]):select(b(`Какие x принадлежат области y=√(x−${n})?`,`Қай x мәндері y=√(x−${n}) анықталу облысына кіреді?`),[`${n}`,`${n+1}`,`${n+3}`],[`${n-1}`,`${n}`,`${n+1}`,`${n+3}`],[step(`x−${n}≥0 ⇒ x≥${n}.`,`x−${n}≥0 ⇒ x≥${n}.`),step('Граничное значение разрешено: корень из нуля существует.','Шекаралық мән рұқсат етілген: нөлдің түбірі бар.')])});

add({id:'transformations',module:'Функции и графики',track:'profile',title:b('Преобразования графиков','Графиктерді түрлендіру'),spec:'13',prerequisites:['functions'],goal:b('Предсказывать сдвиг и отражение графика по формуле.','Формула бойынша графиктің жылжуын және шағылуын болжау.'),explanation:b('f(x)+b двигает график вверх на b. f(x−a) двигает вправо на a: чтобы прежний вход равнялся нулю, теперь нужен x=a. Минус перед всей функцией отражает точки относительно оси x. Изменяя коэффициент квадрата, меняем ширину параболы.','f(x)+b графикті b-ға жоғары жылжытады. f(x−a) графикті a-ға оңға жылжытады: бұрынғы кіріс нөл болу үшін енді x=a қажет. Функция алдындағы минус x осіне қатысты шағылыстырады. Квадраттың коэффициентін өзгерту парабола енін өзгертеді.'),simpler:b('У y=(x−3)² вершина там, где скобка равна нулю: x=3.','y=(x−3)² төбесі жақша нөл болатын жерде: x=3.'),formula:b('y=k(x−a)²+b: вершина (a,b); k>0 — ветви вверх; k<0 — вниз.','y=k(x−a)²+b: төбесі (a,b); k>0 — тармақтары жоғары; k<0 — төмен.'),terms:b('Вершина параболы — её самая низкая или высокая точка.','Парабола төбесі — ең төменгі не ең жоғарғы нүктесі.'),error:b('Сдвиг f(x−a) истолкован как сдвиг влево.','f(x−a) солға жылжу деп түсінілген.'),recap:b('Найди ноль скобки и вертикальный сдвиг.','Жақшаның нөлін және тік жылжуды тап.'),build:(i,n,l)=>l===1?num(b(`Абсцисса вершины y=(x−${n})²+2?`,`y=(x−${n})²+2 төбесінің абсциссасы неше?`),n,[step(`Квадрат минимален при x−${n}=0.`,`Квадрат x−${n}=0 кезінде ең кіші.`),step(`x=${n}.`,`x=${n}.`)]):l===2?num(b(`Каково минимальное значение y=2(x+${n})²−${n+3}?`,`y=2(x+${n})²−${n+3} ең кіші мәні неше?`),-(n+3),[step('Квадрат ≥0, коэффициент положителен.','Квадрат ≥0, коэффициент оң.'),step(`Минимум достигается при x=−${n}; y=−${n+3}.`,`Минимум x=−${n} кезінде; y=−${n+3}.`)]):matching(b(`Сопоставь преобразования y=x² при a=${n}.`,`a=${n} үшін y=x² түрлендірулерін сәйкестендір.`),[{left:`(x−${n})²`,right:`→ ${n}`},{left:`x²+${n}`,right:`↑ ${n}`},{left:'−x²',right:'↕ Ox'}],[step('Изменение внутри скобки задаёт горизонтальный сдвиг.','Жақша ішіндегі өзгеріс көлденең жылжуды береді.'),step('Прибавка снаружи задаёт вертикальный сдвиг, минус — отражение.','Сырттағы қосынды тік жылжуды, минус шағылуды береді.')])});

add({id:'linear',module:'Уравнения',track:'profile',title:b('Линейные уравнения','Сызықтық теңдеулер'),spec:'05',prerequisites:['brackets','fractions'],goal:b('Самостоятельно решить уравнение, делая одинаковое действие с обеими частями.','Екі бөлікке бірдей амал қолданып, теңдеуді өздігінен шешу.'),explanation:b('Уравнение — равенство с неизвестным. Решить его — найти все значения, при которых равенство верно. Представь весы: одинаковое действие с обеими сторонами сохраняет равновесие. В 2x+3=11 вычитаем 3 с обеих сторон: 2x=8, затем делим обе стороны на 2: x=4. Фраза «перенести со сменой знака» — сокращение этого действия.','Теңдеу — белгісізі бар теңдік. Шешу — теңдік дұрыс болатын барлық мәнді табу. Таразыны елестет: екі жаққа бірдей амал жасау тепе-теңдікті сақтайды. 2x+3=11 теңдеуінде екі жақтан да 3 азайтамыз: 2x=8, кейін екі жағын 2-ге бөлеміз: x=4.'),simpler:b('Число, прибавленное к x, убираем вычитанием с обеих сторон. Множитель убираем делением.','x-ке қосылған санды екі жақтан азайтамыз. Көбейткішті бөлу арқылы алып тастаймыз.'),formula:b('ax+b=c ⇒ x=(c−b)/a, a≠0. Проверка: подставить x в исходное равенство.','ax+b=c ⇒ x=(c−b)/a, a≠0. Тексеру: x-ті бастапқы теңдікке қою.'),terms:b('Корень уравнения — значение неизвестного, делающее равенство верным. Равносильные уравнения имеют одинаковые корни.','Теңдеудің түбірі — теңдікті дұрыс ететін белгісіз мәні. Мәндес теңдеулердің түбірлері бірдей.'),error:b('В 2x+3=11 получено 2x=14: вместо вычитания 3 выполнено сложение. Если известен только ответ, причина ещё не установлена.','2x+3=11 теңдеуінде 2x=14 алынған: 3 азайтудың орнына қосылған. Тек жауап белгілі болса, қате себебі әлі анықталмаған.'),recap:b('Запиши действие с обеими частями. Проверь найденное значение.','Екі бөлікке жасалған амалды жаз. Табылған мәнді тексер.'),build:(i,n,l)=>{const x=n+2,a=l+1,c=a*x+3;verify(`linear ${i}`,equal(a*x+3,c));return l===1?num(b(`Реши 2x+3=${2*x+3}.`,`2x+3=${2*x+3} теңдеуін шеш.`),x,[step(`Вычитаем 3 с обеих сторон: 2x=${2*x}.`,`Екі жақтан 3 азайтамыз: 2x=${2*x}.`),step(`Делим обе стороны на 2: x=${x}.`,`Екі жақты 2-ге бөлеміз: x=${x}.`),step(`Проверка: 2·${x}+3=${2*x+3}.`,`Тексеру: 2·${x}+3=${2*x+3}.`)],undefined,b('Что прибавлено к 2x? Вычти это из обеих частей.','2x-ке не қосылған? Екі бөліктен де оны азайт.')):l===2?num(b(`Реши 3(x−2)=${3*(x-2)}.`,`3(x−2)=${3*(x-2)} теңдеуін шеш.`),x,[step(`Делим обе части на 3: x−2=${x-2}.`,`Екі бөлікті 3-ке бөлеміз: x−2=${x-2}.`),step(`Прибавляем 2: x=${x}.`,`2 қосамыз: x=${x}.`)]):num(b(`Реши (x+${n})/2 − 1 = ${n}.`,`(x+${n})/2 − 1 = ${n} теңдеуін шеш.`),n+2,[step(`Прибавляем 1: (x+${n})/2=${n+1}.`,`1 қосамыз: (x+${n})/2=${n+1}.`),step(`Умножаем на 2 и вычитаем ${n}: x=${n+2}.`,`2-ге көбейтеміз және ${n} азайтамыз: x=${n+2}.`)])}});

add({id:'quadratic',module:'Уравнения',track:'profile',title:b('Квадратные уравнения','Квадрат теңдеулер'),spec:'05',prerequisites:['linear','identities'],goal:b('Найти все корни квадратного уравнения и проверить их.','Квадрат теңдеудің барлық түбірін тауып, тексеру.'),explanation:b('Квадратное уравнение содержит x² и имеет вид ax²+bx+c=0 с a≠0. Дискриминант D помогает определить число действительных корней: D>0 — два, D=0 — один, D<0 — ни одного. Иногда быстрее разложить на множители. Произведение равно нулю, когда хотя бы один множитель равен нулю.','Квадрат теңдеуде x² бар және ax²+bx+c=0 түрінде жазылады, a≠0. D дискриминанты нақты түбір санын анықтайды: D>0 — екі, D=0 — бір, D<0 — жоқ. Кейде көбейткіштерге жіктеу жылдамырақ. Көбейтінді нөл болса, кемінде бір көбейткіш нөл.'),simpler:b('В x²=9 подходят 3 и −3, потому что оба квадрата равны 9.','x²=9 үшін 3 және −3 сәйкес: екеуінің де квадраты 9.'),formula:b('D=b²−4ac; x=(−b±√D)/(2a) при D≥0.','D=b²−4ac; D≥0 болса x=(−b±√D)/(2a).'),terms:b('Дискриминант — число b²−4ac; действительный корень — корень на числовой прямой.','Дискриминант — b²−4ac саны; нақты түбір — сан түзуіндегі түбір.'),error:b('Потерян отрицательный корень или неверно вычислен −b.','Теріс түбір жоғалған немесе −b қате есептелген.'),recap:b('Приведи к нулю, найди D, оба корня и проверь.','Нөлге келтір, D мен екі түбірді тап, тексер.'),build:(i,n,l)=>{const r=n+1,s=l===1?-r:n+3;verify(`quadratic ${i}`,equal(r*r-(r+s)*r+r*s,0)&&equal(s*s-(r+s)*s+r*s,0));return l===1?num(b(`Найди положительный корень x²=${r*r}.`,`x²=${r*r} теңдеуінің оң түбірін тап.`),r,[step(`Корни ±${r}.`,`Түбірлері ±${r}.`),step(`Положительный корень ${r}.`,`Оң түбірі ${r}.`)]):l===2?num(b(`Найди сумму корней x²−${r+s}x+${r*s}=0.`,`x²−${r+s}x+${r*s}=0 түбірлерінің қосындысын тап.`),r+s,[step(`Разложение: (x−${r})(x−${s})=0.`,`Жіктелуі: (x−${r})(x−${s})=0.`),step(`Корни ${r},${s}; сумма ${r+s}.`,`Түбірлері ${r},${s}; қосындысы ${r+s}.`)]):select(b(`Выбери все корни x²−${r+s}x+${r*s}=0.`,`x²−${r+s}x+${r*s}=0 теңдеуінің барлық түбірін таңда.`),[`${r}`,`${s}`],[`${-r}`,`${r}`,`${s}`,`${s+2}`],[step(`D=${(r-s)**2}; либо разложим на (x−${r})(x−${s}).`,`D=${(r-s)**2}; немесе (x−${r})(x−${s})-ке жіктейміз.`),step(`Оба корня ${r} и ${s} подходят при подстановке.`,`${r} және ${s} екі түбірі де орнына қойғанда сәйкес.`)])}});

add({id:'rational',module:'Уравнения',track:'profile',title:b('Рациональные уравнения','Рационал теңдеулер'),spec:'05',prerequisites:['quadratic','algebra-fractions'],goal:b('Убрать знаменатели без потери ограничений.','Шектеулерді жоғалтпай бөлімдерден құтылу.'),explanation:b('Рациональное уравнение содержит неизвестное в знаменателе. Сначала исключи все значения, обнуляющие знаменатель. Затем умножь обе части на общий знаменатель. Полученные корни обязательно сравни с первоначальными ограничениями.','Рационал теңдеуде белгісіз бөлімде болады. Алдымен бөлімді нөл ететін барлық мәнді алып таста. Содан кейін екі бөлікті ортақ бөлімге көбейт. Алынған түбірлерді бастапқы шектеулермен салыстыр.'),simpler:b('Если делим на x−2, число 2 брать нельзя ни до, ни после преобразования.','x−2-ге бөлсек, 2 санын түрлендіруге дейін де, кейін де алуға болмайды.'),formula:b('A(x)/B(x)=C(x) ⇒ A(x)=B(x)C(x), только при B(x)≠0.','A(x)/B(x)=C(x) ⇒ A(x)=B(x)C(x), тек B(x)≠0 кезінде.'),terms:b('Посторонний корень — результат преобразования, не подходящий исходному условию.','Бөгде түбір — түрлендіруден шыққан, бастапқы шартқа сай емес мән.'),error:b('Принят корень, обнуляющий исходный знаменатель.','Бастапқы бөлімді нөл ететін түбір қабылданған.'),recap:b('ОДЗ запиши первой строкой, проверь последней.','ММЖ-ны бірінші жолға жаз, соңында тексер.'),build:(i,n,l)=>l===1?num(b(`Реши ${2*(n+2)}/x=2.`,`${2*(n+2)}/x=2 теңдеуін шеш.`),n+2,[step('ОДЗ: x≠0.','ММЖ: x≠0.'),step(`2x=${2*(n+2)} ⇒ x=${n+2}, допустим.`,`2x=${2*(n+2)} ⇒ x=${n+2}, мүмкін.`)]):l===2?num(b(`Реши ${3*(n+2)}/(x−1)=3.`,`${3*(n+2)}/(x−1)=3 теңдеуін шеш.`),n+3,[step('ОДЗ: x≠1.','ММЖ: x≠1.'),step(`x−1=${n+2} ⇒ x=${n+3}.`,`x−1=${n+2} ⇒ x=${n+3}.`)]):num(b(`Реши (x²−${n*n})/(x−${n})=${2*n+4}.`,`(x²−${n*n})/(x−${n})=${2*n+4} теңдеуін шеш.`),n+4,[step(`ОДЗ: x≠${n}.`,`ММЖ: x≠${n}.`),step(`Сокращаем: x+${n}=${2*n+4}.`,`Қысқартамыз: x+${n}=${2*n+4}.`),step(`x=${n+4}; ограничение выполнено.`,`x=${n+4}; шектеу орындалған.`)])});

add({id:'irrational',module:'Уравнения',track:'profile',title:b('Иррациональные уравнения','Иррационал теңдеулер'),spec:'06',prerequisites:['radicals','quadratic'],goal:b('Решать уравнение с корнем и отсеивать посторонние решения.','Түбірі бар теңдеуді шешу және бөгде шешімдерді алып тастау.'),explanation:b('Иррациональное уравнение содержит неизвестное под корнем. Перед возведением в квадрат изолируй корень. Правая часть должна быть неотрицательной, потому что арифметический корень неотрицателен. Квадрат может сделать неверное равенство верным (например, −2 и 2 имеют одинаковый квадрат), поэтому проверка обязательна.','Иррационал теңдеуде белгісіз түбір астында болады. Квадраттау алдында түбірді жеке қалдыр. Арифметикалық түбір теріс емес болғандықтан, оң бөлік те теріс емес болуы керек. Квадраттау қате теңдікті дұрыс етуі мүмкін: −2 мен 2 квадраттары бірдей. Сондықтан тексеру міндетті.'),simpler:b('У √(x+1)=3 квадрат даёт x+1=9; затем проверяем √9=3.','√(x+1)=3 үшін квадраттау x+1=9 береді; кейін √9=3 тексереміз.'),formula:b('√g(x)=h(x) ⇔ g(x)=h(x)² и h(x)≥0.','√g(x)=h(x) ⇔ g(x)=h(x)² және h(x)≥0.'),terms:b('Иррациональное уравнение — уравнение с неизвестным под знаком корня.','Иррационал теңдеу — белгісізі түбір таңбасының астындағы теңдеу.'),error:b('После возведения в квадрат не проверен знак правой части.','Квадраттаудан кейін оң бөліктің таңбасы тексерілмеген.'),recap:b('Изолируй корень → ограничения → квадрат → проверка.','Түбірді жеке қалдыр → шектеулер → квадраттау → тексеру.'),build:(i,n,l)=>l===1?num(b(`Реши √(x+${n})=${n+2}.`,`√(x+${n})=${n+2} теңдеуін шеш.`),(n+2)**2-n,[step(`x+${n}=${(n+2)**2}.`,`x+${n}=${(n+2)**2}.`),step(`x=${(n+2)**2-n}; подстановка даёт положительный корень ${n+2}.`,`x=${(n+2)**2-n}; орнына қойғанда оң түбір ${n+2} шығады.`)]):l===2?num(b(`Реши √(2x+1)=${2*n+1}.`,`√(2x+1)=${2*n+1} теңдеуін шеш.`),(((2*n+1)**2)-1)/2,[step(`2x+1=${(2*n+1)**2}.`,`2x+1=${(2*n+1)**2}.`),step(`x=${(((2*n+1)**2)-1)/2}; проверяем исходный корень.`,`x=${(((2*n+1)**2)-1)/2}; бастапқы түбірді тексереміз.`)]):num(b(`Сколько действительных корней у √(x+${n})=−${n+1}?`,`√(x+${n})=−${n+1} теңдеуінің неше нақты түбірі бар?`),0,[step('Левая часть неотрицательна, правая отрицательна.','Сол бөлік теріс емес, оң бөлік теріс.'),step('Равенство невозможно: 0 корней.','Теңдік мүмкін емес: 0 түбір.')])});

add({id:'exponential',module:'Уравнения',track:'profile',title:b('Показательные уравнения','Көрсеткіштік теңдеулер'),spec:'07',prerequisites:['powers','quadratic'],goal:b('Сравнивать показатели при одинаковом основании и делать замену.','Бірдей негізде көрсеткіштерді салыстыру және алмастыру жасау.'),explanation:b('При a>0,a≠1 разные показатели дают разные значения aˣ. Поэтому у aᶠ=aᵍ можно приравнять f и g. Если встречаются 4ˣ и 2ˣ, положи t=2ˣ: 4ˣ=t². После решения учитывай t>0 и возвращайся к x.','a>0,a≠1 кезінде әртүрлі көрсеткіштер aˣ-тің әртүрлі мәндерін береді. Сондықтан aᶠ=aᵍ үшін f пен g тең. 4ˣ және 2ˣ кездессе, t=2ˣ деп ал: 4ˣ=t². Шешкен соң t>0 екенін ескеріп, x-ке қайт.'),simpler:b('2ˣ=16 превращается в 2ˣ=2⁴, значит x=4.','2ˣ=16 теңдеуі 2ˣ=2⁴ болады, демек x=4.'),formula:b('aᶠ⁽ˣ⁾=aᵍ⁽ˣ⁾ ⇔ f(x)=g(x), a>0,a≠1. t=aˣ>0.','aᶠ⁽ˣ⁾=aᵍ⁽ˣ⁾ ⇔ f(x)=g(x), a>0,a≠1. t=aˣ>0.'),terms:b('Показательное уравнение — неизвестное в показателе степени. Замена переменной — временная новая буква для повторяющегося выражения.','Көрсеткіштік теңдеу — белгісізі дәреже көрсеткішіндегі теңдеу. Айнымалыны алмастыру — қайталанатын өрнекке уақытша жаңа әріп енгізу.'),error:b('После замены забыто t>0 или возврат к x.','Алмастырудан кейін t>0 немесе x-ке қайту ұмытылған.'),recap:b('Приведи к одному основанию; при замене сохрани ограничения.','Бір негізге келтір; алмастырғанда шектеулерді сақта.'),build:(i,n,l)=>l===1?num(b(`Реши 2ˣ=${2**n}.`,`2ˣ=${2**n} теңдеуін шеш.`),n,[step(`Правая часть 2^${n}.`,`Оң бөлік 2^${n}.`),step(`x=${n}.`,`x=${n}.`)]):l===2?num(b(`Реши 3^(2x−1)=${3**(2*n+1)}.`,`3^(2x−1)=${3**(2*n+1)} теңдеуін шеш.`),n+1,[step(`2x−1=${2*n+1}.`,`2x−1=${2*n+1}.`),step(`x=${n+1}.`,`x=${n+1}.`)]):num(b(`Реши 4ˣ−${2**n}·2ˣ=0.`,`4ˣ−${2**n}·2ˣ=0 теңдеуін шеш.`),n,[step(`t=2ˣ>0; t²−${2**n}t=0.`,`t=2ˣ>0; t²−${2**n}t=0.`),step(`t=0 исключён; t=${2**n}.`,`t=0 алынып тасталады; t=${2**n}.`),step(`2ˣ=2^${n} ⇒ x=${n}.`,`2ˣ=2^${n} ⇒ x=${n}.`)])});

add({id:'log-equations',module:'Уравнения',track:'profile',title:b('Логарифмические уравнения','Логарифмдік теңдеулер'),spec:'07',prerequisites:['logarithms','linear'],goal:b('Решать логарифмическое уравнение с положительными аргументами.','Оң аргументтері бар логарифмдік теңдеуді шешу.'),explanation:b('Сначала выпиши положительность каждого аргумента. По определению logₐ g(x)=c равносильно g(x)=aᶜ на допустимых значениях. При одинаковых основаниях равные логарифмы имеют равные аргументы. Если объединяешь сумму в логарифм произведения, ограничения каждого исходного множителя сохраняются.','Алдымен әр аргументтің оң болуын жаз. Анықтама бойынша logₐ g(x)=c мүмкін мәндерде g(x)=aᶜ-ке мәндес. Бірдей негіздегі тең логарифмдердің аргументтері тең. Қосындыны көбейтіндінің логарифміне біріктірсең, әр бастапқы аргументтің шектеуі сақталады.'),simpler:b('log₂(x−1)=3 значит x−1=8, x=9; 9−1 положительно.','log₂(x−1)=3 болса x−1=8, x=9; 9−1 оң.'),formula:b('logₐ g(x)=c ⇔ g(x)=aᶜ, g(x)>0, a>0,a≠1.','logₐ g(x)=c ⇔ g(x)=aᶜ, g(x)>0, a>0,a≠1.'),terms:b('ОДЗ логарифма требует строго положительного аргумента, ноль исключён.','Логарифмнің ММЖ-сы қатаң оң аргументті талап етеді; нөл алынбайды.'),error:b('Уравнение решено без проверки положительности аргумента.','Теңдеу аргументтің оң екенін тексермей шешілген.'),recap:b('ОДЗ → определение или свойства → проверка каждого аргумента.','ММЖ → анықтама не қасиеттер → әр аргументті тексеру.'),build:(i,n,l)=>l===1?num(b(`Реши log₂ x=${n}.`,`log₂ x=${n} теңдеуін шеш.`),2**n,[step('ОДЗ x>0.','ММЖ x>0.'),step(`x=2^${n}=${2**n}.`,`x=2^${n}=${2**n}.`)]):l===2?num(b(`Реши log₂(x−${n})=3.`,`log₂(x−${n})=3 теңдеуін шеш.`),n+8,[step(`ОДЗ x>${n}.`,`ММЖ x>${n}.`),step(`x−${n}=8 ⇒ x=${n+8}.`,`x−${n}=8 ⇒ x=${n+8}.`)]):num(b(`Реши log₂(x−${n}) + log₂(x−${n})=4.`,`log₂(x−${n}) + log₂(x−${n})=4 теңдеуін шеш.`),n+4,[step(`ОДЗ x>${n}; 2log₂(x−${n})=4.`,`ММЖ x>${n}; 2log₂(x−${n})=4.`),step(`log₂(x−${n})=2 ⇒ x−${n}=4 ⇒ x=${n+4}.`,`log₂(x−${n})=2 ⇒ x−${n}=4 ⇒ x=${n+4}.`)])});

// Compact authoring helper: every topic still has its own explanation, formula, errors and tasks.
function core(id:string,module:string,track:Track,title:Bilingual,spec:string|null,prerequisites:string[],goal:Bilingual,explanation:Bilingual,formula:Bilingual,terms:Bilingual,error:Bilingual,build:TopicDef['build'],simpler?:Bilingual){
 add({id,module,track,title,spec,prerequisites,goal,explanation,formula,terms,error,build,
 simpler:simpler??b('Раздели задачу на маленькие действия. Назови известные величины, выбери правило и проверь один шаг за раз.','Есепті шағын қадамдарға бөл. Белгілі шамаларды ата, ережені таңда және әр қадамды жеке тексер.'),
 recap:b('Укажи условия формулы; выполни переходы по очереди; проверь исходное условие и единицы.','Формула шарттарын көрсет; қадамдарды ретімен орында; бастапқы шарт пен бірліктерді тексер.')});
}

core('trig-circle','Тригонометрия','profile',b('Окружность, углы и радианы','Шеңбер, бұрыштар және радиандар'),'03',['proportions'],b('Связать угол с координатами точки на единичной окружности.','Бұрышты бірлік шеңбер нүктесінің координаталарымен байланыстыру.'),
 b('На окружности радиуса 1 точка угла α имеет координаты (cos α,sin α). Угол отсчитывается от положительной оси x против часовой стрелки. Один полный оборот — 360° или 2π радиан. Синус — вертикальная координата, косинус — горизонтальная, тангенс — их отношение при cos α≠0. Знаки видны по четверти.','Радиусы 1 шеңберде α бұрышының нүктесі (cos α,sin α) координаталарына ие. Бұрыш оң x осінен сағат тіліне қарсы өлшенеді. Толық айналым — 360° немесе 2π радиан. Синус — тік, косинус — көлденең координата; cos α≠0 болса тангенс олардың қатынасы. Таңбалары ширектен көрінеді.'),
 b('180°=π рад; sin α=y, cos α=x; tan α=sin α/cos α (cos α≠0).','180°=π рад; sin α=y, cos α=x; tan α=sin α/cos α (cos α≠0).'),b('Радиан — угол с длиной дуги, равной радиусу. Единичная окружность имеет радиус 1.','Радиан — доғасының ұзындығы радиусқа тең бұрыш. Бірлік шеңбердің радиусы 1.'),b('Перепутаны sin и cos или градусы и радианы.','sin пен cos немесе градус пен радиан шатастырылған.'),
 (i,n,l)=>l===1?matching(b(`Сопоставь углы и радианы. Набор ${n}.`,`Бұрыштарды радиандармен сәйкестендір. ${n}-жинақ.`),[{left:`${30*n}°`,right:`${n}π/6`},{left:`${180+30*n}°`,right:`${6+n}π/6`},{left:`${360+30*n}°`,right:`${12+n}π/6`}],[step('Делим градусы на 180 и умножаем на π.','Градусты 180-ге бөліп, π-ге көбейтеміз.'),step('Углы, отличающиеся на 360°, различаются на 2π.','360°-қа ерекшеленетін бұрыштардың айырмасы 2π.')]):l===2?num(b(`Найди sin ${[0,30,90,150,270][n-1]}°.`,`sin ${[0,30,90,150,270][n-1]}° мәнін тап.`),[0,.5,1,.5,-1][n-1],[step('Синус — вертикальная координата точки окружности.','Синус — шеңбер нүктесінің тік координатасы.'),step(`Значение ${[0,.5,1,.5,-1][n-1]}.`,`Мәні ${[0,.5,1,.5,-1][n-1]}.`)]):select(b(`Для α=${100+10*n}° выбери верные утверждения.`,`α=${100+10*n}° үшін дұрыс тұжырымдарды таңда.`),['sin α>0','cos α<0','tan α<0'],['sin α>0','cos α>0','cos α<0','tan α<0'],[step('Это вторая четверть: x<0,y>0.','Бұл екінші ширек: x<0,y>0.'),step('Синус положителен, косинус и тангенс отрицательны.','Синус оң, косинус пен тангенс теріс.')]),
 b('Поставь точку на верх окружности: высота 1, значит sin 90°=1; горизонтальная координата 0, значит cos 90°=0.','Шеңбердің жоғарғы нүктесінде биіктік 1, демек sin 90°=1; көлденең координата 0, демек cos 90°=0.'));

core('trig-identities','Тригонометрия','profile',b('Тригонометрические тождества','Тригонометриялық тепе-теңдіктер'),'03',['trig-circle','identities'],b('Восстановить одну функцию угла по другой и упростить выражение.','Бір бұрыш функциясы арқылы екіншісін табу және өрнекті ықшамдау.'),
 b('По теореме Пифагора координаты точки окружности дают sin²α+cos²α=1. Если из квадрата извлекаем корень, знак выбирается по четверти. Делить на sin или cos можно только когда они не нулевые. Формулы двойного угла связывают α и 2α.','Пифагор теоремасы бойынша шеңбер нүктесінің координаталары sin²α+cos²α=1 береді. Квадраттан түбір алғанда таңба ширек бойынша таңдалады. sin немесе cos нөл емес болғанда ғана бөлеміз. Қос бұрыш формулалары α мен 2α-ны байланыстырады.'),
 b('sin²α+cos²α=1; sin2α=2sinαcosα; cos2α=cos²α−sin²α; 1+tan²α=1/cos²α при cosα≠0.','sin²α+cos²α=1; sin2α=2sinαcosα; cos2α=cos²α−sin²α; cosα≠0 болса 1+tan²α=1/cos²α.'),b('Тождество выполняется при каждом допустимом угле. Четверть определяет знак функции.','Тепе-теңдік әр мүмкін бұрышта орындалады. Ширек функцияның таңбасын анықтайды.'),b('Выбран положительный корень без учёта четверти.','Ширекті ескермей оң түбір таңдалған.'),
 (i,n,l)=>l===1?num(b(`Вычисли ${n}(sin²α+cos²α).`,`${n}(sin²α+cos²α) мәнін есепте.`),n,[step('Сумма квадратов равна 1.','Квадраттар қосындысы 1.'),step(`${n}·1=${n}.`,`${n}·1=${n}.`)]):l===2?num(b(`sin α=3/5, α — в первой четверти. Найди ${n}cos α.`,`sin α=3/5, α бірінші ширекте. ${n}cos α мәнін тап.`),.8*n,[step('cos²α=1−9/25=16/25.','cos²α=1−9/25=16/25.'),step(`cos α=4/5; ${n}cos α=${f(.8*n)}.`,`cos α=4/5; ${n}cos α=${f(.8*n)}.`)]):num(b(`sin α=3/5, cos α=−4/5. Найди ${n}sin 2α.`,`sin α=3/5, cos α=−4/5. ${n}sin 2α мәнін тап.`),-.96*n,[step('sin 2α=2·(3/5)·(−4/5)=−24/25.','sin 2α=2·(3/5)·(−4/5)=−24/25.'),step(`Умножаем на ${n}: ${f(-.96*n)}.`,`${n}-ге көбейтеміз: ${f(-.96*n)}.`)]));

core('trig-equations','Уравнения','profile',b('Тригонометрические уравнения','Тригонометриялық теңдеулер'),'06',['trig-identities'],b('Найти все корни на указанном промежутке и учесть период.','Көрсетілген аралықтағы барлық түбірді тауып, периодты ескеру.'),
 b('Один и тот же синус встречается в двух точках окружности, кроме крайних значений ±1. После полного оборота значения повторяются. Сначала найди точки на одном обороте, затем добавь целое число периодов. Если требуется промежуток, оставь только корни в нём; внимательно проверь включение границ.','Бірдей синус шеңбердің екі нүктесінде кездеседі, тек ±1 шеткі мәндерде бір нүкте. Толық айналымнан кейін мәндер қайталанады. Алдымен бір айналымдағы нүктелерді тап, кейін бүтін период қос. Аралық берілсе, тек сол аралықтағы түбірлерді қалдыр; шекаралардың кіруін тексер.'),
 b('sin x=sin α: x=α+2πk или x=π−α+2πk; cos x=cos α: x=±α+2πk; tan x=tan α: x=α+πk, k∈ℤ.','sin x=sin α: x=α+2πk немесе x=π−α+2πk; cos x=cos α: x=±α+2πk; tan x=tan α: x=α+πk, k∈ℤ.'),b('Период — величина, после прибавления которой функция повторяется; ℤ — целые числа.','Период — қосқанда функция қайталанатын шама; ℤ — бүтін сандар.'),b('Потеряна вторая ветвь синуса или добавлены корни вне интервала.','Синустың екінші тармағы жоғалған немесе аралықтан тыс түбір қосылған.'),
 (i,n,l)=>l===1?num(b(`Сколько корней sin x=${[0,.5,1,-.5,-1][n-1]} на [0;2π)?`,`[0;2π) аралығында sin x=${[0,.5,1,-.5,-1][n-1]} теңдеуінің неше түбірі бар?`),[2,2,1,2,1][n-1],[step('Пересекаем окружность горизонтальной линией нужной высоты.','Шеңберді керек биіктіктегі көлденең сызықпен қиамыз.'),step(`Точек ${[2,2,1,2,1][n-1]}; 2π исключено.`,`Нүкте саны ${[2,2,1,2,1][n-1]}; 2π кірмейді.`)]):l===2?num(b(`Найди наименьший положительный корень sin(x−${n}°)=1/2 в градусах.`,`sin(x−${n}°)=1/2 ең кіші оң түбірін градуспен тап.`),30+n,[step('x−n°=30°+360°k или 150°+360°k.','x−n°=30°+360°k немесе 150°+360°k.'),step(`Первый положительный x=${30+n}°.`,`Бірінші оң x=${30+n}°.`)],'°'):num(b(`Сколько корней sin(${n+1}x)=0 на [0;2π)?`,`[0;2π) аралығында sin(${n+1}x)=0 теңдеуінің неше түбірі бар?`),2*(n+1),[step(`${n+1}x=πk ⇒ x=πk/${n+1}.`,`${n+1}x=πk ⇒ x=πk/${n+1}.`),step(`0≤k<${2*(n+1)}: всего ${2*(n+1)} целых k.`,`0≤k<${2*(n+1)}: барлығы ${2*(n+1)} бүтін k.`)]));

core('linear-systems','Системы уравнений','profile',b('Линейные системы: два неизвестных','Сызықтық жүйелер: екі белгісіз'),'08',['linear'],b('Решать систему подстановкой или сложением и проверять пару.','Жүйені орнына қою не қосу тәсілімен шешіп, жұпты тексеру.'),
 b('Система требует, чтобы несколько равенств выполнялись одновременно. Решение с двумя неизвестными — пара (x,y). Подстановка заменяет одно неизвестное выражением из другого уравнения. Метод сложения устраняет переменную, если её коэффициенты противоположны. Проверяй оба равенства.','Жүйедегі бірнеше теңдік бір уақытта орындалуы тиіс. Екі белгісіздің шешімі — (x,y) жұбы. Орнына қою тәсілінде бір белгісізді басқа теңдеуден алынған өрнекпен алмастырамыз. Қосу тәсілі қарама-қарсы коэффициенттерді жояды. Екі теңдікті де тексер.'),
 b('x+y=S, x−y=D ⇒ x=(S+D)/2, y=(S−D)/2.','x+y=S, x−y=D ⇒ x=(S+D)/2, y=(S−D)/2.'),b('Система — условия, выполняющиеся одновременно. Подстановка — замена равным выражением.','Жүйе — бір уақытта орындалатын шарттар. Орнына қою — тең өрнекпен алмастыру.'),b('Проверено только одно уравнение.','Тек бір теңдеу тексерілген.'),
 (i,n,l)=>{const x=n+l,y=n+1,S=x+y,D=x-y;verify(`system ${i}`,equal(x+y,S)&&equal(x-y,D));return num(b(`Система x+y=${S}, x−y=${D}. Найди ${l===1?'x':l===2?'y':'xy'}.`,`x+y=${S}, x−y=${D} жүйесінде ${l===1?'x':l===2?'y':'xy'} тап.`),l===1?x:l===2?y:x*y,[step(`Складываем: 2x=${S+D}, x=${x}.`,`Қосамыз: 2x=${S+D}, x=${x}.`),step(`Подставляем: y=${S}−${x}=${y}.`,`Орнына қоямыз: y=${S}−${x}=${y}.`),step(l===3?`xy=${x*y}.`:`Проверяем ${x}+${y}=${S} и ${x}−${y}=${D}.`,l===3?`xy=${x*y}.`:`${x}+${y}=${S} және ${x}−${y}=${D} тексереміз.`)])});

core('nonlinear-systems','Системы уравнений','profile',b('Нелинейные системы','Сызықтық емес жүйелер'),'08',['quadratic','linear-systems'],b('Найти несколько пар решений и связать сумму с произведением.','Бірнеше шешім жұбын табу және қосынды мен көбейтіндіні байланыстыру.'),
 b('Если есть квадрат или произведение неизвестных, система нелинейная. Из x+y=S выражаем y=S−x и подставляем во второе равенство. У квадратного уравнения может быть два корня, и каждому нужен свой y. Для суммы и произведения x,y — корни t²−St+P=0.','Белгісіздердің квадраты не көбейтіндісі бар жүйе сызықтық емес. x+y=S теңдеуінен y=S−x шығарып, екінші теңдікке қоямыз. Квадрат теңдеудің екі түбірі болуы мүмкін, әрқайсысына өз y мәні керек. Қосынды мен көбейтінді үшін x,y — t²−St+P=0 түбірлері.'),
 b('x+y=S, xy=P ⇒ t²−St+P=0; x²+y²=S²−2P.','x+y=S, xy=P ⇒ t²−St+P=0; x²+y²=S²−2P.'),b('Нелинейность означает, что неизвестные не входят только в первой степени раздельно.','Сызықтық емес жүйеде белгісіздер тек бөлек бірінші дәрежеде ғана болмайды.'),b('Найдена одна пара, хотя переставленная пара тоже подходит.','Бір жұп қана табылған, бірақ орындары ауысқан жұп та сәйкес.'),
 (i,n,l)=>{const x=n+1,y=n+3;verify(`nonlinear ${i}`,equal(x+y,2*n+4)&&equal(x*y,(n+1)*(n+3)));return num(b(`Дано x+y=${x+y}, xy=${x*y}. Найди ${l===1?'x²+y²':l===2?'большее из x,y':'(x−y)²'}.`,`x+y=${x+y}, xy=${x*y} берілген. ${l===1?'x²+y²':l===2?'x,y-дің үлкенін':'(x−y)²'} тап.`),l===1?x*x+y*y:l===2?y:(x-y)**2,[step(`x,y — корни t²−${x+y}t+${x*y}=0: ${x} и ${y}.`,`x,y — t²−${x+y}t+${x*y}=0 түбірлері: ${x} және ${y}.`),step(l===1?`${x}²+${y}²=${x*x+y*y}.`:l===2?`Большее число ${y}.`:`(${x}−${y})²=4.`,l===1?`${x}²+${y}²=${x*x+y*y}.`:l===2?`Үлкен сан ${y}.`:`(${x}−${y})²=4.`)])});

core('advanced-systems','Системы уравнений','profile',b('Системы с корнями, степенями и тригонометрией','Түбірлі, дәрежелі және тригонометриялық жүйелер'),'09',['exponential','log-equations','irrational','trig-equations'],b('Соединить разные типы уравнений и проверить общие решения.','Әртүрлі теңдеулерді біріктіріп, ортақ шешімдерді тексеру.'),
 b('Каждое преобразование системы должно учитывать область определения. В степенных системах удобно ввести положительные t=2ˣ,u=2ʸ. Для логарифмов сначала нужны положительные аргументы. Для корней — неотрицательность обеих сторон перед квадратом. В тригонометрии одно уравнение выбирает точки окружности, другое оставляет нужные.','Жүйенің әр түрлендіруінде анықталу облысы ескеріледі. Дәрежелі жүйеде оң t=2ˣ,u=2ʸ алмастыруы ыңғайлы. Логарифмге оң аргумент қажет. Түбірде квадраттау алдында екі жағы да теріс емес болуы керек. Тригонометрияда бірінші теңдеу нүктелерді, екіншісі сәйкесін таңдайды.'),
 b('2ˣ·2ʸ=2ˣ⁺ʸ; log₂x+log₂y=log₂(xy), x,y>0; sin²x+cos²x=1.','2ˣ·2ʸ=2ˣ⁺ʸ; log₂x+log₂y=log₂(xy), x,y>0; sin²x+cos²x=1.'),b('Общий корень системы удовлетворяет каждому исходному уравнению.','Жүйенің ортақ түбірі әр бастапқы теңдеуге сәйкес келеді.'),b('Корень одного уравнения принят без проверки второго и ОДЗ.','Бір теңдеудің түбірі екіншісі мен ММЖ тексерілмей қабылданған.'),
 (i,n,l)=>i%4===0?num(b(`Система 2ˣ=${2**n}, 2ʸ=4. Найди x+y.`,`2ˣ=${2**n}, 2ʸ=4 жүйесінде x+y тап.`),n+2,[step(`x=${n}, y=2 по равенству оснований.`,`Негіздер тең болғандықтан x=${n}, y=2.`),step(`x+y=${n+2}.`,`x+y=${n+2}.`)]):i%4===1?num(b(`Система log₂x=${n}, log₂y=1. Найди xy.`,`log₂x=${n}, log₂y=1 жүйесінде xy тап.`),2**(n+1),[step(`x=2^${n}=${2**n}>0, y=2>0.`,`x=2^${n}=${2**n}>0, y=2>0.`),step(`xy=${2**(n+1)}.`,`xy=${2**(n+1)}.`)]):i%4===2?num(b(`Система √(x+${n})=${n+1}, x+y=${(n+1)**2}. Найди y.`,`√(x+${n})=${n+1}, x+y=${(n+1)**2} жүйесінде y тап.`),n,[step(`x=${(n+1)**2-n}; подкоренное положительно.`,`x=${(n+1)**2-n}; түбір астындағы сан оң.`),step(`y=${(n+1)**2}−${(n+1)**2-n}=${n}.`,`y=${(n+1)**2}−${(n+1)**2-n}=${n}.`)]):num(b(`Система sin x=0, cos x=1. Сколько корней x на [0;${2*(n+l)}π)?`,`sin x=0, cos x=1 жүйесінің [0;${2*(n+l)}π) аралығында неше x түбірі бар?`),n+l,[step('Совместно получаем x=2πk.','Бірге x=2πk аламыз.'),step(`k=0,…,${n+l-1}; всего ${n+l}.`,`k=0,…,${n+l-1}; барлығы ${n+l}.`)]));

core('linear-inequalities','Неравенства','profile',b('Линейные неравенства','Сызықтық теңсіздіктер'),'10',['linear','negatives'],b('Найти диапазон решений и правильно менять знак.','Шешімдер аралығын табу және таңбаны дұрыс өзгерту.'),b('Неравенство сравнивает величины. Прибавление одинакового числа сохраняет знак. Умножение или деление на положительное число сохраняет знак, на отрицательное — меняет его: −2x<6 означает x>−3. Строгое неравенство исключает границу.','Теңсіздік шамаларды салыстырады. Бірдей санды қосу таңбаны сақтайды. Оң санға көбейту не бөлу таңбаны сақтайды, теріс санға — өзгертеді: −2x<6 болса x>−3. Қатаң теңсіздік шекараны қоспайды.'),b('ax<b: x<b/a при a>0; x>b/a при a<0.','ax<b: a>0 болса x<b/a; a<0 болса x>b/a.'),b('Строгое: <,>; нестрогое: ≤,≥. Интервал — часть числовой прямой.','Қатаң: <,>; қатаң емес: ≤,≥. Аралық — сан түзуінің бөлігі.'),b('При делении на отрицательное число не изменён знак.','Теріс санға бөлгенде таңба өзгертілмеген.'),
 (i,n,l)=>l===1?select(b(`Какие значения решают x+2>${n+2}?`,`Қай мәндер x+2>${n+2} теңсіздігін қанағаттандырады?`),[`${n+1}`,`${n+2}`],[`${n-1}`,`${n}`,`${n+1}`,`${n+2}`],[step(`Вычитаем 2: x>${n}.`,`2 азайтамыз: x>${n}.`),step('Равенство границе не подходит.','Шекараға тең мән сәйкес емес.')]):l===2?select(b(`Выбери решения −2x≤−${2*n}.`,`−2x≤−${2*n} шешімдерін таңда.`),[`${n}`,`${n+2}`],[`${n-2}`,`${n-1}`,`${n}`,`${n+2}`],[step(`Делим на −2 и меняем знак: x≥${n}.`,`−2-ге бөліп, таңбаны ауыстырамыз: x≥${n}.`),step('Граница включена.','Шекара кіреді.')]):num(b(`Сколько целых x удовлетворяют 0≤x<${n+3}?`,`0≤x<${n+3} шартын неше бүтін x қанағаттандырады?`),n+3,[step(`Целые 0,1,…,${n+2}.`,`Бүтін сандар 0,1,…,${n+2}.`),step(`От 0 до ${n+2} включительно ${n+3} чисел.`,`0-ден ${n+2}-ге дейін ${n+3} сан бар.`)]));

core('quadratic-inequalities','Неравенства','profile',b('Квадратные неравенства и интервалы','Квадрат теңсіздіктер және аралықтар'),'10',['quadratic','linear-inequalities'],b('Определить знаки квадратного выражения между корнями и вне их.','Квадрат өрнектің түбірлер арасындағы және сыртындағы таңбасын анықтау.'),b('Разложи выражение на множители и отметь корни на прямой. Между соседними корнями знак постоянен: проверь одно число из каждого промежутка. Если коэффициент x² положителен, парабола выше нуля снаружи двух корней, ниже между ними. При ≤ или ≥ корни включаются.','Өрнекті көбейткіштерге жіктеп, түбірлерді түзуге белгіле. Көршілес түбірлер арасындағы таңба тұрақты: әр аралықтан бір сан тексер. x² коэффициенті оң болса, парабола екі түбірдің сыртында нөлден жоғары, арасында төмен. ≤ немесе ≥ кезінде түбірлер кіреді.'),b('(x−a)(x−b)≤0 ⇔ a≤x≤b при a<b.','a<b кезінде (x−a)(x−b)≤0 ⇔ a≤x≤b.'),b('Метод интервалов — проверка знаков на промежутках между нулями.','Аралықтар әдісі — нөлдердің арасындағы таңбаларды тексеру.'),b('Выбраны внешние интервалы вместо внутреннего.','Ішкі аралықтың орнына сыртқы аралықтар таңдалған.'),
 (i,n,l)=>{const a=n,bv=n+l+2;return l===1?num(b(`Сколько целых решений (x−${a})(x−${bv})≤0?`,`(x−${a})(x−${bv})≤0 теңсіздігінің неше бүтін шешімі бар?`),bv-a+1,[step(`Решение [${a};${bv}].`,`Шешімі [${a};${bv}].`),step(`Количество ${bv}−${a}+1=${bv-a+1}.`,`Саны ${bv}−${a}+1=${bv-a+1}.`)]):select(b(`Выбери все решения (x−${a})(x−${bv})${l===2?'<':'>'}0.`,`(x−${a})(x−${bv})${l===2?'<':'>'}0 теңсіздігінің барлық шешімін таңда.`),l===2?[`${a+1}`,`${bv-1}`]:[`${a-1}`,`${bv+1}`],[`${a-1}`,`${a+1}`,`${bv-1}`,`${bv+1}`],[step(`Корни ${a},${bv}; между ними знак −, снаружи +.`,`Түбірлері ${a},${bv}; арасында таңба −, сыртында +.`),step(l===2?'Нужен внутренний открытый интервал.':'Нужны внешние интервалы.',l===2?'Ішкі ашық аралық қажет.':'Сыртқы аралықтар қажет.')])});

core('rational-inequalities','Неравенства','profile',b('Рациональные неравенства','Рационал теңсіздіктер'),'10',['rational','quadratic-inequalities'],b('Различать ноль числителя и запрещённую точку знаменателя.','Алымның нөлі мен бөлімнің тыйым салынған нүктесін ажырату.'),b('У дроби знак зависит от обоих множителей. Отметь нули числителя и знаменателя, проверь знаки интервалов. Знаменатель никогда не может стать нулём, даже если неравенство нестрогое. Не умножай на выражение неизвестного знака: оно может изменить знак сравнения.','Бөлшектің таңбасы екі көбейткішке тәуелді. Алым мен бөлім нөлдерін белгілеп, аралық таңбаларын тексер. Теңсіздік қатаң емес болса да, бөлім нөл болмайды. Таңбасы белгісіз өрнекке көбейтпе: ол салыстыру таңбасын өзгертуі мүмкін.'),b('(x−a)/(x−b)>0 при a<b: x<a или x>b; x=b исключено.','a<b үшін (x−a)/(x−b)>0: x<a немесе x>b; x=b алынбайды.'),b('Полюс — точка, где знаменатель равен нулю и выражение не определено.','Полюс — бөлім нөлге тең болып, өрнек анықталмайтын нүкте.'),b('Полюс включён в ответ либо умножение сделано без учёта знака.','Полюс жауапқа қосылған немесе көбейткенде таңба ескерілмеген.'),
 (i,n,l)=>l===1?num(b(`Какое значение исключено из (x−${n})/(x−${n+3})?`,`(x−${n})/(x−${n+3}) өрнегінен қай мән шығарылады?`),n+3,[step('Приравниваем знаменатель к нулю.','Бөлімді нөлге теңестіреміз.'),step(`x=${n+3} запрещено.`,`x=${n+3} тыйым салынған.`)]):select(b(`Выбери решения (x−${n})/(x−${n+3})${l===2?'≤':'>'}0.`,`(x−${n})/(x−${n+3})${l===2?'≤':'>'}0 шешімдерін таңда.`),l===2?[`${n}`,`${n+1}`]:[`${n-1}`,`${n+4}`],[`${n-1}`,`${n}`,`${n+1}`,`${n+4}`],[step(`Точки ${n},${n+3}: знаки +,−,+.`,`${n},${n+3} нүктелері: таңбалар +,−,+.`),step(l===2?`Берём [${n};${n+3}), полюс исключён.`:'Берём внешние открытые интервалы.',l===2?`[${n};${n+3}) аламыз, полюс кірмейді.`:'Сыртқы ашық аралықтарды аламыз.') ]));

core('advanced-inequalities','Неравенства','profile',b('Неравенства со степенями, логарифмами и корнями','Дәрежелі, логарифмді және түбірлі теңсіздіктер'),'10',['exponential','logarithms','trig-circle','radicals'],b('Использовать монотонность и ограничения, читать тригонометрическое неравенство на окружности.','Монотондылық пен шектеулерді қолдану, тригонометриялық теңсіздікті шеңберден оқу.'),b('Функции aˣ и logₐx возрастают при a>1, убывают при 0<a<1. В убывающем случае сравнение показателей меняет знак. Логарифм требует x>0. У √g(x)<c сначала c>0 и g(x)≥0, затем квадрат. sin x>0 означает верхнюю половину окружности.','aˣ және logₐx функциялары a>1 кезінде өседі, 0<a<1 кезінде кемиді. Кемитін жағдайда көрсеткіштерді салыстыру таңбаны өзгертеді. Логарифм үшін x>0. √g(x)<c үшін алдымен c>0 және g(x)≥0, кейін квадраттаймыз. sin x>0 — шеңбердің жоғарғы жартысы.'),b('a>1: aᵘ>aᵛ ⇔ u>v; 0<a<1: u<v. logₐx требует x>0. √g<c ⇔ 0≤g<c² (c>0).','a>1: aᵘ>aᵛ ⇔ u>v; 0<a<1: u<v. logₐx үшін x>0. √g<c ⇔ 0≤g<c² (c>0).'),b('Монотонность — устойчивое возрастание или убывание функции.','Монотондылық — функцияның тұрақты өсуі не кемуі.'),b('Не изменён знак при основании меньше 1 или забыта ОДЗ.','Негіз 1-ден кіші болғанда таңба өзгертілмеген немесе ММЖ ұмытылған.'),
 (i,n,l)=>i%4===0?select(b(`Выбери решения (1/2)ˣ>(1/2)^${n}.`,`(1/2)ˣ>(1/2)^${n} шешімдерін таңда.`),[`${n-2}`,`${n-1}`],[`${n-2}`,`${n-1}`,`${n}`,`${n+1}`],[step('Основание 1/2 меньше 1: функция убывает.','1/2 негізі 1-ден кіші: функция кемиді.'),step(`Поэтому x<${n}.`,`Сондықтан x<${n}.`)]):i%4===1?num(b(`Наименьшее целое x, для которого log₂x>${n}?`,`log₂x>${n} болатын ең кіші бүтін x неше?`),2**n+1,[step(`x>2^${n}=${2**n}.`,`x>2^${n}=${2**n}.`),step(`Следующее целое ${2**n+1}.`,`Келесі бүтін сан ${2**n+1}.`)]):i%4===2?num(b(`Сколько целых x решают √x<${n+1}?`,`√x<${n+1} теңсіздігін неше бүтін x шешеді?`),(n+1)**2,[step(`ОДЗ x≥0; после квадрата x<${(n+1)**2}.`,`ММЖ x≥0; квадраттаудан кейін x<${(n+1)**2}.`),step(`От 0 до ${(n+1)**2-1}: ${(n+1)**2} чисел.`,`0-ден ${(n+1)**2-1}-ге дейін ${(n+1)**2} сан.`)]):select(b(`При α=${n*10}° какие функции положительны?`,`α=${n*10}° кезінде қай функциялар оң?`),['sin α','cos α','tan α'],['sin α','cos α','tan α','−sin α'],[step('Угол в первой четверти.','Бұрыш бірінші ширекте.'),step('Три функции положительны, отрицательный синус отрицателен.','Үш функция оң, теріс синус теріс.') ]));

core('inequality-systems','Системы неравенств','profile',b('Системы неравенств: пересечение','Теңсіздіктер жүйесі: қиылысу'),'11',['rational-inequalities','advanced-inequalities'],b('Найти значения, удовлетворяющие всем ограничениям сразу.','Барлық шектеулерді бір уақытта қанағаттандыратын мәндерді табу.'),b('В системе нужен общий участок решений. Каждое неравенство реши отдельно, изобрази промежутки на одной прямой и возьми пересечение. Объединение подходит для слова «или», пересечение — для «и». Строгая граница хотя бы одного условия делает итоговую границу открытой.','Жүйеде шешімдердің ортақ бөлігі қажет. Әр теңсіздікті жеке шешіп, бір түзуге белгіле және қиылысуын ал. «Немесе» үшін бірігу, «және» үшін қиылысу керек. Кемінде бір шарттың қатаң шекарасы соңғы шекараны ашық етеді.'),b('x∈A и x∈B ⇒ x∈A∩B. Для [a;b]∩[c;d]: нижняя граница max(a,c), верхняя min(b,d).','x∈A және x∈B ⇒ x∈A∩B. [a;b]∩[c;d] үшін төменгі шекара max(a,c), жоғарғысы min(b,d).'),b('Пересечение — элементы, принадлежащие обоим множествам.','Қиылысу — екі жиынға да кіретін элементтер.'),b('Взято объединение вместо общего участка.','Ортақ бөліктің орнына бірігу алынған.'),
 (i,n,l)=>l===1?num(b(`Сколько целых решений системы x≥${n}, x<${n+4}?`,`x≥${n}, x<${n+4} жүйесінің неше бүтін шешімі бар?`),4,[step(`Общий промежуток [${n};${n+4}).`,`Ортақ аралық [${n};${n+4}).`),step(`Числа ${n},${n+1},${n+2},${n+3}.`,`Сандар ${n},${n+1},${n+2},${n+3}.`)]):l===2?num(b(`Сколько целых x: (x−${n})(x−${n+5})≤0 и x>${n+1}?`,`(x−${n})(x−${n+5})≤0 және x>${n+1} шарттарына неше бүтін x сай?`),4,[step(`Первая часть [${n};${n+5}], вторая (${n+1};∞).`,`Біріншісі [${n};${n+5}], екіншісі (${n+1};∞).`),step(`Пересечение (${n+1};${n+5}], 4 целых.`,`Қиылысуы (${n+1};${n+5}], 4 бүтін сан.`)]):num(b(`Наименьшее целое решение log₂x>${n} и 2ˣ≥2^${n+2}?`,`log₂x>${n} және 2ˣ≥2^${n+2} жүйесінің ең кіші бүтін шешімі?`),Math.max(2**n+1,n+2),[step(`Первое: x>${2**n}; второе: x≥${n+2}.`,`Біріншісі: x>${2**n}; екіншісі: x≥${n+2}.`),step(`Минимальное целое max(${2**n+1},${n+2})=${Math.max(2**n+1,n+2)}.`,`Ең кіші бүтін max(${2**n+1},${n+2})=${Math.max(2**n+1,n+2)}.`)]));

core('arithmetic','Последовательности','profile',b('Арифметическая прогрессия','Арифметикалық прогрессия'),'12',['linear'],b('Найти член и сумму последовательности с постоянной разностью.','Айырымы тұрақты тізбектің мүшесін және қосындысын табу.'),b('Последовательность — числа с номерами. В арифметической прогрессии каждый следующий член больше предыдущего на одну и ту же разность d (она может быть отрицательной). От первого до n-го делаем n−1 шагов. Для суммы пары первого и последнего, второго и предпоследнего имеют одинаковую сумму.','Тізбек — нөмірленген сандар. Арифметикалық прогрессияда әр келесі мүше алдыңғысынан бірдей d айырымға өзгереді (ол теріс болуы мүмкін). Бірінші мүшеден n-шіге n−1 қадам жасалады. Қосындыда бірінші мен соңғы, екінші мен соңғының алдындағы жұптар бірдей қосынды береді.'),b('aₙ=a₁+(n−1)d; Sₙ=n(a₁+aₙ)/2. n — номер/число членов, d — разность.','aₙ=a₁+(n−1)d; Sₙ=n(a₁+aₙ)/2. n — нөмір/мүшелер саны, d — айырым.'),b('Член последовательности — число на определённом месте; разность — прибавка между соседями.','Тізбектің мүшесі — белгілі орындағы сан; айырым — көршілес мүшелердің өзгерісі.'),b('Использовано n шагов вместо n−1.','n−1 орнына n қадам алынған.'),
 (i,n,l)=>l===1?num(b(`a₁=${n}, d=3. Найди a₅.`,`a₁=${n}, d=3. a₅ тап.`),n+12,[step('От первого до пятого четыре шага.','Біріншіден бесіншіге төрт қадам.'),step(`a₅=${n}+4·3=${n+12}.`,`a₅=${n}+4·3=${n+12}.`)]):l===2?matching(b(`При a₁=${n}, d=2 сопоставь номер и член.`,`a₁=${n}, d=2 болғанда нөмір мен мүшені сәйкестендір.`),[{left:'a₂',right:`${n+2}`},{left:'a₄',right:`${n+6}`},{left:'a₆',right:`${n+10}`}],[step('aₖ=a₁+(k−1)d.','aₖ=a₁+(k−1)d.'),step(`Прибавляем 2,6,10 к первому члену ${n}.`,`Бірінші ${n} мүшеге 2,6,10 қосамыз.`)]):num(b(`Сумма первых 10 членов, если a₁=${n}, d=2?`,`a₁=${n}, d=2 болса, алғашқы 10 мүшенің қосындысы неше?`),10*n+90,[step(`a₁₀=${n}+9·2=${n+18}.`,`a₁₀=${n}+9·2=${n+18}.`),step(`S₁₀=10(${n}+${n+18})/2=${10*n+90}.`,`S₁₀=10(${n}+${n+18})/2=${10*n+90}.`)]));

core('geometric','Последовательности','profile',b('Геометрическая прогрессия','Геометриялық прогрессия'),'12',['powers','arithmetic'],b('Найти член и сумму последовательности с постоянным множителем.','Көбейткіші тұрақты тізбектің мүшесін және қосындысын табу.'),b('В геометрической прогрессии следующий член получается умножением на q. Знаменатель прогрессии q — отношение соседних ненулевых членов. При q=2 величина удваивается; при q=1/2 уменьшается вдвое. Первый член до n-го умножается на q ровно n−1 раз.','Геометриялық прогрессияда келесі мүше q-ға көбейту арқылы табылады. Прогрессияның еселігі q — көршілес нөл емес мүшелердің қатынасы. q=2 болса шама екі еселенеді, q=1/2 болса жартысына азаяды. Бірінші мүшеден n-шіге дейін q-ға n−1 рет көбейтеміз.'),b('bₙ=b₁qⁿ⁻¹; Sₙ=b₁(qⁿ−1)/(q−1), q≠1; при q=1: Sₙ=nb₁.','bₙ=b₁qⁿ⁻¹; Sₙ=b₁(qⁿ−1)/(q−1), q≠1; q=1 болса Sₙ=nb₁.'),b('Знаменатель прогрессии q — множитель перехода, не знаменатель дроби.','Прогрессия еселігі q — келесі мүшеге өту көбейткіші, бөлшектің бөлімі емес.'),b('Разность применена вместо отношения или не учтён случай q=1.','Қатынас орнына айырым қолданылған немесе q=1 жағдайы ескерілмеген.'),
 (i,n,l)=>l===1?num(b(`b₁=${n}, q=2. Найди b₄.`,`b₁=${n}, q=2. b₄ тап.`),8*n,[step('Три умножения на 2.','2-ге үш рет көбейту.'),step(`b₄=${n}·2³=${8*n}.`,`b₄=${n}·2³=${8*n}.`)]):l===2?num(b(`b₁=${16*n}, q=1/2. Найди b₅.`,`b₁=${16*n}, q=1/2. b₅ тап.`),n,[step('Четыре умножения на 1/2 дают 1/16.','1/2-ге төрт рет көбейту 1/16 береді.'),step(`${16*n}/16=${n}.`,`${16*n}/16=${n}.`)]):num(b(`b₁=${n}, q=3. Найди сумму первых 4 членов.`,`b₁=${n}, q=3. Алғашқы 4 мүшенің қосындысын тап.`),40*n,[step(`Члены ${n},${3*n},${9*n},${27*n}.`,`Мүшелері ${n},${3*n},${9*n},${27*n}.`),step(`S₄=${n}(3⁴−1)/(3−1)=${40*n}.`,`S₄=${n}(3⁴−1)/(3−1)=${40*n}.`)]));

core('derivative','Математический анализ','profile',b('Производная и скорость изменения','Туынды және өзгеру жылдамдығы'),'13',['functions','powers'],b('Найти производную и мгновенную скорость изменения.','Туындыны және лездік өзгеру жылдамдығын табу.'),b('Производная f′(x) показывает, как быстро меняется f около выбранного x. На графике это наклон касательной — прямой, которая касается кривой и показывает её местное направление. Если s(t) — путь, s′(t) — мгновенная скорость. Производная постоянного числа равна нулю.','f′(x) туындысы таңдалған x маңында f қаншалықты тез өзгеретінін көрсетеді. Графикте бұл жанаманың көлбеулігі — қисыққа тиіп, жергілікті бағытын көрсететін түзу. s(t) жол болса, s′(t) — лездік жылдамдық. Тұрақты санның туындысы нөл.'),b('(xⁿ)′=nxⁿ⁻¹; (kf+g)′=kf′+g′; (sin x)′=cos x; (cos x)′=−sin x (радианы).','(xⁿ)′=nxⁿ⁻¹; (kf+g)′=kf′+g′; (sin x)′=cos x; (cos x)′=−sin x (радиан).'),b('Касательная — прямая местного направления; производная — скорость изменения.','Жанама — жергілікті бағыттың түзуі; туынды — өзгеру жылдамдығы.'),b('Коэффициент степени потерян или показатель не уменьшен на 1.','Дәреже коэффициенті жоғалған немесе көрсеткіш 1-ге азаймаған.'),
 (i,n,l)=>l===1?expr(b(`Найди производную ${n}x²+3.`,`${n}x²+3 туындысын тап.`),`${2*n}*x`,[step('(x²)′=2x, (3)′=0.','(x²)′=2x, (3)′=0.'),step(`f′(x)=${2*n}x.`,`f′(x)=${2*n}x.`)],b('Постоянное число не меняется.','Тұрақты сан өзгермейді.')):l===2?num(b(`f(x)=${n}x³−2x. Найди f′(2).`,`f(x)=${n}x³−2x. f′(2) тап.`),12*n-2,[step(`f′(x)=${3*n}x²−2.`,`f′(x)=${3*n}x²−2.`),step(`f′(2)=${3*n}·4−2=${12*n-2}.`,`f′(2)=${3*n}·4−2=${12*n-2}.`)]):num(b(`Путь s(t)=${n}t²+3t (м), t в секундах. Скорость при t=4?`,`Жол s(t)=${n}t²+3t (м), t секундпен. t=4 кезіндегі жылдамдық?`),8*n+3,[step(`v(t)=s′(t)=${2*n}t+3.`,`v(t)=s′(t)=${2*n}t+3.`),step(`v(4)=${8*n+3} м/с.`,`v(4)=${8*n+3} м/с.`)],'м/с'));

core('extrema','Математический анализ','profile',b('Исследование функций и экстремумы','Функцияны зерттеу және экстремумдар'),'13',['derivative','quadratic-inequalities'],b('Найти точки минимума, максимум и промежутки изменения функции.','Минимум нүктелерін, максимумды және функцияның өзгеру аралықтарын табу.'),b('При f′>0 функция возрастает, при f′<0 убывает. Критическая точка — место, где производная ноль или не существует внутри области. Нулевой производной недостаточно: для минимума знак должен смениться с − на +, для максимума с + на −. На замкнутом отрезке сравни также значения на концах.','f′>0 болса функция өседі, f′<0 болса кемиді. Сындық нүктеде облыс ішінде туынды нөлге тең не жоқ. Нөл туындының өзі жеткіліксіз: минимумда таңба −-тен +-ке, максимумда +-тен −-ке ауысады. Тұйық кесіндіде шеткі мәндерді де салыстыр.'),b('f′(x₀)=0 — кандидат. На [a;b] сравнить f(a),f(b) и значения в критических точках.','f′(x₀)=0 — үміткер. [a;b] ішінде f(a),f(b) және сындық нүктелердегі мәндерді салыстыр.'),b('Экстремум — местный максимум или минимум; критическая точка требует проверки.','Экстремум — жергілікті максимум не минимум; сындық нүктені тексеру қажет.'),b('Каждая точка f′=0 объявлена экстремумом без смены знака.','f′=0 әр нүктесі таңба ауысуынсыз экстремум деп алынған.'),
 (i,n,l)=>l===1?num(b(`Абсцисса минимума f(x)=(x−${n})²+2?`,`f(x)=(x−${n})²+2 минимумының абсциссасы неше?`),n,[step(`f′(x)=2(x−${n}).`,`f′(x)=2(x−${n}).`),step(`При x=${n} знак меняется с − на +.`,`x=${n} кезінде таңба −-тен +-ке ауысады.`)]):l===2?num(b(`Найди минимальное значение f(x)=x²−${2*n}x+${n*n+3}.`,`f(x)=x²−${2*n}x+${n*n+3} ең кіші мәнін тап.`),3,[step(`f′(x)=2x−${2*n}, ноль при x=${n}.`,`f′(x)=2x−${2*n}, нөлі x=${n}.`),step(`f(${n})=${n*n}−${2*n*n}+${n*n+3}=3.`,`f(${n})=${n*n}−${2*n*n}+${n*n+3}=3.`)]):num(b(`Найди максимум f(x)=x² на отрезке [−${n+2};${n}].`,`[−${n+2};${n}] кесіндісінде f(x)=x² максимумын тап.`),(n+2)**2,[step('Критическая точка x=0 даёт 0.','Сындық x=0 нүктесінде 0 шығады.'),step(`На концах ${(n+2)**2} и ${n*n}; больше ${(n+2)**2}.`,`Шеттерінде ${(n+2)**2} және ${n*n}; үлкені ${(n+2)**2}.`)]));

core('integral','Математический анализ','profile',b('Первообразная и интеграл','Алғашқы функция және интеграл'),'13',['derivative'],b('Восстановить функцию по производной и вычислить простой интеграл.','Туынды арқылы функцияны қалпына келтіру және қарапайым интегралды есептеу.'),b('Первообразная F для f — функция с F′=f. Их много: добавление постоянного C не меняет производную. Определённый интеграл равен F(b)−F(a). Когда f≥0, он даёт площадь под графиком; отрицательные участки учитываются со знаком, поэтому интеграл не всегда геометрическая площадь.','f үшін алғашқы F функциясының туындысы F′=f. Олар көп: C тұрақтысын қосу туындыны өзгертпейді. Анықталған интеграл F(b)−F(a)-ға тең. f≥0 кезінде график астындағы ауданды береді; теріс бөліктер таңбасымен есептеледі, сондықтан интеграл әрдайым геометриялық аудан емес.'),b('∫xⁿ dx=xⁿ⁺¹/(n+1)+C, n≠−1; ∫ₐᵇf(x)dx=F(b)−F(a).','∫xⁿ dx=xⁿ⁺¹/(n+1)+C, n≠−1; ∫ₐᵇf(x)dx=F(b)−F(a).'),b('C — произвольная постоянная; пределы a,b — границы интегрирования.','C — еркін тұрақты; a,b — интегралдау шекаралары.'),b('Забыто деление на новый показатель или перепутан порядок F(b)−F(a).','Жаңа көрсеткішке бөлу ұмытылған немесе F(b)−F(a) реті ауысқан.'),
 (i,n,l)=>l===1?num(b(`Найди ∫₀¹ ${n} dx.`,`∫₀¹ ${n} dx мәнін тап.`),n,[step(`Первообразная ${n}x.`,`Алғашқы функция ${n}x.`),step(`${n}·1−${n}·0=${n}.`,`${n}·1−${n}·0=${n}.`)]):l===2?num(b(`Найди ∫₀² ${n}x dx.`,`∫₀² ${n}x dx мәнін тап.`),2*n,[step(`F(x)=${n}x²/2.`,`F(x)=${n}x²/2.`),step(`F(2)−F(0)=${n}·4/2=${2*n}.`,`F(2)−F(0)=${n}·4/2=${2*n}.`)]):num(b(`Найди площадь под y=${3*n}x² на [1;2].`,`[1;2] аралығында y=${3*n}x² астындағы ауданды тап.`),7*n,[step('Функция положительна: площадь равна интегралу.','Функция оң: аудан интегралға тең.'),step(`F(x)=${n}x³; F(2)−F(1)=${8*n}−${n}=${7*n}.`,`F(x)=${n}x³; F(2)−F(1)=${8*n}−${n}=${7*n}.`)]));

core('motion','Математическое моделирование','profile',b('Задачи на движение','Қозғалыс есептері'),'13',['linear','units'],b('Составить модель движения и согласовать единицы.','Қозғалыс моделін құру және бірліктерді сәйкестендіру.'),b('Путь, скорость и время связаны при равномерном движении. Нарисуй участников, направление и расстояние. При движении навстречу расстояние сокращается со скоростью суммы; при догонке — разности. На реке скорость по течению равна сумме скорости лодки и течения, против — разности.','Бірқалыпты қозғалыста жол, жылдамдық және уақыт байланысты. Қатысушыларды, бағытты және қашықтықты сыз. Бір-біріне қарсы қозғалғанда қашықтық жылдамдықтар қосындысымен, қуып жеткенде айырмасымен қысқарады. Ағыс бойымен қайық пен ағыс жылдамдықтары қосылады, қарсы бағытта азайтылады.'),b('s=vt; навстречу t=s/(v₁+v₂); догонка t=s/(v₁−v₂), v₁>v₂.','s=vt; қарсы қозғалыста t=s/(v₁+v₂); қуып жетуде t=s/(v₁−v₂), v₁>v₂.'),b('Модель — формулы, описывающие условие; относительная скорость — скорость изменения расстояния.','Модель — шартты сипаттайтын формулалар; салыстырмалы жылдамдық — қашықтықтың өзгеру жылдамдығы.'),b('Скорости сложены при догонке или смешаны часы и минуты.','Қуып жетуде жылдамдықтар қосылған немесе сағат пен минут араласқан.'),
 (i,n,l)=>l===1?num(b(`Автобус едет 60 км/ч в течение ${n+1} ч. Путь?`,`Автобус 60 км/сағ жылдамдықпен ${n+1} сағ жүреді. Жолы?`),60*(n+1),[step('s=vt.','s=vt.'),step(`60·${n+1}=${60*(n+1)}.`,`60·${n+1}=${60*(n+1)}.`)],'км'):l===2?num(b(`Из городов в ${100*(n+1)} км выехали навстречу машины 40 и 60 км/ч. Через сколько часов встреча?`,`${100*(n+1)} км қашықтықтағы қалалардан 40 және 60 км/сағ көліктер қарсы шықты. Неше сағаттан кейін кездеседі?`),n+1,[step('Скорость сближения 40+60=100 км/ч.','Жақындасу жылдамдығы 40+60=100 км/сағ.'),step(`t=${100*(n+1)}/100=${n+1}.`,`t=${100*(n+1)}/100=${n+1}.`)],'ч'):num(b(`Катер 15 км/ч в стоячей воде, течение ${n} км/ч. Найди время против течения на ${2*(15-n)} км.`,`Қайықтың тынық судағы жылдамдығы 15 км/сағ, ағыс ${n} км/сағ. Ағысқа қарсы ${2*(15-n)} км жүру уақыты?`),2,[step(`Против течения v=15−${n}=${15-n}.`,`Ағысқа қарсы v=15−${n}=${15-n}.`),step(`t=${2*(15-n)}/${15-n}=2.`,`t=${2*(15-n)}/${15-n}=2.`)],'ч'));

core('work','Математическое моделирование','profile',b('Совместная работа','Бірлескен жұмыс'),'13',['fractions','rational'],b('Сложить производительности и найти время общей работы.','Өнімділіктерді қосып, ортақ жұмыс уақытын табу.'),b('Всю работу удобно принять за 1. Если человек выполняет её за a часов, за час он делает 1/a работы. Совместно производительности складываются, а времена нет. После нахождения скорости работы время равно объёму, делённому на скорость. Для трубы, которая сливает, производительность берётся со знаком минус.','Барлық жұмысты 1 деп алған ыңғайлы. Адам a сағатта бітірсе, бір сағатта жұмыстың 1/a бөлігін орындайды. Бірге жұмыс істегенде өнімділіктер қосылады, уақыттары қосылмайды. Уақыт — көлемнің өнімділікке қатынасы. Суды ағызатын құбырдың өнімділігі минус таңбасымен алынады.'),b('p=1/t; tсовм=1/(1/a+1/b), a,b>0.','p=1/t; tбірге=1/(1/a+1/b), a,b>0.'),b('Производительность — доля работы за единицу времени.','Өнімділік — уақыт бірлігінде орындалатын жұмыс бөлігі.'),b('Сложены времена вместо производительностей.','Өнімділік орнына уақыттар қосылған.'),
 (i,n,l)=>l===1?num(b(`Работа занимает ${n+3} ч. Какую долю делают за 1 ч? Ответ десятичный.`,`Жұмыс ${n+3} сағ алады. 1 сағ ішінде қандай бөлігі орындалады? Ондық жауап бер.`),1/(n+3),[step('Работа равна 1.','Жұмыс 1-ге тең.'),step(`Доля за час 1/${n+3}≈${f(1/(n+3))}.`,`Сағаттағы бөлігі 1/${n+3}≈${f(1/(n+3))}.`)]):l===2?num(b(`Два одинаковых мастера по отдельности работают ${2*(n+2)} ч. Вместе?`,`Екі бірдей шебердің әрқайсысы ${2*(n+2)} сағ жұмыс істейді. Бірге неше сағ?`),n+2,[step(`Производительность 2/${2*(n+2)}=1/${n+2}.`,`Өнімділік 2/${2*(n+2)}=1/${n+2}.`),step(`Время ${n+2} ч.`,`Уақыт ${n+2} сағ.`)],'ч'):num(b(`Одна труба наполняет за ${2*(n+1)} ч, другая за ${3*(n+1)} ч. Вместе за сколько часов?`,`Бір құбыр ${2*(n+1)} сағ, екіншісі ${3*(n+1)} сағ толтырады. Бірге неше сағ?`),6*(n+1)/5,[step(`p=1/${2*(n+1)}+1/${3*(n+1)}=5/${6*(n+1)}.`,`p=1/${2*(n+1)}+1/${3*(n+1)}=5/${6*(n+1)}.`),step(`t=1/p=${f(6*(n+1)/5)}.`,`t=1/p=${f(6*(n+1)/5)}.`)],'ч'));

core('mixtures','Математическое моделирование','profile',b('Смеси, концентрация и проценты','Қоспалар, концентрация және пайыз'),'13',['percentages','linear'],b('Сохранить массу вещества при смешивании и разбавлении.','Араластыру және сұйылту кезінде зат массасын сақтау.'),b('Концентрация — доля нужного вещества во всей смеси. В 200 г раствора 10% содержат 20 г вещества. При добавлении воды масса вещества не меняется, но общая масса растёт. При смешивании складываются массы вещества и общие массы; нельзя просто усреднить проценты, если массы разные.','Концентрация — бүкіл қоспадағы қажетті заттың үлесі. 200 г 10% ерітіндіде 20 г зат бар. Су қосқанда зат массасы өзгермейді, жалпы масса өседі. Араластыруда зат массалары мен жалпы массалар қосылады; массалар әртүрлі болса, пайыздарды жай орташа алуға болмайды.'),b('mвещ=mраств·p/100; pсм=100(m₁p₁/100+m₂p₂/100)/(m₁+m₂).','mзат=mеріт·p/100; pқоспа=100(m₁p₁/100+m₂p₂/100)/(m₁+m₂).'),b('Раствор — однородная смесь; массовая концентрация — процент массы вещества.','Ерітінді — біртекті қоспа; массалық концентрация — зат массасының пайызы.'),b('Концентрации усреднены без учёта массы.','Концентрациялар массаларды ескермей орташаланған.'),
 (i,n,l)=>l===1?num(b(`Сколько граммов соли в ${100*n} г раствора 15%?`,`${100*n} г 15% ерітіндіде неше грамм тұз бар?`),15*n,[step('Масса соли = масса раствора ·0,15.','Тұз массасы = ерітінді массасы ·0,15.'),step(`${100*n}·0,15=${15*n}.`,`${100*n}·0,15=${15*n}.`)],'г'):l===2?num(b(`К ${100*n} г раствора 20% добавили ${100*n} г воды. Какой процент соли?`,`${100*n} г 20% ерітіндіге ${100*n} г су қосылды. Тұз пайызы қандай?`),10,[step(`Соль ${20*n} г, новая масса ${200*n} г.`,`Тұз ${20*n} г, жаңа масса ${200*n} г.`),step(`100·${20*n}/${200*n}=10%.`,`100·${20*n}/${200*n}=10%.`)],'%'):num(b(`Смешали ${100*n} г раствора 10% и ${200*n} г раствора 25%. Концентрация?`,`${100*n} г 10% және ${200*n} г 25% ерітінді араластырылды. Концентрациясы?`),20,[step(`Соль: ${10*n}+${50*n}=${60*n} г.`,`Тұз: ${10*n}+${50*n}=${60*n} г.`),step(`Общая масса ${300*n}; 100·${60*n}/${300*n}=20%.`,`Жалпы масса ${300*n}; 100·${60*n}/${300*n}=20%.`)],'%'));

core('angles','Планиметрия','profile',b('Углы и параллельные прямые','Бұрыштар және параллель түзулер'),'14',['numbers'],b('Находить углы из геометрических связей.','Геометриялық байланыстар арқылы бұрыштарды табу.'),b('Угол образуется двумя лучами с общим началом. Развёрнутый угол равен 180°, полный оборот 360°. Смежные углы вместе образуют прямую, вертикальные лежат напротив при пересечении прямых и равны. У параллельных прямых с секущей соответственные и накрест лежащие углы равны.','Бұрыш ортақ бастау нүктесі бар екі сәуледен тұрады. Жазыңқы бұрыш 180°, толық айналым 360°. Сыбайлас бұрыштар түзу құрайды, вертикаль бұрыштар қиылысуда қарама-қарсы орналасып, тең болады. Параллель түзулер мен қиюшыда сәйкес және айқыш бұрыштар тең.'),b('α+β=180° для смежных; α=β для вертикальных.','Сыбайлас үшін α+β=180°; вертикаль үшін α=β.'),b('Секущая пересекает две прямые; параллельные прямые на плоскости не пересекаются.','Қиюшы екі түзуді қияды; параллель түзулер жазықтықта қиылыспайды.'),b('Не проверена параллельность перед использованием равенства углов.','Бұрыш теңдігін қолданғанда параллельдік тексерілмеген.'),
 (i,n,l)=>l===1?num(b(`Один смежный угол ${20*n}°. Найди другой.`,`Бір сыбайлас бұрыш ${20*n}°. Екіншісін тап.`),180-20*n,[step('Сумма смежных 180°.','Сыбайлас бұрыштардың қосындысы 180°.'),step(`180−${20*n}=${180-20*n}.`,`180−${20*n}=${180-20*n}.`)],'°'):l===2?num(b(`Вертикальный угол к ${30+10*n}° равен?`,`${30+10*n}° бұрышқа вертикаль бұрыш неше?`),30+10*n,[step('Вертикальные углы равны.','Вертикаль бұрыштар тең.'),step(`Ответ ${30+10*n}°.`,`Жауап ${30+10*n}°.`)],'°'):num(b(`Смежные углы относятся 1:${n+1}. Найди меньший угол.`,`Сыбайлас бұрыштар қатынасы 1:${n+1}. Кіші бұрышты тап.`),180/(n+2),[step(`Всего ${n+2} равных долей в 180°.`,`180° ішінде ${n+2} тең үлес бар.`),step(`Меньший 180/${n+2}=${f(180/(n+2))}°.`,`Кіші бұрыш 180/${n+2}=${f(180/(n+2))}°.`)],'°'));

core('triangles','Планиметрия','profile',b('Треугольники, Пифагор и площадь','Үшбұрыштар, Пифагор және аудан'),'14,15',['angles','radicals'],b('Использовать сумму углов, Пифагора и основание с высотой.','Бұрыштар қосындысын, Пифагорды және табан мен биіктікті қолдану.'),b('Треугольник имеет три стороны и сумму углов 180°. В прямоугольном треугольнике катеты образуют угол 90°, гипотенуза напротив него — самая длинная сторона. Теорема Пифагора относится только к такому треугольнику. Высота перпендикулярна выбранному основанию и может выходить за треугольник.','Үшбұрыштың үш қабырғасы бар, бұрыштар қосындысы 180°. Тікбұрышты үшбұрышта катеттер 90° бұрыш құрайды, қарсы жатқан гипотенуза ең ұзын қабырға. Пифагор теоремасы тек осындай үшбұрышқа арналған. Биіктік таңдалған табанға перпендикуляр және үшбұрыштан тыс жатуы мүмкін.'),b('α+β+γ=180°; c²=a²+b² (c — гипотенуза); S=ah/2.','α+β+γ=180°; c²=a²+b² (c — гипотенуза); S=ah/2.'),b('Катет — сторона у прямого угла; высота — перпендикуляр к основанию.','Катет — тік бұрышқа жанасқан қабырға; биіктік — табанға перпендикуляр.'),b('Боковая сторона принята за высоту без прямого угла.','Бүйір қабырға тік бұрышсыз биіктік деп алынған.'),
 (i,n,l)=>l===1?num(b(`Два угла треугольника ${30+5*n}° и 60°. Третий?`,`Үшбұрыштың екі бұрышы ${30+5*n}° және 60°. Үшіншісі?`),90-5*n,[step('Три угла дают 180°.','Үш бұрыш қосындысы 180°.'),step(`180−${30+5*n}−60=${90-5*n}.`,`180−${30+5*n}−60=${90-5*n}.`)],'°'):l===2?num(b(`Катеты ${3*n} и ${4*n} см. Гипотенуза?`,`Катеттері ${3*n} және ${4*n} см. Гипотенузасы?`),5*n,[step(`c²=${(3*n)**2}+${(4*n)**2}=${25*n*n}.`,`c²=${(3*n)**2}+${(4*n)**2}=${25*n*n}.`),step(`c=${5*n}.`,`c=${5*n}.`)],'см'):num(b(`Основание ${2*n+4} см, площадь ${5*(2*n+4)} см². Высота?`,`Табаны ${2*n+4} см, ауданы ${5*(2*n+4)} см². Биіктігі?`),10,[step('h=2S/a.','h=2S/a.'),step(`h=2·${5*(2*n+4)}/${2*n+4}=10.`,`h=2·${5*(2*n+4)}/${2*n+4}=10.`)],'см'));

core('quadrilaterals','Планиметрия','profile',b('Четырёхугольники и площади','Төртбұрыштар және аудандар'),'14,15',['triangles'],b('Различать свойства прямоугольника, параллелограмма, ромба и трапеции.','Тіктөртбұрыш, параллелограмм, ромб және трапеция қасиеттерін ажырату.'),b('Параллелограмм имеет две пары параллельных сторон; его площадь — основание на перпендикулярную высоту. Прямоугольник — параллелограмм с прямыми углами. Ромб — с равными сторонами, его диагонали перпендикулярны. У трапеции одна пара сторон параллельна: это основания. Сумма внутренних углов четырёхугольника 360°.','Параллелограммның екі жұп қабырғасы параллель; ауданы — табан мен перпендикуляр биіктіктің көбейтіндісі. Тіктөртбұрыш — бұрыштары тік параллелограмм. Ромбтың барлық қабырғасы тең, диагональдары перпендикуляр. Трапецияның бір жұп қабырғасы параллель, олар табандар. Төртбұрыш бұрыштары қосындысы 360°.'),b('Sпрям=ab; Sпар=ah; Sтрап=(a+b)h/2; Sромба=d₁d₂/2.','Sтікт=ab; Sпар=ah; Sтрап=(a+b)h/2; Sромб=d₁d₂/2.'),b('Диагональ соединяет противоположные вершины; периметр — сумма сторон.','Диагональ қарама-қарсы төбелерді қосады; периметр — қабырғалар қосындысы.'),b('Основание умножено на наклонную боковую сторону вместо высоты.','Табан биіктіктің орнына көлбеу бүйір қабырғаға көбейтілген.'),
 (i,n,l)=>l===1?num(b(`Прямоугольник ${n+3}×4 см. Площадь?`,`${n+3}×4 см тіктөртбұрыш ауданы?`),4*(n+3),[step('S=ab.','S=ab.'),step(`${n+3}·4=${4*(n+3)}.`,`${n+3}·4=${4*(n+3)}.`)],'см²'):l===2?matching(b(`Сопоставь фигуру и площадь: ▭ прямоугольник, ◇ ромб, △ треугольник.`,`Фигура мен ауданын сәйкестендір: ▭ тіктөртбұрыш, ◇ ромб, △ үшбұрыш.`),[{left:`▭ a=${n},b=6`,right:`${6*n}`},{left:`◇ d₁=${n},d₂=6`,right:`${3*n}`},{left:`△ a=${n},h=4`,right:`${2*n}`}],[step('Используем ab, d₁d₂/2 и ah/2.','ab, d₁d₂/2 және ah/2 қолданамыз.'),step('Площадь выражена в квадратных единицах.','Аудан шаршы бірліктермен беріледі.')]):num(b(`Основания трапеции ${n+3} и ${n+7} см, высота 4 см. Площадь?`,`Трапеция табандары ${n+3} және ${n+7} см, биіктігі 4 см. Ауданы?`),4*n+20,[step(`Среднее оснований (${n+3}+${n+7})/2=${n+5}.`,`Табандардың орташа мәні (${n+3}+${n+7})/2=${n+5}.`),step(`S=${n+5}·4=${4*n+20}.`,`S=${n+5}·4=${4*n+20}.`)],'см²'));

core('circles','Планиметрия','profile',b('Окружность, углы и круг','Шеңбер, бұрыштар және дөңгелек'),'14,15',['angles','proportions'],b('Вычислять длину окружности, площадь круга и вписанные углы.','Шеңбер ұзындығын, дөңгелек ауданын және іштей сызылған бұрышты есептеу.'),b('Окружность — точки на одном расстоянии r от центра, круг включает внутреннюю область. Диаметр d=2r проходит через центр. Вписанный угол с вершиной на окружности равен половине центрального угла, опирающегося на ту же дугу. Касательная перпендикулярна радиусу в точке касания.','Шеңбер — центрден бірдей r қашықтықтағы нүктелер, дөңгелек ішкі аймақты да қамтиды. d=2r диаметрі центр арқылы өтеді. Төбесі шеңбердегі іштей сызылған бұрыш сол доғаға тірелетін центрлік бұрыштың жартысына тең. Жанама жанасу нүктесіндегі радиусқа перпендикуляр.'),b('L=2πr; S=πr²; αвпис=αцентр/2 для одной дуги.','L=2πr; S=πr²; бір доға үшін αіштей=αцентр/2.'),b('Дуга — часть окружности; хорда соединяет две её точки. π≈3,14159.','Доға — шеңбер бөлігі; хорда оның екі нүктесін қосады. π≈3,14159.'),b('Радиус перепутан с диаметром или длина с площадью.','Радиус диаметрмен немесе ұзындық ауданмен шатастырылған.'),
 (i,n,l)=>l===1?num(b(`Радиус ${n+1} см. Найди коэффициент перед π в длине окружности.`,`Радиус ${n+1} см. Шеңбер ұзындығындағы π алдындағы коэффициентті тап.`),2*(n+1),[step('L=2πr.','L=2πr.'),step(`L=${2*(n+1)}π; коэффициент ${2*(n+1)}.`,`L=${2*(n+1)}π; коэффициент ${2*(n+1)}.`)]):l===2?num(b(`Диаметр ${2*(n+2)} см. Коэффициент перед π в площади круга?`,`Диаметр ${2*(n+2)} см. Дөңгелек ауданындағы π коэффициенті?`),(n+2)**2,[step(`r=d/2=${n+2}.`,`r=d/2=${n+2}.`),step(`S=πr²=${(n+2)**2}π.`,`S=πr²=${(n+2)**2}π.`)]):num(b(`Центральный угол ${60+20*n}°. Вписанный угол на той же дуге?`,`Центрлік бұрыш ${60+20*n}°. Сол доғадағы іштей сызылған бұрыш?`),30+10*n,[step('Вписанный равен половине центрального.','Іштей сызылған бұрыш центрліктің жартысына тең.'),step(`${60+20*n}/2=${30+10*n}.`,`${60+20*n}/2=${30+10*n}.`)],'°'));

core('similarity','Планиметрия','profile',b('Подобие и отношения площадей','Ұқсастық және аудандар қатынасы'),'15',['triangles','proportions'],b('Переносить размеры подобных фигур и учитывать квадрат масштаба.','Ұқсас фигуралардың өлшемдерін табу және масштаб квадратын ескеру.'),b('Подобные фигуры имеют одинаковую форму: соответствующие углы равны, стороны пропорциональны. Если длины увеличились в k раз, периметр тоже в k раз, площадь — в k² раз. У треугольников достаточно равенства двух углов. Соответствие сторон нужно определить по одинаковым углам.','Ұқсас фигуралардың пішіні бірдей: сәйкес бұрыштары тең, қабырғалары пропорционал. Ұзындық k есе артса, периметр де k есе, аудан k² есе артады. Үшбұрышта екі бұрыштың теңдігі жеткілікті. Қабырғалардың сәйкестігін бірдей бұрыштар арқылы анықта.'),b('a₂/a₁=k; P₂/P₁=k; S₂/S₁=k², k>0.','a₂/a₁=k; P₂/P₁=k; S₂/S₁=k², k>0.'),b('Коэффициент подобия k — отношение соответствующих длин.','Ұқсастық коэффициенті k — сәйкес ұзындықтар қатынасы.'),b('Площадь увеличена в k раз вместо k².','Аудан k² орнына k есе арттырылған.'),
 (i,n,l)=>l===1?num(b(`Сторона 4 см увеличена в ${n+1} раз. Новая длина?`,`4 см қабырға ${n+1} есе үлкейтілді. Жаңа ұзындығы?`),4*(n+1),[step('Умножаем длину на k.','Ұзындықты k-ға көбейтеміз.'),step(`4·${n+1}=${4*(n+1)}.`,`4·${n+1}=${4*(n+1)}.`)],'см'):l===2?num(b(`Площадь 3 см², коэффициент подобия ${n+1}. Новая площадь?`,`Аудан 3 см², ұқсастық коэффициенті ${n+1}. Жаңа аудан?`),3*(n+1)**2,[step(`Площадь умножается на k²=${(n+1)**2}.`,`Аудан k²=${(n+1)**2}-ге көбейтіледі.`),step(`3·${(n+1)**2}=${3*(n+1)**2}.`,`3·${(n+1)**2}=${3*(n+1)**2}.`)],'см²'):num(b(`Площади подобных треугольников относятся 1:${(n+2)**2}. Малая сторона 3 см. Соответствующая большая?`,`Ұқсас үшбұрыштар аудандарының қатынасы 1:${(n+2)**2}. Кіші қабырға 3 см. Сәйкес үлкен қабырға?`),3*(n+2),[step(`Линейный коэффициент √${(n+2)**2}=${n+2}.`,`Сызықтық коэффициент √${(n+2)**2}=${n+2}.`),step(`3·${n+2}=${3*(n+2)}.`,`3·${n+2}=${3*(n+2)}.`)],'см'));

core('plane-vectors','Координаты и преобразования','profile',b('Координаты и векторы на плоскости','Жазықтықтағы координаталар және векторлар'),'15',['triangles','functions'],b('Найти вектор, расстояние и образ точки при преобразовании.','Векторды, қашықтықты және түрлендірілген нүктені табу.'),b('Координаты (x,y) задают положение. Вектор — направленный отрезок: его координаты равны конечным минус начальные. Длина находится по Пифагору. Скалярное произведение связывает координаты и угол; ноль у ненулевых векторов означает перпендикулярность. При переносе прибавь вектор, при отражении относительно оси x измени знак y.','(x,y) координаталары орынды көрсетеді. Вектор — бағытталған кесінді: координаталары соңғы нүктеден бастапқыны азайту арқылы табылады. Ұзындығы Пифагормен есептеледі. Скаляр көбейтінді координаталар мен бұрышты байланыстырады; нөл емес векторларда нөл перпендикулярлықты білдіреді. Көшіруде векторды қос, x осіне шағылуда y таңбасын өзгерт.'),b('AB=(xB−xA,yB−yA); |v|=√(vx²+vy²); u·v=uxvx+uyvy.','AB=(xB−xA,yB−yA); |v|=√(vx²+vy²); u·v=uxvx+uyvy.'),b('Скалярное произведение — число, равное |u||v|cosα. Перенос сохраняет длины и углы.','Скаляр көбейтінді — |u||v|cosα саны. Параллель көшіру ұзындықтар мен бұрыштарды сақтайды.'),b('Координаты вычтены в обратном порядке.','Координаталар кері ретпен азайтылған.'),
 (i,n,l)=>l===1?num(b(`A(${n};1), B(${n+4};4). Длина AB?`,`A(${n};1), B(${n+4};4). AB ұзындығы?`),5,[step('AB=(4,3).','AB=(4,3).'),step('|AB|=√(16+9)=5.','|AB|=√(16+9)=5.')]):l===2?num(b(`u=(${n};2), v=(3;−1). Найди u·v.`,`u=(${n};2), v=(3;−1). u·v тап.`),3*n-2,[step(`u·v=${n}·3+2·(−1).`,`u·v=${n}·3+2·(−1).`),step(`Получаем ${3*n-2}.`,`${3*n-2} аламыз.`)]):num(b(`Точку A(${n};−3) отразили относительно Ox, затем перенесли на (2;${n}). Найди y образа.`,`A(${n};−3) нүктесін Ox-ке шағылдырып, (2;${n}) векторына көшірді. Жаңа y тап.`),n+3,[step(`Отражение: (${n};3).`,`Шағылу: (${n};3).`),step(`После переноса (${n+2};${n+3}); y=${n+3}.`,`Көшіргеннен кейін (${n+2};${n+3}); y=${n+3}.`)]));

core('solids','Стереометрия','profile',b('Тела, прямые, плоскости и сечения','Денелер, түзулер, жазықтықтар және қималар'),'16',['quadrilaterals'],b('Узнавать пространственные тела и понимать сечения.','Кеңістік денелерін тану және қималарды түсіну.'),b('В пространстве прямые могут быть параллельными, пересекаться или быть скрещивающимися: последние не лежат в одной плоскости. Призма имеет два равных параллельных основания; пирамида одно основание и общую вершину боковых треугольников. Сечение — фигура пересечения тела с плоскостью. У прямой призмы сечение, параллельное основанию, равно основанию.','Кеңістікте түзулер параллель, қиылысатын немесе айқас болуы мүмкін: айқас түзулер бір жазықтықта жатпайды. Призманың екі тең параллель табаны бар; пирамиданың бір табаны және бүйір үшбұрыштардың ортақ төбесі бар. Қима — дене мен жазықтықтың қиылысу фигурасы. Тік призманың табанына параллель қимасы табанға тең.'),b('У n-угольной призмы: вершины 2n, рёбра 3n, грани n+2. У пирамиды: n+1, 2n, n+1.','n-бұрышты призмада: төбелер 2n, қырлар 3n, жақтар n+2. Пирамидада: n+1, 2n, n+1.'),b('Грань — плоская часть поверхности; ребро — линия двух граней; сечение — пересечение плоскостью.','Жақ — беттің жазық бөлігі; қыр — екі жақтың ортақ сызығы; қима — жазықтықпен қиылысу.'),b('Скрещивающиеся прямые названы параллельными.','Айқас түзулер параллель деп аталған.'),
 (i,n,l)=>l===1?num(b(`Сколько вершин у ${n+3}-угольной призмы?`,`${n+3}-бұрышты призманың неше төбесі бар?`),2*(n+3),[step('По одной вершине основания внизу и вверху.','Төменгі және жоғарғы табанда бірдей төбелер бар.'),step(`2·${n+3}=${2*(n+3)}.`,`2·${n+3}=${2*(n+3)}.`)]):l===2?num(b(`Сколько рёбер у ${n+3}-угольной пирамиды?`,`${n+3}-бұрышты пирамиданың неше қыры бар?`),2*(n+3),[step(`${n+3} рёбер основания и столько же боковых.`,`${n+3} табан қыры және сонша бүйір қыры бар.`),step(`Всего ${2*(n+3)}.`,`Барлығы ${2*(n+3)}.`)]):num(b(`У прямой призмы основание — прямоугольник ${n+2}×4. Площадь сечения, параллельного основанию?`,`Тік призманың табаны ${n+2}×4 тіктөртбұрыш. Табанға параллель қиманың ауданы?`),4*(n+2),[step('Параллельное основанию сечение призмы равно основанию.','Призманың табанына параллель қимасы табанға тең.'),step(`S=${n+2}·4=${4*(n+2)}.`,`S=${n+2}·4=${4*(n+2)}.`)]));

core('volumes','Стереометрия','profile',b('Площади поверхностей и объёмы','Бет аудандары және көлемдер'),'17',['solids','circles','units'],b('Вычислять объём и поверхность призм, пирамид, цилиндров, конусов и шара.','Призма, пирамида, цилиндр, конус және шар көлемі мен бетін есептеу.'),b('Объём показывает вместимость и измеряется кубическими единицами. Призма и цилиндр имеют объём площади основания на перпендикулярную высоту. У пирамиды и конуса он в три раза меньше при тех же основании и высоте. Для боковой поверхности конуса нужна образующая l, а не высота h; l²=r²+h². Полная поверхность включает основания.','Көлем сыйымдылықты көрсетеді және куб бірлікпен өлшенеді. Призма мен цилиндр көлемі — табан ауданы мен перпендикуляр биіктіктің көбейтіндісі. Пирамида мен конуста бірдей табан мен биіктікте ол үш есе аз. Конустың бүйір бетіне h биіктігі емес, l жасаушысы керек; l²=r²+h². Толық бет табандарды да қамтиды.'),b('Vпр=Sh; Vпир=Sh/3; Vцил=πr²h; Sцил=2πr(r+h); Vкон=πr²h/3; Sкон=πr(r+l); Vшара=4πr³/3; Sшара=4πr².','Vпр=Sh; Vпир=Sh/3; Vцил=πr²h; Sцил=2πr(r+h); Vкон=πr²h/3; Sкон=πr(r+l); Vшар=4πr³/3; Sшар=4πr².'),b('Образующая конуса соединяет вершину с окружностью основания; высота перпендикулярна основанию.','Конус жасаушысы төбені табан шеңберімен қосады; биіктік табанға перпендикуляр.'),b('Не учтены основания в полной поверхности или деление на 3 у пирамиды.','Толық бетте табандар не пирамидадағы 3-ке бөлу ескерілмеген.'),
 (i,n,l)=>l===1?num(b(`Прямоугольный параллелепипед ${n+2}×3×4 см. Объём?`,`${n+2}×3×4 см тікбұрышты параллелепипед көлемі?`),12*(n+2),[step('V=abc.','V=abc.'),step(`${n+2}·3·4=${12*(n+2)}.`,`${n+2}·3·4=${12*(n+2)}.`)],'см³'):l===2?num(b(`Цилиндр r=${n}, h=6. Найди коэффициент перед π в объёме.`,`Цилиндр r=${n}, h=6. Көлеміндегі π коэффициентін тап.`),6*n*n,[step('V=πr²h.','V=πr²h.'),step(`V=${6*n*n}π.`,`V=${6*n*n}π.`)]):num(b(`Конус r=${3*n}, h=${4*n}. Коэффициент перед π в полной поверхности?`,`Конус r=${3*n}, h=${4*n}. Толық бетіндегі π коэффициенті?`),24*n*n,[step(`l=√(${(3*n)**2}+${(4*n)**2})=${5*n}.`,`l=√(${(3*n)**2}+${(4*n)**2})=${5*n}.`),step(`S=πr(r+l)=π·${3*n}·${8*n}=${24*n*n}π.`,`S=πr(r+l)=π·${3*n}·${8*n}=${24*n*n}π.`)]));

core('space-vectors','Координаты и преобразования','profile',b('Векторы и преобразования в пространстве','Кеңістіктегі векторлар және түрлендірулер'),'18',['plane-vectors','solids'],b('Работать с тремя координатами, расстояниями и переносом.','Үш координатамен, қашықтықпен және көшірумен жұмыс істеу.'),b('Третья координата z указывает высоту относительно плоскости xy. Правила векторов сохраняются: вычитаем координаты конца и начала, складываем покоординатно. Длина — корень суммы трёх квадратов. Скалярное произведение даёт угол или проверку перпендикулярности. Отражение относительно плоскости xy меняет знак z.','Үшінші z координатасы xy жазықтығына қатысты биіктікті көрсетеді. Вектор ережелері сақталады: соңғы және бастапқы координаталарды азайтамыз, сәйкес координаталарды қосамыз. Ұзындық — үш квадрат қосындысының түбірі. Скаляр көбейтінді бұрышты не перпендикулярлықты тексереді. xy жазықтығына шағылу z таңбасын өзгертеді.'),b('|v|=√(vx²+vy²+vz²); u·v=uxvx+uyvy+uzvz; cosα=(u·v)/(|u||v|) для ненулевых векторов.','|v|=√(vx²+vy²+vz²); u·v=uxvx+uyvy+uzvz; нөл емес векторларда cosα=(u·v)/(|u||v|).'),b('Пространственный вектор имеет три координаты; нулевой вектор не задаёт направление.','Кеңістік векторы үш координаталы; нөл векторы бағыт бермейді.'),b('При длине забыта третья координата.','Ұзындықта үшінші координата ұмытылған.'),
 (i,n,l)=>l===1?num(b(`Длина вектора (${n};${2*n};${2*n})?`,`(${n};${2*n};${2*n}) векторының ұзындығы?`),3*n,[step(`Сумма квадратов ${n*n}+${4*n*n}+${4*n*n}=${9*n*n}.`,`Квадраттар қосындысы ${n*n}+${4*n*n}+${4*n*n}=${9*n*n}.`),step(`Корень ${3*n}.`,`Түбірі ${3*n}.`)]):l===2?num(b(`u=(${n};2;−1), v=(3;1;4). Найди u·v.`,`u=(${n};2;−1), v=(3;1;4). u·v тап.`),3*n-2,[step(`u·v=${n}·3+2·1−1·4.`,`u·v=${n}·3+2·1−1·4.`),step(`Получаем ${3*n-2}.`,`${3*n-2} аламыз.`)]):num(b(`A(1;2;−${n}) отражена в xy, затем перенесена на (0;0;3). Новая z?`,`A(1;2;−${n}) xy-ге шағылдырып, (0;0;3) векторына көшірілді. Жаңа z?`),n+3,[step(`После отражения z=${n}.`,`Шағылудан кейін z=${n}.`),step(`После переноса z=${n}+3=${n+3}.`,`Көшіруден кейін z=${n}+3=${n+3}.`)]));

core('logic','Количественные рассуждения','literacy',b('Логика, числа и множества','Логика, сандар және жиындар'),'01,05',['numbers'],b('Проверять условия по очереди и находить пересечение множеств.','Шарттарды кезекпен тексеру және жиындардың қиылысуын табу.'),b('Логическое высказывание бывает истинным или ложным. «И» требует выполнения обоих условий, «или» — хотя бы одного (если не сказано иначе). Множество — набор элементов без повторов. В пересечении A∩B находятся общие элементы, в объединении A∪B — все элементы двух множеств. Для числовой логики проверь закономерность на нескольких примерах.','Логикалық пікір ақиқат не жалған болады. «Және» екі шарттың орындалуын, «немесе» кемінде біреуін талап етеді (өзгеше айтылмаса). Жиын — қайталанбайтын элементтер тобы. A∩B қиылысуында ортақ, A∪B бірігуінде екі жиынның барлық элементі бар. Сандық логикада заңдылықты бірнеше мысалда тексер.'),b('|A∪B|=|A|+|B|−|A∩B|; |A| — число элементов.','|A∪B|=|A|+|B|−|A∩B|; |A| — элементтер саны.'),b('Чётное число делится на 2 без остатка; множество перечисляет разные элементы.','Жұп сан 2-ге қалдықсыз бөлінеді; жиын әртүрлі элементтерді береді.'),b('Общие элементы посчитаны дважды или «и» заменено на «или».','Ортақ элементтер екі рет саналған немесе «және» орнына «немесе» алынған.'),
 (i,n,l)=>l===1?select(b(`Выбери все чётные числа: ${2*n}, ${2*n+1}, ${2*n+2}, ${2*n+3}.`,`Барлық жұп сандарды таңда: ${2*n}, ${2*n+1}, ${2*n+2}, ${2*n+3}.`),[`${2*n}`,`${2*n+2}`],[`${2*n}`,`${2*n+1}`,`${2*n+2}`,`${2*n+3}`],[step('Чётные делятся на 2 без остатка.','Жұп сандар 2-ге қалдықсыз бөлінеді.'),step(`Подходят ${2*n} и ${2*n+2}.`,`${2*n} және ${2*n+2} сәйкес.`)]):l===2?num(b(`A={${n},${n+1},${n+2}}, B={${n+2},${n+3}}. Сколько элементов A∪B?`,`A={${n},${n+1},${n+2}}, B={${n+2},${n+3}}. A∪B-де неше элемент бар?`),4,[step(`Общий элемент ${n+2} учитываем один раз.`,`Ортақ ${n+2} элементін бір рет санаймыз.`),step('3+2−1=4.','3+2−1=4.')]):num(b(`В группе ${10+n} любят алгебру, ${8+n} геометрию, ${3+n} обе. Сколько любят хотя бы одну?`,`Топта ${10+n} оқушы алгебраны, ${8+n} геометрияны, ${3+n} екеуін де ұнатады. Кемінде біреуін ұнататындар неше?`),15+n,[step('Складываем две группы и вычитаем пересечение.','Екі топты қосып, қиылысуын азайтамыз.'),step(`${10+n}+${8+n}−${3+n}=${15+n}.`,`${10+n}+${8+n}−${3+n}=${15+n}.`)]));

core('word-models','Количественные рассуждения','literacy',b('Из условия в уравнение','Шарттан теңдеуге'),'02',['linear'],b('Составить буквенную модель бытового условия.','Тұрмыстық шарттың әріпті моделін құру.'),b('Назови неизвестную величину буквой и запиши её единицу. Переведи каждую фразу: «на 3 больше» — x+3, «в 3 раза больше» — 3x. Условие равенства даёт уравнение. После решения верни ответ к вопросу: если x — цена одной вещи, общую стоимость надо найти отдельно.','Белгісіз шаманы әріппен атап, бірлігін жаз. Әр тіркесті аудар: «3-ке артық» — x+3, «3 есе артық» — 3x. Теңдік шарты теңдеу береді. Шешкен соң сұраққа қайт: x бір заттың бағасы болса, жалпы құнды бөлек табу керек.'),b('Стоимость = цена · количество; «на a больше» ⇒ x+a; «в a раз больше» ⇒ ax.','Құн = баға · сан; «a-ға артық» ⇒ x+a; «a есе артық» ⇒ ax.'),b('Неизвестная величина — то, что нужно найти, или удобная промежуточная величина.','Белгісіз шама — ізделетін не ыңғайлы аралық шама.'),b('Перепутаны «на» и «в раз» или найдено не то, что спрашивали.','«-ға артық» пен «есе артық» шатасқан немесе сұралмаған шама табылған.'),
 (i,n,l)=>l===1?num(b(`${n+2} одинаковых ручек стоят ${150*(n+2)} ₸. Цена одной?`,`${n+2} бірдей қалам ${150*(n+2)} ₸ тұрады. Біреуінің бағасы?`),150,[step(`(${n+2})x=${150*(n+2)}.`,`(${n+2})x=${150*(n+2)}.`),step(`x=${150*(n+2)}/${n+2}=150.`,`x=${150*(n+2)}/${n+2}=150.`)],'₸'):l===2?num(b(`Задуманное число увеличили в 3 раза, затем на ${n}. Получили ${3*(n+4)+n}. Число?`,`Ойлаған санды 3 есе арттырып, ${n} қосты. ${3*(n+4)+n} шықты. Сан?`),n+4,[step(`3x+${n}=${3*(n+4)+n}.`,`3x+${n}=${3*(n+4)+n}.`),step(`Вычитаем ${n}, делим на 3: x=${n+4}.`,`${n} азайтамыз, 3-ке бөлеміз: x=${n+4}.`)]):num(b(`У старшего в 2 раза больше марок, вместе ${3*(n+5)}. Сколько у младшего?`,`Үлкенінде 2 есе көп марка бар, бірге ${3*(n+5)}. Кішісінде неше?`),n+5,[step(`У младшего x, у старшего 2x; 3x=${3*(n+5)}.`,`Кішісінде x, үлкенінде 2x; 3x=${3*(n+5)}.`),step(`x=${n+5}.`,`x=${n+5}.`)]));

core('charts','Диаграммы и данные','literacy',b('Чтение таблиц и диаграмм','Кестелер мен диаграммаларды оқу'),'03',['percentages'],b('Извлекать данные и находить долю без искажения масштаба.','Деректерді алып, масштабты бұрмаламай үлесті табу.'),b('В столбчатой диаграмме высота показывает значение, но сначала прочитай подпись оси и шаг делений. Круговая диаграмма делит целое: все сектора дают 100% и 360°. Для сравнения групп разного размера используй доли, а не только количество. Текстовая таблица содержит те же сведения для тех, кому график недоступен.','Бағанды диаграммада биіктік мәнді көрсетеді, алдымен ось атауы мен бөлік қадамын оқы. Дөңгелек диаграмма бүтінді бөледі: барлық сектор 100% және 360° береді. Өлшемі әртүрлі топтарды салыстыруда тек санын емес, үлесін қолдан. Мәтіндік кесте график қолжетімсіз болғанда сол деректі береді.'),b('Доля=p/100; угол сектора=360·p/100; p=100·часть/целое.','Үлес=p/100; сектор бұрышы=360·p/100; p=100·бөлік/бүтін.'),b('Сектор — часть круга; масштаб оси — величина одного деления.','Сектор — дөңгелек бөлігі; ось масштабы — бір бөліктің шамасы.'),b('Количество сравнивается без размера группы или пропущена подпись оси.','Топ өлшемі ескерілмеген немесе ось атауы оқылмаған.'),
 (i,n,l)=>l===1?num(b(`Таблица продаж: понедельник ${10*n}, вторник ${15*n}, среда ${20*n}. Всего?`,`Сату кестесі: дүйсенбі ${10*n}, сейсенбі ${15*n}, сәрсенбі ${20*n}. Барлығы?`),45*n,[step('Складываем значения всех дней.','Барлық күннің мәндерін қосамыз.'),step(`${10*n}+${15*n}+${20*n}=${45*n}.`,`${10*n}+${15*n}+${20*n}=${45*n}.`)]):l===2?num(b(`Сектор диаграммы составляет ${10*n}%. Найди его угол.`,`Диаграмма секторы ${10*n}%. Оның бұрышын тап.`),36*n,[step('Круг 360° соответствует 100%.','360° дөңгелек 100%-ға сәйкес.'),step(`360·${10*n}/100=${36*n}.`,`360·${10*n}/100=${36*n}.`)],'°'):num(b(`В группе A ${10*n} успешных из ${20*n}, в B ${12*n} из ${30*n}. На сколько процентных пунктов доля A выше?`,`A тобында ${20*n} адамның ${10*n}-і, B-де ${30*n} адамның ${12*n}-і табысты. A үлесі неше пайыздық тармаққа жоғары?`),10,[step('A: 50%, B: 40%.','A: 50%, B: 40%.'),step('Разность долей 50−40=10 процентных пунктов.','Үлес айырмасы 50−40=10 пайыздық тармақ.')],'п.п.'));

core('statistics','Диаграммы и данные','literacy',b('Среднее, медиана, мода, размах','Орташа, медиана, мода, құлаш'),'04',['numbers'],b('Выбрать и вычислить подходящую характеристику данных.','Деректерге сәйкес сипаттаманы таңдау және есептеу.'),b('Среднее — сумма значений, делённая на их количество. Медиана — середина после сортировки: при чётном количестве это среднее двух центральных значений. Мода — самое частое значение, её может не быть или быть несколько. Размах — максимум минус минимум. Одно большое значение сильно меняет среднее, но слабее влияет на медиану.','Орташа — мәндер қосындысының олардың санына қатынасы. Медиана — сұрыптаудан кейінгі орта: жұп санда екі орталық мәннің орташа шамасы. Мода — ең жиі мән; ол жоқ не бірнеше болуы мүмкін. Құлаш — максимум минус минимум. Бір үлкен мән орташаға қатты, медианаға азырақ әсер етеді.'),b('Среднее=(x₁+…+xₙ)/n; размах=max−min. Перед медианой отсортировать.','Орташа=(x₁+…+xₙ)/n; құлаш=max−min. Медиана алдында сұрыпта.'),b('Сортировка — запись в порядке возрастания. Частота — число появлений значения.','Сұрыптау — өсу ретімен жазу. Жиілік — мәннің кездесу саны.'),b('Медиана найдена без сортировки или среднее разделено не на количество данных.','Медиана сұрыптамай табылған немесе орташа деректер санына бөлінбеген.'),
 (i,n,l)=>l===1?num(b(`Среднее чисел ${n},${n+2},${n+4}?`,`${n},${n+2},${n+4} сандарының орташа мәні?`),n+2,[step(`Сумма ${3*n+6}, количество 3.`,`Қосынды ${3*n+6}, саны 3.`),step(`(${3*n+6})/3=${n+2}.`,`(${3*n+6})/3=${n+2}.`)]):l===2?num(b(`Медиана ряда ${n+7},${n},${n+3},${n+5}?`,`${n+7},${n},${n+3},${n+5} қатарының медианасы?`),n+4,[step(`Порядок ${n},${n+3},${n+5},${n+7}.`,`Реті ${n},${n+3},${n+5},${n+7}.`),step(`Два средних: (${n+3}+${n+5})/2=${n+4}.`,`Ортадағы екеуі: (${n+3}+${n+5})/2=${n+4}.`)]):num(b(`В ряду ${n},${n},${n},${n+2},${n+9} найди моду.`,`${n},${n},${n},${n+2},${n+9} қатарындағы моданы тап.`),n,[step(`${n} встречается 3 раза, остальные по одному.`,`${n} 3 рет, қалғандары бір рет кездеседі.`),step(`Наиболее частое значение ${n}.`,`Ең жиі мән ${n}.`)]));

core('probability','Неопределённость','literacy',b('Комбинаторика и вероятность','Комбинаторика және ықтималдық'),'05',['fractions','logic'],b('Посчитать равновозможные исходы и вероятность события.','Тең мүмкін нәтижелерді және оқиғаның ықтималдығын санау.'),b('Исход — один возможный результат опыта; событие — нужная группа исходов. Если каждый исход одинаково вероятен, вероятность равна числу подходящих исходов, делённому на все. Для последовательных независимых выборов числа вариантов перемножаются. Выбор без возвращения меняет число предметов во втором шаге.','Нәтиже — тәжірибенің бір мүмкін қорытындысы; оқиға — қажетті нәтижелер тобы. Барлық нәтиже бірдей ықтимал болса, ықтималдық қолайлы нәтижелер санының барлық санына қатынасына тең. Тәуелсіз кезекті таңдауларда нұсқа сандары көбейтіледі. Қайтармай таңдау екінші қадамдағы зат санын өзгертеді.'),b('P(A)=m/N при равновозможных исходах; 0≤P≤1; P(не A)=1−P(A).','Тең мүмкін нәтижелерде P(A)=m/N; 0≤P≤1; P(A емес)=1−P(A).'),b('Независимость означает, что первый результат не меняет вероятности второго.','Тәуелсіздік бірінші нәтиженің екіншісінің ықтималдығын өзгертпейтінін білдіреді.'),b('Исходы посчитаны как равновозможные без основания или забыто отсутствие возвращения.','Тең мүмкіндігі негізсіз қабылданған немесе қайтарылмайтыны ұмытылған.'),
 (i,n,l)=>l===1?num(b(`В мешке ${n} красных и ${n} синих шаров. Случайно берут один. Вероятность красного?`,`Қапта ${n} қызыл және ${n} көк шар. Біреуі кездейсоқ алынды. Қызылдың ықтималдығы?`),.5,[step(`Подходящих ${n}, всего ${2*n}.`,`Қолайлысы ${n}, барлығы ${2*n}.`),step(`${n}/${2*n}=0,5.`,`${n}/${2*n}=0,5.`)]):l===2?num(b(`Есть ${n+2} футболок и 3 пары брюк. Сколько комплектов из одной футболки и одних брюк?`,`${n+2} жейде және 3 шалбар бар. Бір жейде мен бір шалбардан неше жиынтық?`),3*(n+2),[step('Для каждой футболки есть 3 выбора брюк.','Әр жейдеге 3 шалбар таңдауы бар.'),step(`(${n+2})·3=${3*(n+2)}.`,`(${n+2})·3=${3*(n+2)}.`)]):num(b(`В мешке ${n+2} красных и 2 синих. Без возвращения берут 2. Вероятность двух синих?`,`Қапта ${n+2} қызыл және 2 көк шар. Қайтармай 2 шар алынды. Екі көктің ықтималдығы?`),2/((n+4)*(n+3)),[step(`Первый синий: 2/${n+4}; второй после него: 1/${n+3}.`,`Бірінші көк: 2/${n+4}; одан кейін екінші: 1/${n+3}.`),step(`P=2/(${n+4}·${n+3})≈${f(2/((n+4)*(n+3)))}.`,`P=2/(${n+4}·${n+3})≈${f(2/((n+4)*(n+3)))}.`)]));

core('dependencies','Изменение и зависимости','literacy',b('Зависимости и тарифы','Тәуелділіктер және тарифтер'),'06',['proportions'],b('Читать правило зависимости и выбирать подходящий тариф.','Тәуелділік ережесін оқу және тиімді тарифті таңдау.'),b('Прямая пропорциональность y=kx имеет постоянное отношение y/x. Обратная y=k/x имеет постоянное произведение xy. Не всякая зависимость пропорциональна: у тарифа C=a+bx есть постоянный платёж a, поэтому удвоение x не удваивает C. Сравнивать тарифы нужно при одном и том же потреблении.','Тура пропорционал y=kx тәуелділікте y/x қатынасы тұрақты. Кері y=k/x тәуелділікте xy көбейтіндісі тұрақты. Барлық тәуелділік пропорционал емес: C=a+bx тарифінде тұрақты a төлемі бар, x екі есе артқанда C екі еселенбейді. Тарифтерді бірдей тұтынуда салыстыр.'),b('C=a+bx, a — фиксированный платёж, b — цена единицы, x — количество.','C=a+bx, a — тұрақты төлем, b — бірлік бағасы, x — саны.'),b('Тариф — правило расчёта цены; постоянный платёж не зависит от количества.','Тариф — баға есептеу ережесі; тұрақты төлем санға тәуелді емес.'),b('Не учтён постоянный платёж или сравнивались разные количества.','Тұрақты төлем ескерілмеген немесе әртүрлі сандар салыстырылған.'),
 (i,n,l)=>l===1?num(b(`Такси: 500 ₸ посадка + 100 ₸/км. Цена за ${n+2} км?`,`Такси: 500 ₸ бастапқы төлем + 100 ₸/км. ${n+2} км құны?`),500+100*(n+2),[step('C=500+100x.','C=500+100x.'),step(`Подставляем x=${n+2}: ${500+100*(n+2)}.`,`x=${n+2} қоямыз: ${500+100*(n+2)}.`)],'₸'):l===2?num(b(`y=${12*n}/x. Найди y при x=3.`,`y=${12*n}/x. x=3 кезінде y тап.`),4*n,[step('x=3≠0, подстановка допустима.','x=3≠0, орнына қоюға болады.'),step(`${12*n}/3=${4*n}.`,`${12*n}/3=${4*n}.`)]):num(b(`Тариф A: ${500*n}+100x; B: ${200*n}+150x (₸). При каком x цены равны?`,`A тарифі: ${500*n}+100x; B: ${200*n}+150x (₸). Қай x кезінде бағалар тең?`),6*n,[step(`${500*n}+100x=${200*n}+150x ⇒ ${300*n}=50x.`,`${500*n}+100x=${200*n}+150x ⇒ ${300*n}=50x.`),step(`x=${6*n}; оба тарифа дают ${1100*n} ₸.`,`x=${6*n}; екі тариф те ${1100*n} ₸ береді.`) ]));

core('patterns','Изменение и зависимости','literacy',b('Закономерности и таблицы','Заңдылықтар және кестелер'),'07',['numbers'],b('Выявлять правило последовательности и проверять его на данных.','Тізбектің ережесін анықтау және деректерде тексеру.'),b('Несколько чисел могут продолжаться по разным правилам. Если правило не задано, ищи простую закономерность и объясни, почему она соответствует всем данным; не выдавай догадку за единственное доказанное правило. В задачах ниже правило задано или указан тип изменения. Таблица связывает значения по строкам: сначала прочитай заголовки.','Бірнеше сан әртүрлі ережемен жалғасуы мүмкін. Ереже берілмесе, қарапайым заңдылық іздеп, барлық дерекке сәйкестігін түсіндір; болжамды жалғыз дәлелденген ереже деп айтпа. Төмендегі есептерде ереже не өзгеріс түрі берілген. Кесте мәндерді жол бойынша байланыстырады: алдымен тақырыптарды оқы.'),b('Постоянная разность: aₙ=a₁+(n−1)d. Квадраты: aₙ=n².','Тұрақты айырым: aₙ=a₁+(n−1)d. Квадраттар: aₙ=n².'),b('Закономерность — правило перехода, согласованное со всеми указанными данными.','Заңдылық — барлық берілген дерекке сәйкес өту ережесі.'),b('Выбрано правило по двум числам без проверки остальных.','Ереже екі санға ғана қарап таңдалып, қалғандары тексерілмеген.'),
 (i,n,l)=>l===1?num(b(`Ряд начинается ${n},${n+3},${n+6}; каждый раз прибавляют 3. Следующее число?`,`Қатар ${n},${n+3},${n+6} деп басталады; әр жолы 3 қосылады. Келесі сан?`),n+9,[step('Постоянная прибавка 3.','Тұрақты қосылғыш 3.'),step(`${n+6}+3=${n+9}.`,`${n+6}+3=${n+9}.`)]):l===2?num(b(`Таблица задаёт y=x²+1. При x=${n+2} чему равно y?`,`Кесте y=x²+1 ережесін береді. x=${n+2} кезінде y неше?`),(n+2)**2+1,[step(`Квадрат входа ${(n+2)**2}.`,`Кірістің квадраты ${(n+2)**2}.`),step(`Прибавляем 1: ${(n+2)**2+1}.`,`1 қосамыз: ${(n+2)**2+1}.`)]):num(b(`В ряду a₁=${n}, разности между соседями 1,3,5,7,… Найди a₅.`,`Қатарда a₁=${n}, көршілес мүшелер айырымы 1,3,5,7,… a₅ тап.`),n+16,[step('Четыре перехода: 1+3+5+7=16.','Төрт өту: 1+3+5+7=16.'),step(`a₅=${n}+16=${n+16}.`,`a₅=${n}+16=${n+16}.`)]));

core('geometric-logic','Пространство и форма','literacy',b('Геометрическая логика','Геометриялық логика'),'08',['angles'],b('Разбивать фигуру на части и рассуждать о форме.','Фигураны бөліктерге бөлу және пішіні туралы пайымдау.'),b('Сложную фигуру удобно разбить на прямоугольники или треугольники. Складывая площади, не считай общую часть дважды. При разрезании площадь сохраняется, периметр может вырасти из-за новых краёв. Если куб разделили на маленькие кубы, число частей определяется по трём направлениям.','Күрделі фигураны тіктөртбұрыштарға не үшбұрыштарға бөлген ыңғайлы. Аудандарды қосқанда ортақ бөлікті екі рет санама. Кескенде аудан сақталады, жаңа шеттерден периметр өсуі мүмкін. Кубты кіші кубтарға бөлгенде бөліктер саны үш бағыт бойынша анықталады.'),b('Sобъединения=S₁+S₂−Sобщей части; N кубиков=k³ при k частях каждого ребра.','Sбірігу=S₁+S₂−Sортақ бөлік; әр қыры k бөлік болса, кубтар саны N=k³.'),b('Разбиение — части без перекрытия; наложение — общая часть двух фигур.','Бөлу — қабаттаспайтын бөліктер; қабаттасу — екі фигураның ортақ бөлігі.'),b('Площадь и периметр ошибочно считаются одинаково изменяющимися.','Аудан мен периметр бірдей өзгереді деп алынған.'),
 (i,n,l)=>l===1?num(b(`Квадрат ${n+2}×${n+2} разрезан на две равные части. Общая площадь частей?`,`${n+2}×${n+2} шаршы екі тең бөлікке кесілді. Бөліктердің жалпы ауданы?`),(n+2)**2,[step('Разрезание сохраняет площадь.','Кесу ауданды сақтайды.'),step(`Общая площадь ${(n+2)**2}.`,`Жалпы аудан ${(n+2)**2}.`)]):l===2?num(b(`Из квадрата ${n+4}×${n+4} вырезали квадрат 2×2. Оставшаяся площадь?`,`${n+4}×${n+4} шаршыдан 2×2 шаршы қиылды. Қалған аудан?`),(n+4)**2-4,[step(`Большая площадь ${(n+4)**2}, вырезанная 4.`,`Үлкен аудан ${(n+4)**2}, кесілгені 4.`),step(`Вычитаем: ${(n+4)**2-4}.`,`Азайтамыз: ${(n+4)**2-4}.`)]):num(b(`Каждое ребро куба разделено на ${n+1} равных частей; разрезы параллельны граням. Маленьких кубов?`,`Кубтың әр қыры ${n+1} тең бөлікке бөлініп, жақтарына параллель кесілді. Кіші кубтар неше?`),(n+1)**3,[step(`По ${n+1} частей в трёх направлениях.`,`Үш бағыттың әрқайсысында ${n+1} бөлік.`),step(`N=${n+1}³=${(n+1)**3}.`,`N=${n+1}³=${(n+1)**3}.`)]));

core('practical-area','Пространство и форма','literacy',b('Площадь, периметр и ремонт','Аудан, периметр және жөндеу'),'09',['quadrilaterals','units'],b('Выбирать площадь или периметр для практического расчёта.','Практикалық есепте аудан не периметрді таңдау.'),b('Для покрытия пола нужна площадь, для ограды — периметр. При расчёте упаковок поделить площадь на покрытие упаковки и округлить вверх: часть упаковки купить нельзя. Размеры должны иметь одинаковые единицы, площадь — квадратные. Проёмы вычитаются только если это указано условием.','Еден жабуға аудан, қоршауға периметр керек. Қаптама санын табу үшін ауданды бір қаптама жабатын ауданға бөліп, жоғары дөңгелекте: қаптаманың бөлігін сатып ала алмайсың. Өлшемдер бірдей бірлікте, аудан шаршы бірлікте болуы тиіс. Ойықтар шартта айтылса ғана азайтылады.'),b('Pпрям=2(a+b); Sпрям=ab; Nупак=ceil(S/Sупак). ceil — округление вверх.','Pтікт=2(a+b); Sтікт=ab; Nқап=ceil(S/Sқап). ceil — жоғары дөңгелектеу.'),b('Периметр — длина границы; округление вверх — ближайшее не меньшее целое.','Периметр — шекара ұзындығы; жоғары дөңгелектеу — кем емес ең жақын бүтін сан.'),b('Для покрытия использован периметр или число упаковок округлено вниз.','Жабуға периметр алынған немесе қаптама саны төмен дөңгелектелген.'),
 (i,n,l)=>l===1?num(b(`Сад ${n+5}×4 м. Длина ограды без ворот?`,`${n+5}×4 м бақ. Қақпасыз қоршау ұзындығы?`),2*n+18,[step('P=2(a+b).','P=2(a+b).'),step(`2(${n+5}+4)=${2*n+18}.`,`2(${n+5}+4)=${2*n+18}.`)],'м'):l===2?num(b(`Пол ${n+3}×4 м. Плитка покрывает 2 м² за упаковку. Сколько упаковок?`,`Еден ${n+3}×4 м. Бір қаптама плитка 2 м² жабады. Неше қаптама?`),2*(n+3),[step(`S=${4*(n+3)} м².`,`S=${4*(n+3)} м².`),step(`N=${4*(n+3)}/2=${2*(n+3)}.`,`N=${4*(n+3)}/2=${2*(n+3)}.`)]):num(b(`Нужно покрыть ${10+n} м². Упаковка покрывает 3 м². Минимум целых упаковок?`,`${10+n} м² жабу керек. Бір қаптама 3 м² жабады. Ең аз бүтін қаптама саны?`),Math.ceil((10+n)/3),[step(`Делим ${10+n}/3≈${f((10+n)/3)}.`,`${10+n}/3≈${f((10+n)/3)} бөлеміз.`),step(`Округляем вверх: ${Math.ceil((10+n)/3)}.`,`Жоғары дөңгелектейміз: ${Math.ceil((10+n)/3)}.`)]));

core('surface','Пространство и форма','literacy',b('Поверхность и упаковка','Бет және қаптама'),'10',['volumes'],b('Найти площадь материала для упаковки, учитывая открытые стороны.','Ашық жақтарды ескеріп, қаптау материалы ауданын табу.'),b('Поверхность — наружные грани тела. Для закрытой коробки учитываются шесть граней; у коробки без крышки одна верхняя грань исключается. Этикетка цилиндрической банки покрывает только боковую поверхность, которая разворачивается в прямоугольник высоты h и длины 2πr. Запас материала прибавляй после расчёта нужной площади.','Бет — дененің сыртқы жақтары. Жабық қораптың алты жағы есептеледі; қақпақсыз қорапта жоғарғы жақ алынбайды. Цилиндр ыдыстың жапсырмасы тек бүйір бетті жабады: ол биіктігі h, ұзындығы 2πr тіктөртбұрышқа жазылады. Материал қорын қажетті ауданнан кейін қос.'),b('Sкоробки=2(ab+ac+bc); Sбез крышки=ab+2ac+2bc; Sбок цилиндра=2πrh.','Sқорап=2(ab+ac+bc); Sқақпақсыз=ab+2ac+2bc; Sцилиндр бүйір=2πrh.'),b('Развёртка — поверхность, разложенная в плоскую фигуру.','Жазба — жазық фигураға жайылған бет.'),b('Учтена крышка у открытой коробки или объём вместо площади материала.','Ашық қорапта қақпақ есептелген немесе материал ауданына көлем алынған.'),
 (i,n,l)=>l===1?num(b(`Куб ребра ${n+1} см. Площадь шести граней?`,`Қыры ${n+1} см кубтың алты жағының ауданы?`),6*(n+1)**2,[step(`Одна грань ${(n+1)**2} см².`,`Бір жақ ${(n+1)**2} см².`),step(`Умножаем на 6: ${6*(n+1)**2}.`,`6-ға көбейтеміз: ${6*(n+1)**2}.`)],'см²'):l===2?num(b(`Коробка без крышки: основание ${n+2}×3 см, высота 4 см. Площадь материала?`,`Қақпақсыз қорап: табаны ${n+2}×3 см, биіктігі 4 см. Материал ауданы?`),11*(n+2)+24,[step(`Дно ${3*(n+2)}, боковые 2·${n+2}·4+2·3·4.`,`Түбі ${3*(n+2)}, бүйірлері 2·${n+2}·4+2·3·4.`),step(`Сумма ${11*(n+2)+24}.`,`Қосындысы ${11*(n+2)+24}.`)],'см²'):num(b(`Для куба ребра ${n+2} см нужен материал с запасом 10% на все грани. Площадь?`,`Қыры ${n+2} см кубтың барлық жағына 10% қорымен материал керек. Ауданы?`),6.6*(n+2)**2,[step(`Без запаса 6·${n+2}²=${6*(n+2)**2}.`,`Қорсыз 6·${n+2}²=${6*(n+2)**2}.`),step(`Умножаем на 1,1: ${f(6.6*(n+2)**2)}.`,`1,1-ге көбейтеміз: ${f(6.6*(n+2)**2)}.`)],'см²'));

core('exponential-systems','Системы уравнений','profile',b('Системы показательных уравнений','Көрсеткіштік теңдеулер жүйесі'),'09',['exponential','linear-systems','nonlinear-systems'],b('Решать показательные системы через показатели и положительную замену.','Көрсеткіштік жүйелерді көрсеткіштер мен оң алмастыру арқылы шешу.'),b('С одинаковыми основаниями сначала сравни показатели. У произведения 2ˣ2ʸ показатель x+y. Если дана сумма степеней, вводим u=2ˣ,v=2ʸ: получаем сумму и произведение положительных чисел. Находим u,v квадратным уравнением, затем возвращаемся к x,y через логарифм. Проверяем обе исходные строки.','Бірдей негіздерде алдымен көрсеткіштерді салыстыр. 2ˣ2ʸ көбейтіндісінің көрсеткіші x+y. Дәрежелер қосындысы берілсе, u=2ˣ,v=2ʸ деп аламыз: оң сандардың қосындысы мен көбейтіндісі шығады. u,v-ны квадрат теңдеуден тауып, логарифм арқылы x,y-ке қайтамыз. Екі бастапқы жолды тексер.'),b('u=2ˣ>0,v=2ʸ>0; u+v=S,uv=P ⇒ t²−St+P=0. x=log₂u,y=log₂v.','u=2ˣ>0,v=2ʸ>0; u+v=S,uv=P ⇒ t²−St+P=0. x=log₂u,y=log₂v.'),b('Замена переводит степени в новые положительные неизвестные; отрицательные u,v исключаются.','Алмастыру дәрежелерді жаңа оң белгісіздерге ауыстырады; теріс u,v алынады.'),b('Ответ дан для u вместо x или принята неположительная замена.','Жауап x орнына u үшін берілген немесе оң емес алмастыру қабылданған.'),
 (i,n,l)=>l===1?num(b(`2ˣ=${2**n}, 2ʸ=4. Найди x+y.`,`2ˣ=${2**n}, 2ʸ=4. x+y тап.`),n+2,[step(`x=${n},y=2.`,`x=${n},y=2.`),step(`x+y=${n+2}.`,`x+y=${n+2}.`)]):l===2?num(b(`2^(x+y)=${2**(n+3)}, 2^(x−y)=${2**(n-1)}. Найди x.`,`2^(x+y)=${2**(n+3)}, 2^(x−y)=${2**(n-1)}. x тап.`),n+1,[step(`x+y=${n+3},x−y=${n-1}.`,`x+y=${n+3},x−y=${n-1}.`),step(`2x=${2*n+2},x=${n+1}; y=2.`,`2x=${2*n+2},x=${n+1}; y=2.`)]):num(b(`2ˣ+2ʸ=${3*2**n}, 2^(x+y)=${2**(2*n+1)}. Найди большее из x,y.`,`2ˣ+2ʸ=${3*2**n}, 2^(x+y)=${2**(2*n+1)}. x,y-дің үлкенін тап.`),n+1,[step(`u+v=${3*2**n},uv=${2**(2*n+1)}.`,`u+v=${3*2**n},uv=${2**(2*n+1)}.`),step(`Корни t²−${3*2**n}t+${2**(2*n+1)}=0: ${2**n},${2**(n+1)}.`,`t²−${3*2**n}t+${2**(2*n+1)}=0 түбірлері: ${2**n},${2**(n+1)}.`),step(`x,y равны ${n},${n+1} в любом порядке; большее ${n+1}.`,`x,y кез келген ретпен ${n},${n+1}; үлкені ${n+1}.`)]));

core('log-systems','Системы уравнений','profile',b('Системы логарифмических уравнений','Логарифмдік теңдеулер жүйесі'),'09',['log-equations','nonlinear-systems'],b('Сохранять положительность всех аргументов и преобразовывать систему.','Барлық аргументтің оңдығын сақтау және жүйені түрлендіру.'),b('В каждой строке запиши ОДЗ. Сумма логарифмов положительных x,y даёт логарифм xy, разность — x/y. Когда есть x+y и xy, находим два числа как корни квадратного уравнения. Каждую найденную пару проверяем: даже верный алгебраический результат может не иметь допустимых логарифмов.','Әр жолда ММЖ жаз. Оң x,y логарифмдерінің қосындысы xy логарифмін, айырмасы x/y логарифмін береді. x+y мен xy берілсе, екі санды квадрат теңдеудің түбірі ретінде табамыз. Әр жұпты тексер: дұрыс алгебралық нәтиже логарифмге жарамсыз болуы мүмкін.'),b('log₂x+log₂y=log₂(xy); log₂x−log₂y=log₂(x/y), x,y>0.','log₂x+log₂y=log₂(xy); log₂x−log₂y=log₂(x/y), x,y>0.'),b('Аргументы должны быть положительны по отдельности, а не только их произведение.','Аргументтердің тек көбейтіндісі емес, әрқайсысы жеке оң болуы тиіс.'),b('Два отрицательных числа приняты потому, что их произведение положительно.','Екі теріс сан олардың көбейтіндісі оң болғандықтан қабылданған.'),
 (i,n,l)=>l===1?num(b(`log₂x=${n}, log₂y=2. Найди xy.`,`log₂x=${n}, log₂y=2. xy тап.`),2**(n+2),[step(`x=${2**n}>0,y=4>0.`,`x=${2**n}>0,y=4>0.`),step(`xy=${2**(n+2)}.`,`xy=${2**(n+2)}.`)]):l===2?num(b(`log₂x+log₂y=${n+3}, log₂x−log₂y=${n-1}. Найди x.`,`log₂x+log₂y=${n+3}, log₂x−log₂y=${n-1}. x тап.`),2**(n+1),[step(`Складываем: 2log₂x=${2*n+2}.`,`Қосамыз: 2log₂x=${2*n+2}.`),step(`log₂x=${n+1} ⇒ x=${2**(n+1)}.`,`log₂x=${n+1} ⇒ x=${2**(n+1)}.`)]):num(b(`log₂x+log₂y=log₂${(n+1)*(n+4)}, x+y=${2*n+5}. Найди большее из x,y.`,`log₂x+log₂y=log₂${(n+1)*(n+4)}, x+y=${2*n+5}. x,y-дің үлкенін тап.`),n+4,[step(`ОДЗ x,y>0; xy=${(n+1)*(n+4)}.`,`ММЖ x,y>0; xy=${(n+1)*(n+4)}.`),step(`t²−${2*n+5}t+${(n+1)*(n+4)}=0 даёт ${n+1},${n+4}; оба положительны.`,`t²−${2*n+5}t+${(n+1)*(n+4)}=0 түбірлері ${n+1},${n+4}; екеуі де оң.`),step(`Большее ${n+4}.`,`Үлкені ${n+4}.`)]));

core('irrational-systems','Системы уравнений','profile',b('Системы иррациональных уравнений','Иррационал теңдеулер жүйесі'),'09',['irrational','nonlinear-systems'],b('Решать системы с несколькими корнями, проверяя каждое возведение в квадрат.','Бірнеше түбірі бар жүйелерді шешіп, әр квадраттауды тексеру.'),b('Корень неотрицателен, поэтому обе стороны изолированного равенства должны быть неотрицательны. Квадрат суммы корней содержит двойное произведение. В замене u=√x,v=√y ограничения u,v≥0 обязательны. После решения возвращаем x=u²,y=v² и подставляем в исходную систему.','Түбір теріс емес, сондықтан жеке қалдырылған теңдіктің екі жағы да теріс емес болуы керек. Түбірлер қосындысының квадратында екі еселенген көбейтінді бар. u=√x,v=√y алмастыруында u,v≥0 міндетті. Шешкен соң x=u²,y=v²-ке қайтып, бастапқы жүйеге қоямыз.'),b('(√x+√y)²=x+y+2√xy, x,y≥0; u=√x≥0, v=√y≥0.','(√x+√y)²=x+y+2√xy, x,y≥0; u=√x≥0, v=√y≥0.'),b('Неотрицательный означает ≥0; квадрат равенства может добавить посторонние решения.','Теріс емес деген ≥0; теңдікті квадраттау бөгде шешім қосуы мүмкін.'),b('Пропущено 2√xy при квадрате суммы.','Қосынды квадратында 2√xy қалдырылған.'),
 (i,n,l)=>l===1?num(b(`√x=${n}, √y=${n+1}. Найди x+y.`,`√x=${n}, √y=${n+1}. x+y тап.`),n*n+(n+1)**2,[step(`x=${n*n},y=${(n+1)**2}, оба ≥0.`,`x=${n*n},y=${(n+1)**2}, екеуі ≥0.`),step(`x+y=${n*n+(n+1)**2}.`,`x+y=${n*n+(n+1)**2}.`)]):l===2?num(b(`√(x+y)=${n+3}, √(x−y)=${n+1}. Найди x.`,`√(x+y)=${n+3}, √(x−y)=${n+1}. x тап.`),((n+3)**2+(n+1)**2)/2,[step(`x+y=${(n+3)**2}, x−y=${(n+1)**2}.`,`x+y=${(n+3)**2}, x−y=${(n+1)**2}.`),step(`Сумма строк: 2x=${(n+3)**2+(n+1)**2}, x=${((n+3)**2+(n+1)**2)/2}.`,`Жолдарды қосамыз: 2x=${(n+3)**2+(n+1)**2}, x=${((n+3)**2+(n+1)**2)/2}.`)]):num(b(`√x+√y=${2*n+2}, x+y=${n*n+(n+2)**2}. Найди большее из x,y.`,`√x+√y=${2*n+2}, x+y=${n*n+(n+2)**2}. x,y-дің үлкенін тап.`),(n+2)**2,[step(`u=√x,v=√y≥0; u+v=${2*n+2}.`,`u=√x,v=√y≥0; u+v=${2*n+2}.`),step(`2uv=(u+v)²−(x+y)=${2*n*(n+2)} ⇒ uv=${n*(n+2)}.`,`2uv=(u+v)²−(x+y)=${2*n*(n+2)} ⇒ uv=${n*(n+2)}.`),step(`u,v=${n},${n+2}; большее исходное число ${(n+2)**2}.`,`u,v=${n},${n+2}; бастапқы үлкен сан ${(n+2)**2}.`)]));

core('trig-systems','Системы уравнений','profile',b('Системы тригонометрических уравнений','Тригонометриялық теңдеулер жүйесі'),'09',['trig-equations','trig-identities'],b('Найти общие углы нескольких тригонометрических условий.','Бірнеше тригонометриялық шарттың ортақ бұрыштарын табу.'),b('Каждое уравнение отмечает точки единичной окружности. Для системы нужны точки, подходящие всем уравнениям. Sin определяет высоту, cos горизонтальную координату, поэтому пара часто оставляет одну точку на обороте. Сумма и произведение функций позволяют сделать замену u=sin x,v=cos x; дополнительно u²+v²=1.','Әр теңдеу бірлік шеңбердің нүктелерін белгілейді. Жүйеге барлық теңдеуге сай нүктелер қажет. Sin биіктікті, cos көлденең координатаны анықтайды, сондықтан жұп бір айналымда жиі бір нүкте қалдырады. Функциялар қосындысы мен көбейтіндісінде u=sin x,v=cos x алмастыруын жасап, u²+v²=1 ескереміз.'),b('sin x=0,cos x=1 ⇒ x=2πk. sin x+cos x=1, sin x·cos x=0 ⇒ x=2πk или π/2+2πk.','sin x=0,cos x=1 ⇒ x=2πk. sin x+cos x=1, sin x·cos x=0 ⇒ x=2πk немесе π/2+2πk.'),b('Общий угол соответствует одновременно вертикальной и горизонтальной координатам.','Ортақ бұрыш тік және көлденең координаталардың екеуіне де сәйкес.'),b('Корни двух уравнений объединены вместо пересечения.','Екі теңдеудің түбірлері қиылыстыру орнына біріктірілген.'),
 (i,n,l)=>l===1?num(b(`sin x=0,cos x=1. Сколько решений на [0;${2*n}π)?`,`sin x=0,cos x=1. [0;${2*n}π) аралығында неше шешім?`),n,[step('x=2πk.','x=2πk.'),step(`k=0,…,${n-1}: ${n} решений.`,`k=0,…,${n-1}: ${n} шешім.`)]):l===2?num(b(`sin(x−${n}°)=1/2, cos(x−${n}°)=−√3/2. Найди x на [0;360°).`,`sin(x−${n}°)=1/2, cos(x−${n}°)=−√3/2. [0;360°) ішінде x тап.`),150+n,[step('Угол с указанными координатами 150° во второй четверти.','Берілген координаталардағы бұрыш екінші ширекте 150°.'),step(`x−${n}°=150°, x=${150+n}°.`,`x−${n}°=150°, x=${150+n}°.`)],'°'):num(b(`sin x+cos x=1, sin x cos x=0. Сколько решений на [0;${2*(n+1)}π)?`,`sin x+cos x=1, sin x cos x=0. [0;${2*(n+1)}π) ішінде неше шешім?`),2*(n+1),[step('Если произведение ноль, одна функция 0, другая из суммы 1.','Көбейтінді нөл болса, бір функция 0, екіншісі қосындыдан 1.'),step('На каждом обороте x=0 и π/2 с добавлением 2πk.','Әр айналымда x=0 және π/2, оларға 2πk қосылады.'),step(`Оборотов ${n+1}, всего ${2*(n+1)}.`,`Айналым ${n+1}, барлығы ${2*(n+1)}.`)]));

core('exponential-inequalities','Неравенства','profile',b('Показательные неравенства','Көрсеткіштік теңсіздіктер'),'10',['exponential','linear-inequalities'],b('Решать неравенство с основанием больше или меньше единицы.','Негізі бірден үлкен не кіші теңсіздікті шешу.'),b('Основание a>1 задаёт возрастающую функцию: сравнение степеней сохраняет знак для показателей. При 0<a<1 функция убывает, знак для показателей меняется. Для суммы степеней замена t=aˣ>0 переводит задачу в квадратное неравенство. Сначала реши для t, потом верни x с учётом монотонности.','a>1 негізі өсетін функция береді: дәрежелерді салыстыру көрсеткіш таңбасын сақтайды. 0<a<1 кезінде функция кемиді, көрсеткіштер үшін таңба өзгереді. Дәрежелер қосындысында t=aˣ>0 алмастыруы квадрат теңсіздікке әкеледі. Алдымен t-ны шеш, кейін монотондықты ескеріп x-ке қайт.'),b('a>1: aᵘ≤aᵛ ⇔ u≤v. 0<a<1: aᵘ≤aᵛ ⇔ u≥v.','a>1: aᵘ≤aᵛ ⇔ u≤v. 0<a<1: aᵘ≤aᵛ ⇔ u≥v.'),b('Монотонность позволяет сравнивать входы по значениям функции.','Монотондылық функция мәндері бойынша кірістерді салыстыруға мүмкіндік береді.'),b('Основание 1/2 обработано как возрастающее.','1/2 негізі өсетін деп алынған.'),
 (i,n,l)=>l===1?select(b(`Выбери решения 2ˣ≥${2**n}.`,`2ˣ≥${2**n} шешімдерін таңда.`),[`${n}`,`${n+2}`],[`${n-2}`,`${n-1}`,`${n}`,`${n+2}`],[step(`2ˣ≥2^${n} ⇒ x≥${n}.`,`2ˣ≥2^${n} ⇒ x≥${n}.`),step('Граница включена.','Шекара кіреді.')]):l===2?num(b(`Сколько целых x на [0;${n+4}] удовлетворяют (1/2)ˣ>(1/2)^${n+2}?`,`[0;${n+4}] ішінде (1/2)ˣ>(1/2)^${n+2} шартын неше бүтін x қанағаттандырады?`),n+2,[step(`Функция убывает: x<${n+2}.`,`Функция кемиді: x<${n+2}.`),step(`x=0,…,${n+1}, всего ${n+2}.`,`x=0,…,${n+1}, барлығы ${n+2}.`)]):num(b(`Сколько целых x: 4ˣ−${3*2**n}·2ˣ+${2**(2*n+1)}≤0?`,`4ˣ−${3*2**n}·2ˣ+${2**(2*n+1)}≤0 шартын неше бүтін x шешеді?`),2,[step(`t=2ˣ>0; (t−${2**n})(t−${2**(n+1)})≤0.`,`t=2ˣ>0; (t−${2**n})(t−${2**(n+1)})≤0.`),step(`${2**n}≤2ˣ≤${2**(n+1)} ⇒ ${n}≤x≤${n+1}.`,`${2**n}≤2ˣ≤${2**(n+1)} ⇒ ${n}≤x≤${n+1}.`),step(`Два целых: ${n},${n+1}.`,`Екі бүтін: ${n},${n+1}.`)]));

core('log-inequalities','Неравенства','profile',b('Логарифмические неравенства','Логарифмдік теңсіздіктер'),'10',['logarithms','linear-inequalities'],b('Совмещать область логарифма с монотонностью основания.','Логарифм облысын негіздің монотондығымен біріктіру.'),b('Вначале аргумент строго положителен. При основании больше 1 сравнение аргументов сохраняет знак; между 0 и 1 меняет знак. Итог — пересечение неравенства с ОДЗ. Например log₁/₂x>1 даёт 0<x<1/2, а не просто x<1/2.','Алдымен аргумент қатаң оң. Негіз 1-ден үлкен болса, аргументтерді салыстыру таңбаны сақтайды; 0 мен 1 арасында таңбаны өзгертеді. Нәтиже — теңсіздік пен ММЖ қиылысуы. Мысалы log₁/₂x>1 шарты 0<x<1/2 береді, тек x<1/2 емес.'),b('a>1: logₐg≥c ⇔ g≥aᶜ. 0<a<1: 0<g≤aᶜ.','a>1: logₐg≥c ⇔ g≥aᶜ. 0<a<1: 0<g≤aᶜ.'),b('Логарифм от нуля не определён; граница ОДЗ всегда открыта.','Нөл логарифмі анықталмаған; ММЖ шекарасы әрдайым ашық.'),b('Забыта нижняя граница положительности аргумента.','Аргументтің оңдық төменгі шекарасы ұмытылған.'),
 (i,n,l)=>l===1?num(b(`Наименьшее целое x для log₂x≥${n}?`,`log₂x≥${n} үшін ең кіші бүтін x неше?`),2**n,[step(`x≥2^${n}; условие x>0 выполнено.`,`x≥2^${n}; x>0 шарты орындалған.`),step(`Минимум ${2**n}.`,`Минимум ${2**n}.`)]):l===2?num(b(`Сколько положительных целых x решают log₁/₂x>−${n}?`,`log₁/₂x>−${n} шартын неше оң бүтін x шешеді?`),2**n-1,[step(`Основание убывающее: 0<x<(1/2)^${-n}=${2**n}.`,`Негіз кемитін: 0<x<(1/2)^${-n}=${2**n}.`),step(`x=1,…,${2**n-1}.`,`x=1,…,${2**n-1}.`)]):num(b(`Сколько целых x: log₂(x−${n})≤2?`,`log₂(x−${n})≤2 шартын неше бүтін x шешеді?`),4,[step(`ОДЗ x>${n}; из неравенства x−${n}≤4.`,`ММЖ x>${n}; теңсіздіктен x−${n}≤4.`),step(`x=${n+1},${n+2},${n+3},${n+4}; 4 числа.`,`x=${n+1},${n+2},${n+3},${n+4}; 4 сан.`)]));

core('irrational-inequalities','Неравенства','profile',b('Иррациональные неравенства','Иррационал теңсіздіктер'),'10',['irrational','quadratic-inequalities'],b('Правильно сравнивать корень и выражение, учитывая их знаки.','Түбір мен өрнектің таңбаларын ескеріп, дұрыс салыстыру.'),b('√g(x) существует при g≥0 и всегда ≥0. Если √g≤h, необходимо h≥0, после чего можно сравнить g≤h². Если √g≥h и h≤0, неравенство автоматически верно на ОДЗ; при h>0 квадрат равносилен. Нельзя безусловно квадратировать две стороны разных знаков.','√g(x) g≥0 кезінде бар және әрдайым ≥0. √g≤h болса, h≥0 қажет, содан кейін g≤h² салыстырамыз. √g≥h және h≤0 болса, теңсіздік ММЖ-да автоматты дұрыс; h>0 кезінде квадраттау мәндес. Таңбалары әртүрлі екі бөлікті шартсыз квадраттауға болмайды.'),b('√g≤h ⇔ 0≤g≤h² и h≥0. √g≥h при h≤0 требует только g≥0.','√g≤h ⇔ 0≤g≤h² және h≥0. h≤0 кезінде √g≥h тек g≥0 талап етеді.'),b('Разбор случаев — отдельное решение при положительном и неположительном правом выражении.','Жағдайларға бөлу — оң және оң емес оң жақ өрнекті жеке қарастыру.'),b('Возведение в квадрат выполнено без проверки знаков.','Квадраттау таңбаларды тексермей орындалған.'),
 (i,n,l)=>l===1?num(b(`Сколько целых x решают √(x−${n})≤${n}?`,`√(x−${n})≤${n} шартын неше бүтін x шешеді?`),n*n+1,[step(`0≤x−${n}≤${n*n}.`,`0≤x−${n}≤${n*n}.`),step(`[${n};${n+n*n}] содержит ${n*n+1} целых.`,`[${n};${n+n*n}] ішінде ${n*n+1} бүтін сан.`)]):l===2?num(b(`Сколько целых x решают √(2x+1)<${n+2}?`,`√(2x+1)<${n+2} шартын неше бүтін x шешеді?`),Math.ceil(((n+2)**2-1)/2),[step(`−1/2≤x<${((n+2)**2-1)/2}.`,`−1/2≤x<${((n+2)**2-1)/2}.`),step(`Первое целое 0, всего ${Math.ceil(((n+2)**2-1)/2)}.`,`Бірінші бүтін 0, барлығы ${Math.ceil(((n+2)**2-1)/2)}.`)]):num(b(`Сколько неотрицательных целых x удовлетворяют √(x+${n})≥x?`,`√(x+${n})≥x шартын неше теріс емес бүтін x қанағаттандырады?`),Math.floor((1+Math.sqrt(1+4*n))/2)+1,[step(`При x≥0 квадрат равносилен: x²−x−${n}≤0.`,`x≥0 кезінде квадраттау мәндес: x²−x−${n}≤0.`),step(`0≤x≤(1+√${1+4*n})/2.`,`0≤x≤(1+√${1+4*n})/2.`),step(`Целые начиная с 0: ${Math.floor((1+Math.sqrt(1+4*n))/2)+1}.`,`0-ден басталатын бүтіндер: ${Math.floor((1+Math.sqrt(1+4*n))/2)+1}.`)]));

core('trig-inequalities','Неравенства','profile',b('Тригонометрические неравенства','Тригонометриялық теңсіздіктер'),'10',['trig-circle','trig-equations'],b('Найти дуги решений и перенести их с периодом.','Шешім доғаларын тауып, периодпен қайталау.'),b('sin x>c выбирает точки окружности выше горизонтальной линии y=c. Сначала найдём границы уравнением sin x=c, затем возьмём нужную дугу. При нестрогом сравнении границы включаются. Для sin(kx) решаем по углу kx, после чего делим границы и период на k>0.','sin x>c шеңбердің y=c көлденең сызығынан жоғары нүктелерін таңдайды. Алдымен sin x=c теңдеуінен шекараны тауып, қажетті доғаны аламыз. Қатаң емес салыстыруда шекаралар кіреді. sin(kx) үшін kx бұрышын шешіп, k>0 болғанда шекаралар мен периодты k-ға бөлеміз.'),b('sin x>0 ⇔ 2πk<x<π+2πk. sin x>1/2 ⇔ π/6+2πk<x<5π/6+2πk.','sin x>0 ⇔ 2πk<x<π+2πk. sin x>1/2 ⇔ π/6+2πk<x<5π/6+2πk.'),b('Дуга решений — участок окружности с нужной высотой или горизонтальной координатой.','Шешім доғасы — қажетті биіктігі не көлденең координатасы бар шеңбер бөлігі.'),b('Выбрана нижняя дуга или забыто деление периода при kx.','Төменгі доға таңдалған немесе kx кезінде период бөлуі ұмытылған.'),
 (i,n,l)=>l===1?select(b(`Для sin(x−${n}°)>0 выбери x.`,`sin(x−${n}°)>0 үшін x таңда.`),[`${n+30}°`,`${n+120}°`],[`${n}°`,`${n+30}°`,`${n+120}°`,`${n+270}°`],[step(`Угол x−${n}° должен быть в верхней полуокружности.`,`x−${n}° бұрышы жоғарғы жарты шеңберде болуы керек.`),step('30° и 120° имеют положительный синус; 0° исключён.','30° және 120° синусы оң; 0° алынбайды.')]):l===2?num(b(`Сколько точек x=πk/2 на [0;${2*(n+1)}π) удовлетворяют sin x≥0?`,`[0;${2*(n+1)}π) ішінде x=πk/2 нүктелерінің нешеуі sin x≥0 шартын орындайды?`),3*(n+1),[step('На одном обороте подходят 0,π/2,π; 3π/2 не подходит.','Бір айналымда 0,π/2,π сәйкес; 3π/2 сәйкес емес.'),step(`По 3 в каждом из ${n+1} оборотов: ${3*(n+1)}.`,`${n+1} айналымның әрқайсысында 3: ${3*(n+1)}.`)]):num(b(`Сколько отдельных интервалов решений sin(${n+1}x)>1/2 на [0;2π)?`,`[0;2π) ішінде sin(${n+1}x)>1/2 шешімдерінің неше бөлек аралығы бар?`),n+1,[step(`Угол ${n+1}x проходит ${n+1} оборотов.`,`${n+1}x бұрышы ${n+1} айналым жасайды.`),step(`На каждом обороте одна открытая дуга (π/6;5π/6); интервалов ${n+1}.`,`Әр айналымда бір ашық (π/6;5π/6) доғасы бар; аралық саны ${n+1}.`)]));

core('linear-inequality-systems','Системы неравенств','profile',b('Системы линейных неравенств','Сызықтық теңсіздіктер жүйесі'),'11',['linear-inequalities'],b('Пересекать линейные ограничения и работать со строгими границами.','Сызықтық шектеулерді қиылыстыру және қатаң шекаралармен жұмыс істеу.'),b('Реши каждую строку как обычное линейное неравенство. На одной прямой отметь каждое множество и оставь общую часть. Когда нижняя граница выше верхней, решений нет. Границу включаем только если её допускает каждое неравенство.','Әр жолды кәдімгі сызықтық теңсіздік ретінде шеш. Бір түзуге әр жиынды белгілеп, ортақ бөлікті қалдыр. Төменгі шекара жоғарғысынан үлкен болса, шешім жоқ. Шекара әр теңсіздік рұқсат етсе ғана кіреді.'),b('x≥a и x<b ⇒ [a;b), если a<b; при a≥b — пустое множество.','x≥a және x<b ⇒ [a;b), a<b болса; a≥b кезінде бос жиын.'),b('Пустое множество ∅ не содержит ни одного решения.','Бос ∅ жиынында бір де бір шешім жоқ.'),b('Граница включена, хотя одно из условий строгое.','Бір шарт қатаң болса да, шекара қосылған.'),
 (i,n,l)=>l===1?num(b(`Сколько целых решений x≥${n}, x≤${n+4}?`,`x≥${n}, x≤${n+4} жүйесінің неше бүтін шешімі бар?`),5,[step(`Пересечение [${n};${n+4}].`,`Қиылысуы [${n};${n+4}].`),step('Четыре шага, пять целых чисел.','Төрт қадам, бес бүтін сан.')]):l===2?num(b(`Сколько целых x: −2x≤−${2*n}, 3x<${3*(n+4)}?`,`−2x≤−${2*n}, 3x<${3*(n+4)} жүйесін неше бүтін x шешеді?`),4,[step(`Первая строка x≥${n}, вторая x<${n+4}.`,`Бірінші жол x≥${n}, екінші x<${n+4}.`),step('Общая часть содержит 4 целых.','Ортақ бөлік 4 бүтін саннан тұрады.')]):num(b(`Сколько решений у системы x>${n+3}, x≤${n+2}?`,`x>${n+3}, x≤${n+2} жүйесінде неше шешім бар?`),0,[step('Нижняя граница больше верхней.','Төменгі шекара жоғарғысынан үлкен.'),step('Пересечение пусто, решений 0.','Қиылысуы бос, шешім 0.') ]));

core('rational-inequality-systems','Системы неравенств','profile',b('Системы рациональных неравенств','Рационал теңсіздіктер жүйесі'),'11',['rational-inequalities'],b('Совместить знаки нескольких дробей и все запрещённые точки.','Бірнеше бөлшектің таңбалары мен тыйым салынған нүктелерін біріктіру.'),b('Общая ОДЗ исключает нули всех знаменателей. Для каждой дроби отдельно реши методом интервалов. Потом пересекай решения, сохраняя все исключения: точка, запрещённая хотя бы одной строкой, запрещена всей системой. Равенство нулю разрешено только числителю при нестрогом знаке.','Ортақ ММЖ барлық бөлім нөлдерін алып тастайды. Әр бөлшекті аралықтар әдісімен жеке шеш. Содан кейін барлық тыйымдарды сақтап қиылыстыр: кемінде бір жолда тыйым салынған нүкте бүкіл жүйеде тыйым салынған. Қатаң емес таңбада нөл тек алымға рұқсат.'),b('A/B≤0: нули B исключены. Итог S=S₁∩S₂∩ОДЗ.','A/B≤0: B нөлдері алынбайды. Нәтиже S=S₁∩S₂∩ММЖ.'),b('Общая ОДЗ — значения, допустимые сразу для всех строк.','Ортақ ММЖ — барлық жолда бір уақытта мүмкін мәндер.'),b('После пересечения возвращена точка, запрещённая другим знаменателем.','Қиылыстырғаннан кейін басқа бөлім тыйым салған нүкте қайтарылған.'),
 (i,n,l)=>l===1?num(b(`Система 1/(x−${n})>0, x≤${n+3}. Сколько целых решений?`,`1/(x−${n})>0, x≤${n+3} жүйесінің неше бүтін шешімі бар?`),3,[step(`Первая строка x>${n}; общая часть (${n};${n+3}].`,`Бірінші жол x>${n}; ортақ бөлік (${n};${n+3}].`),step(`Целые ${n+1},${n+2},${n+3}.`,`Бүтіндер ${n+1},${n+2},${n+3}.`)]):l===2?num(b(`Сколько целых x: (x−${n})/(x−${n+4})≤0 и 1/(x−${n+1})>0?`,`(x−${n})/(x−${n+4})≤0 және 1/(x−${n+1})>0 шарттарына неше бүтін x сай?`),2,[step(`Первая часть [${n};${n+4}), вторая x>${n+1}.`,`Біріншісі [${n};${n+4}), екіншісі x>${n+1}.`),step(`Общая часть (${n+1};${n+4}); целые ${n+2},${n+3}.`,`Ортақ бөлік (${n+1};${n+4}); бүтіндер ${n+2},${n+3}.`)]):num(b(`Сколько целых x: (x−${n})/(x−${n+5})<0 и (x−${n+2})/(x−${n+4})≥0?`,`(x−${n})/(x−${n+5})<0 және (x−${n+2})/(x−${n+4})≥0 жүйесін неше бүтін x шешеді?`),2,[step(`Первое: (${n};${n+5}). Второе: (−∞;${n+2}]∪(${n+4};∞).`,`Біріншісі: (${n};${n+5}). Екіншісі: (−∞;${n+2}]∪(${n+4};∞).`),step(`Общие целые ${n+1},${n+2}; точка ${n+4} запрещена.`,`Ортақ бүтіндер ${n+1},${n+2}; ${n+4} нүктесі тыйым салынған.`)]));

core('nonlinear-inequality-systems','Системы неравенств','profile',b('Системы нелинейных неравенств','Сызықтық емес теңсіздіктер жүйесі'),'11',['quadratic-inequalities','irrational-inequalities'],b('Пересекать ограничения от параболы, корня и модуля.','Парабола, түбір және модуль шектеулерін қиылыстыру.'),b('Каждая строка может дать отрезок, несколько лучей или пустое множество. Преобразуй квадратное выражение в произведение, а корневое — только с учётом знаков. Модуль |x−a|≤r при r≥0 означает расстояние от x до a не больше r. Нарисуй общий участок, после чего считай целые значения.','Әр жол кесінді, бірнеше сәуле немесе бос жиын беруі мүмкін. Квадрат өрнекті көбейтіндіге, түбірді тек таңбаларын ескеріп түрлендір. r≥0 кезінде |x−a|≤r x-тен a-ға қашықтық r-ден аспайтынын білдіреді. Ортақ бөлікті сыз, содан кейін бүтін мәндерді сана.'),b('|x−a|≤r ⇔ a−r≤x≤a+r (r≥0). x²≤r² ⇔ −r≤x≤r.','|x−a|≤r ⇔ a−r≤x≤a+r (r≥0). x²≤r² ⇔ −r≤x≤r.'),b('Модуль — расстояние до нуля, а |x−a| — расстояние между числами.','Модуль — нөлге дейінгі, |x−a| — сандар арасындағы қашықтық.'),b('Из x²≤r² оставлен только положительный луч.','x²≤r²-тан тек оң сәуле қалдырылған.'),
 (i,n,l)=>l===1?num(b(`Сколько целых x: x²≤${(n+2)**2}, x≥0?`,`x²≤${(n+2)**2}, x≥0 шарттарына неше бүтін x сай?`),n+3,[step(`Первое: −${n+2}≤x≤${n+2}; пересекаем с x≥0.`,`Біріншісі: −${n+2}≤x≤${n+2}; x≥0-мен қиылыстырамыз.`),step(`0,…,${n+2}: ${n+3} целых.`,`0,…,${n+2}: ${n+3} бүтін.`)]):l===2?num(b(`Сколько целых x: |x−${n}|≤3, x²≥${n*n}?`,`|x−${n}|≤3, x²≥${n*n} шарттарына неше бүтін x сай?`),4+(n===1?2:0),[step(`Первое [${n-3};${n+3}], второе x≤−${n} или x≥${n}.`,`Біріншісі [${n-3};${n+3}], екіншісі x≤−${n} немесе x≥${n}.`),step(n===1?'Общие целые −2,−1,1,2,3,4: 6.':`При n=${n} левый участок не содержит целых; правый ${n},…,${n+3}:4.`,n===1?'Ортақ бүтіндер −2,−1,1,2,3,4: 6.':`n=${n} кезінде сол бөлік бос; оң жақ ${n},…,${n+3}:4.`)]):num(b(`Сколько целых x: √(x−${n})≤2, (x−${n+1})(x−${n+3})≥0?`,`√(x−${n})≤2, (x−${n+1})(x−${n+3})≥0 шарттарына неше бүтін x сай?`),4,[step(`Корень даёт [${n};${n+4}]. Квадрат: x≤${n+1} или x≥${n+3}.`,`Түбір [${n};${n+4}] береді. Квадрат: x≤${n+1} немесе x≥${n+3}.`),step(`Общие ${n},${n+1},${n+3},${n+4}:4.`,`Ортақ ${n},${n+1},${n+3},${n+4}:4.`)]));

core('exponential-inequality-systems','Системы неравенств','profile',b('Системы показательных неравенств','Көрсеткіштік теңсіздіктер жүйесі'),'11',['exponential-inequalities','linear-inequality-systems'],b('Совместить возрастающую и убывающую показательную функцию.','Өсетін және кемитін көрсеткіштік функцияларды біріктіру.'),b('Основание проверяй для каждой строки отдельно: в одной системе могут встретиться 2 и 1/2. Приведи к общему основанию или учти направление монотонности, затем пересекай промежутки показателей. При квадратной замене сохрани t>0 и вернись к исходной переменной.','Әр жолдың негізін бөлек тексер: бір жүйеде 2 және 1/2 кездесуі мүмкін. Ортақ негізге келтір не монотондық бағытын ескер, кейін көрсеткіш аралықтарын қиылыстыр. Квадрат алмастыруда t>0 сақтап, бастапқы айнымалыға қайт.'),b('2ˣ≥2ᵃ ⇒ x≥a; (1/2)ˣ≥(1/2)ᵇ ⇒ x≤b; вместе [a;b].','2ˣ≥2ᵃ ⇒ x≥a; (1/2)ˣ≥(1/2)ᵇ ⇒ x≤b; бірге [a;b].'),b('Одно основание не означает одинаковую запись: 4ˣ=2²ˣ.','Бір негіз бірдей жазуды білдірмейді: 4ˣ=2²ˣ.'),b('Знак второй строки сохранён при убывающем основании.','Кемитін негізі бар екінші жолдың таңбасы сақталған.'),
 (i,n,l)=>l===1?num(b(`Сколько целых x: 2ˣ≥${2**n}, 2ˣ≤${2**(n+3)}?`,`2ˣ≥${2**n}, 2ˣ≤${2**(n+3)} шарттарына неше бүтін x сай?`),4,[step(`${n}≤x≤${n+3}.`,`${n}≤x≤${n+3}.`),step('Границы включены: 4 целых.','Шекаралар кіреді: 4 бүтін.')]):l===2?num(b(`Сколько целых x: 2ˣ>2^${n}, (1/2)ˣ≥(1/2)^${n+4}?`,`2ˣ>2^${n}, (1/2)ˣ≥(1/2)^${n+4} шарттарына неше бүтін x сай?`),4,[step(`x>${n}, x≤${n+4}.`,`x>${n}, x≤${n+4}.`),step(`Целые ${n+1},…,${n+4}:4.`,`Бүтіндер ${n+1},…,${n+4}:4.`)]):num(b(`Сколько целых x: 4ˣ−${3*2**n}·2ˣ+${2**(2*n+1)}≤0, 2ˣ>${2**n}?`,`4ˣ−${3*2**n}·2ˣ+${2**(2*n+1)}≤0, 2ˣ>${2**n} шарттарына неше бүтін x сай?`),1,[step(`Замена t=2ˣ даёт ${n}≤x≤${n+1}.`,`t=2ˣ алмастыруы ${n}≤x≤${n+1} береді.`),step(`Вторая строка x>${n}, остаётся только ${n+1}.`,`Екінші жол x>${n}, тек ${n+1} қалады.`)]));

core('log-inequality-systems','Системы неравенств','profile',b('Системы логарифмических неравенств','Логарифмдік теңсіздіктер жүйесі'),'11',['log-inequalities','linear-inequality-systems'],b('Совместить все логарифмические ограничения и исключить нулевые аргументы.','Барлық логарифмдік шектеулерді біріктіру және нөл аргументтерді алып тастау.'),b('Запиши положительность аргументов всех строк. Для основания больше 1 знак сравнения сохраняется, для основания меньше 1 меняется. Затем возьми общую часть с ОДЗ. Если границы совпали, отдельно проверь точку: строгий знак или нулевой аргумент делают её недопустимой.','Барлық жолдың аргументтері оң екенін жаз. Бірден үлкен негізде салыстыру таңбасы сақталады, кіші негізде өзгереді. Кейін ММЖ-мен ортақ бөлікті ал. Шекаралар сәйкес келсе, нүктені жеке тексер: қатаң таңба не нөл аргумент оны жарамсыз етеді.'),b('log₂x≥a, log₂x≤b ⇒ 2ᵃ≤x≤2ᵇ. ОДЗ: x>0.','log₂x≥a, log₂x≤b ⇒ 2ᵃ≤x≤2ᵇ. ММЖ: x>0.'),b('Совместное решение принадлежит всем областям определения и всем полученным интервалам.','Ортақ шешім барлық анықталу облысы мен алынған аралықтарға кіреді.'),b('Пересечены интервалы без ОДЗ каждой строки.','Аралықтар әр жолдың ММЖ-сынсыз қиылыстырылған.'),
 (i,n,l)=>l===1?num(b(`Сколько целых x: log₂x≥${n}, log₂x≤${n+1}?`,`log₂x≥${n}, log₂x≤${n+1} шарттарына неше бүтін x сай?`),2**n+1,[step(`${2**n}≤x≤${2**(n+1)}.`,`${2**n}≤x≤${2**(n+1)}.`),step(`Число целых ${2**(n+1)}−${2**n}+1=${2**n+1}.`,`Бүтін саны ${2**(n+1)}−${2**n}+1=${2**n+1}.`)]):l===2?num(b(`Сколько целых x: log₂(x−${n})>0, log₁/₂(x−${n})≥−2?`,`log₂(x−${n})>0, log₁/₂(x−${n})≥−2 шарттарына неше бүтін x сай?`),3,[step(`Первое x−${n}>1. Второе 0<x−${n}≤4.`,`Біріншісі x−${n}>1. Екіншісі 0<x−${n}≤4.`),step(`Общие целые ${n+2},${n+3},${n+4}:3.`,`Ортақ бүтіндер ${n+2},${n+3},${n+4}:3.`)]):num(b(`Сколько целых x: log₂(x−${n})≤2, log₂(${n+5}−x)≤1?`,`log₂(x−${n})≤2, log₂(${n+5}−x)≤1 шарттарына неше бүтін x сай?`),2,[step(`Первое ${n}<x≤${n+4}. Второе ${n+3}≤x<${n+5}.`,`Біріншісі ${n}<x≤${n+4}. Екіншісі ${n+3}≤x<${n+5}.`),step(`Пересечение [${n+3};${n+4}]:2 целых.`,`Қиылысуы [${n+3};${n+4}]:2 бүтін.`)]));

core('space-relations','Стереометрия','profile',b('Прямые и плоскости в пространстве','Кеңістіктегі түзулер мен жазықтықтар'),'16',['solids','plane-vectors'],b('Различать пересечение, параллельность, скрещивание и перпендикулярность.','Қиылысу, параллельдік, айқастық және перпендикулярлықты ажырату.'),b('Две прямые в пространстве могут лежать в одной плоскости и пересекаться/быть параллельными, либо не лежать в одной плоскости — быть скрещивающимися. Прямая перпендикулярна плоскости, если перпендикулярна двум пересекающимся прямым этой плоскости через точку пересечения. Координатные плоскости: xy имеет z=0, yz имеет x=0, xz имеет y=0.','Кеңістіктегі екі түзу бір жазықтықта жатып қиылысуы/параллель болуы мүмкін, не бір жазықтықта жатпай айқас болады. Түзу жазықтыққа перпендикуляр болуы үшін қиылысу нүктесінен өтетін жазықтықтағы екі қиылысатын түзуге перпендикуляр болуы керек. Координаталық жазықтықтар: xy үшін z=0, yz үшін x=0, xz үшін y=0.'),b('Расстояние до xy: |z|; до yz: |x|; до xz: |y|. Нормаль — вектор, перпендикулярный плоскости.','xy-ге қашықтық: |z|; yz-ге: |x|; xz-ке: |y|. Нормаль — жазықтыққа перпендикуляр вектор.'),b('Скрещивающиеся прямые не пересекаются и не параллельны. Перпендикуляр означает угол 90°.','Айқас түзулер қиылыспайды және параллель емес. Перпендикуляр деген 90° бұрыш.'),b('Две непересекающиеся прямые в пространстве автоматически названы параллельными.','Кеңістікте қиылыспайтын екі түзу автоматты түрде параллель аталған.'),
 (i,n,l)=>l===1?num(b(`Расстояние от A(2;3;−${n+1}) до плоскости xy?`,`A(2;3;−${n+1}) нүктесінен xy жазықтығына қашықтық?`),n+1,[step('До xy расстояние равно |z|.','xy-ге қашықтық |z|-ке тең.'),step(`|−${n+1}|=${n+1}.`,`|−${n+1}|=${n+1}.`)]):l===2?num(b(`Прямая (x;y;z)=(1;2;t) пересекает плоскость z=${n+3}. При каком t?`,`(x;y;z)=(1;2;t) түзуі z=${n+3} жазықтығын қияды. Қай t кезінде?`),n+3,[step('На прямой z=t.','Түзуде z=t.'),step(`Подставляем в плоскость: t=${n+3}.`,`Жазықтыққа қоямыз: t=${n+3}.`)]):num(b(`Прямая (x;y;z)=(t;2t;3t) пересекает плоскость x+y+z=${6*n}. Найди t.`,`(x;y;z)=(t;2t;3t) түзуі x+y+z=${6*n} жазықтығын қияды. t тап.`),n,[step(`t+2t+3t=6t=${6*n}.`,`t+2t+3t=6t=${6*n}.`),step(`t=${n}; точка (${n};${2*n};${3*n}).`,`t=${n}; нүкте (${n};${2*n};${3*n}).`)]));

core('sections','Стереометрия','profile',b('Сечения пространственных тел','Кеңістік денелерінің қималары'),'16,17',['similarity','solids','circles'],b('Найти форму и размер параллельного или центрального сечения.','Параллель не центрлік қиманың пішінін және өлшемін табу.'),b('Сечение получается плоскостью, а не линией на рисунке. У призмы параллельное основанию сечение равно основанию. У пирамиды сечение параллельное основанию подобно ему: линейный коэффициент равен расстоянию от вершины до сечения, делённому на высоту пирамиды. У шара сечение круг, радиус определяется прямоугольным треугольником.','Қима сызбадағы сызықпен емес, жазықтықпен жасалады. Призманың табанына параллель қимасы табанға тең. Пирамиданың табанына параллель қимасы оған ұқсас: сызықтық коэффициент төбеден қимаға қашықтықтың биіктікке қатынасы. Шар қимасы дөңгелек, радиусы тікбұрышты үшбұрыштан табылады.'),b('Пирамида: k=d/H, Sсеч=k²Sосн. Шар: rсеч²=R²−d², 0≤d≤R.','Пирамида: k=d/H, Sқима=k²Sтабан. Шар: rқима²=R²−d², 0≤d≤R.'),b('d для пирамиды измеряется от вершины; d для шара — от центра.','Пирамидадағы d төбеден, шардағы d центрден өлшенеді.'),b('Расстояние от основания перепутано с расстоянием от вершины.','Табаннан қашықтық төбеден қашықтықпен шатастырылған.'),
 (i,n,l)=>l===1?num(b(`Призма имеет основание площадью ${6*n}. Площадь параллельного основанию сечения?`,`Призманың табан ауданы ${6*n}. Табанға параллель қиманың ауданы?`),6*n,[step('Такое сечение равно основанию.','Мұндай қима табанға тең.'),step(`Площадь ${6*n}.`,`Ауданы ${6*n}.`)]):l===2?num(b(`У пирамиды Sосн=${16*n}, H=8. Сечение в 4 единицах от вершины. Его площадь?`,`Пирамиданың Sтабан=${16*n}, H=8. Қима төбеден 4 бірлікте. Ауданы?`),4*n,[step('k=4/8=1/2.','k=4/8=1/2.'),step(`Sсеч=${16*n}·(1/2)²=${4*n}.`,`Sқима=${16*n}·(1/2)²=${4*n}.`)]):num(b(`Шар R=${5*n}, плоскость в ${3*n} от центра. Радиус круга сечения?`,`Шар R=${5*n}, жазықтық центрден ${3*n} қашықтықта. Қима дөңгелегінің радиусы?`),4*n,[step(`r²=R²−d²=${25*n*n}−${9*n*n}=${16*n*n}.`,`r²=R²−d²=${25*n*n}−${9*n*n}=${16*n*n}.`),step(`r=${4*n}.`,`r=${4*n}.`)]));

core('prisms','Стереометрия','profile',b('Призмы и параллелепипеды','Призмалар және параллелепипедтер'),'16,17',['solids','triangles','quadrilaterals'],b('Найти поверхность, объём и диагональ прямой призмы.','Тік призманың бетін, көлемін және диагоналін табу.'),b('У прямой призмы боковые рёбра перпендикулярны основаниям, их длина равна высоте h. Боковые грани — прямоугольники, поэтому боковая поверхность равна периметру основания на h. Для наклонной призмы эту формулу нельзя использовать без уточнения. У прямоугольного параллелепипеда пространственная диагональ находится двумя применениями Пифагора.','Тік призманың бүйір қырлары табандарға перпендикуляр, олардың ұзындығы h биіктігіне тең. Бүйір жақтары тіктөртбұрыш, сондықтан бүйір бет табан периметрі мен h көбейтіндісіне тең. Көлбеу призмада бұл формуланы шартсыз қолдануға болмайды. Тікбұрышты параллелепипед диагоналі Пифагорды екі рет қолданумен табылады.'),b('V=Sh; Sбок=Ph; Sпол=2S+Ph (прямая призма); d=√(a²+b²+c²).','V=Sh; Sбүйір=Ph; Sтолық=2S+Ph (тік призма); d=√(a²+b²+c²).'),b('S — площадь основания; P — его периметр; h — перпендикулярная высота.','S — табан ауданы; P — оның периметрі; h — перпендикуляр биіктік.'),b('Формула Ph применена к наклонной призме без условий.','Ph формуласы көлбеу призмаға шартсыз қолданылған.'),
 (i,n,l)=>l===1?num(b(`Призма Sосн=${3*n}, h=4. Объём?`,`Призма Sтабан=${3*n}, h=4. Көлемі?`),12*n,[step('V=Sh.','V=Sh.'),step(`${3*n}·4=${12*n}.`,`${3*n}·4=${12*n}.`)]):l===2?num(b(`Прямая призма Sосн=${5*n}, Pосн=${8*n}, h=3. Полная поверхность?`,`Тік призма Sтабан=${5*n}, Pтабан=${8*n}, h=3. Толық беті?`),34*n,[step(`Два основания ${10*n}, боковая ${24*n}.`,`Екі табан ${10*n}, бүйір бет ${24*n}.`),step(`Сумма ${34*n}.`,`Қосындысы ${34*n}.`)]):num(b(`Параллелепипед имеет рёбра ${n},${2*n},${2*n}. Пространственная диагональ?`,`Параллелепипед қырлары ${n},${2*n},${2*n}. Кеңістік диагоналі?`),3*n,[step(`d²=${n*n}+${4*n*n}+${4*n*n}=${9*n*n}.`,`d²=${n*n}+${4*n*n}+${4*n*n}=${9*n*n}.`),step(`d=${3*n}.`,`d=${3*n}.`)]));

core('pyramids','Стереометрия','profile',b('Пирамиды и апофема','Пирамидалар және апофема'),'16,17',['solids','triangles','quadrilaterals'],b('Различать высоту пирамиды, боковое ребро и апофему.','Пирамида биіктігін, бүйір қырын және апофемасын ажырату.'),b('Объём пирамиды в три раза меньше объёма призмы с тем же основанием и высотой. Правильная пирамида имеет правильный многоугольник в основании, а вершина над его центром. Апофема l — высота бокового треугольника, она не равна вертикальной высоте H. У квадратного основания l²=H²+(a/2)².','Пирамида көлемі табаны мен биіктігі бірдей призмадан үш есе аз. Дұрыс пирамиданың табаны дұрыс көпбұрыш, төбесі оның центрінің үстінде. l апофема — бүйір үшбұрыш биіктігі, ол тік H биіктігіне тең емес. Шаршы табанда l²=H²+(a/2)².'),b('V=SH/3; Sбок=Pl/2 для правильной пирамиды; Sпол=Sосн+Sбок.','V=SH/3; дұрыс пирамидада Sбүйір=Pl/2; Sтолық=Sтабан+Sбүйір.'),b('Апофема — высота боковой грани; правильный многоугольник имеет равные стороны и углы.','Апофема — бүйір жақ биіктігі; дұрыс көпбұрыштың қабырғалары мен бұрыштары тең.'),b('В объём подставлена апофема вместо вертикальной высоты.','Көлемге тік биіктік орнына апофема қойылған.'),
 (i,n,l)=>l===1?num(b(`Пирамида Sосн=${6*n}, H=3. Объём?`,`Пирамида Sтабан=${6*n}, H=3. Көлемі?`),6*n,[step('V=SH/3.','V=SH/3.'),step(`${6*n}·3/3=${6*n}.`,`${6*n}·3/3=${6*n}.`)]):l===2?num(b(`Правильная квадратная пирамида: сторона ${2*n}, апофема ${3*n}. Боковая поверхность?`,`Дұрыс төртбұрышты пирамида: қабырға ${2*n}, апофема ${3*n}. Бүйір беті?`),12*n*n,[step(`Pосн=4·${2*n}=${8*n}.`,`Pтабан=4·${2*n}=${8*n}.`),step(`Sбок=${8*n}·${3*n}/2=${12*n*n}.`,`Sбүйір=${8*n}·${3*n}/2=${12*n*n}.`)]):num(b(`Правильная квадратная пирамида: сторона ${6*n}, высота ${4*n}. Найди апофему.`,`Дұрыс төртбұрышты пирамида: қабырға ${6*n}, биіктік ${4*n}. Апофеманы тап.`),5*n,[step(`Половина стороны ${3*n}; l²=${9*n*n}+${16*n*n}.`,`Қабырға жартысы ${3*n}; l²=${9*n*n}+${16*n*n}.`),step(`l=${5*n}.`,`l=${5*n}.`)]));

core('cylinders','Тела вращения','profile',b('Цилиндр и его развёртка','Цилиндр және оның жазбасы'),'16,17',['circles','units'],b('Найти объём, боковую и полную поверхность цилиндра.','Цилиндрдің көлемін, бүйір және толық бетін табу.'),b('Прямой круговой цилиндр получается вращением прямоугольника вокруг стороны. У него два равных круга-основания, радиус r и перпендикулярная высота h. Боковая развёртка — прямоугольник со сторонами 2πr и h. Полная поверхность добавляет оба круга.','Тік дөңгелек цилиндр тіктөртбұрышты қабырғасының айналасында айналдырудан шығады. Екі тең дөңгелек табаны, r радиусы және перпендикуляр h биіктігі бар. Бүйір жазбасы — қабырғалары 2πr және h тіктөртбұрыш. Толық бетке екі дөңгелек қосылады.'),b('V=πr²h; Sбок=2πrh; Sпол=2πrh+2πr².','V=πr²h; Sбүйір=2πrh; Sтолық=2πrh+2πr².'),b('Тело вращения — фигура, полученная оборотом плоской фигуры вокруг оси.','Айналу денесі — жазық фигураның ось айналасындағы айналуынан алынған дене.'),b('Диаметр подставлен вместо радиуса или забыто второе основание.','Радиус орнына диаметр қойылған немесе екінші табан ұмытылған.'),
 (i,n,l)=>num(b(`Цилиндр r=${n+1},h=3. Найди коэффициент перед π в ${l===1?'объёме':l===2?'боковой поверхности':'полной поверхности'}.`,`Цилиндр r=${n+1},h=3. ${l===1?'Көлеміндегі':l===2?'Бүйір бетіндегі':'Толық бетіндегі'} π коэффициентін тап.`),l===1?3*(n+1)**2:l===2?6*(n+1):6*(n+1)+2*(n+1)**2,[step(l===1?'V=πr²h.':l===2?'Sбок=2πrh.':'Sпол=2πrh+2πr².',l===1?'V=πr²h.':l===2?'Sбүйір=2πrh.':'Sтолық=2πrh+2πr².'),step(`Подставляем r=${n+1},h=3; оставляем множитель перед π.`,`r=${n+1},h=3 қоямыз; π алдындағы көбейткішті аламыз.`)]));

core('cones','Тела вращения','profile',b('Конус, высота и образующая','Конус, биіктік және жасаушы'),'16,17',['circles','triangles','pyramids'],b('Отличать образующую от высоты и выбирать правильную формулу.','Жасаушыны биіктіктен ажырату және дұрыс формуланы таңдау.'),b('Прямой круговой конус получается вращением прямоугольного треугольника вокруг катета. Ось проходит через вершину и центр основания. Образующая l соединяет вершину с окружностью основания; высота h идёт к центру под прямым углом. Поэтому r,h,l образуют прямоугольный треугольник. Боковая развёртка — сектор круга радиуса l.','Тік дөңгелек конус тікбұрышты үшбұрышты катеттің айналасында айналдырудан шығады. Ось төбе мен табан центрінен өтеді. l жасаушысы төбені табан шеңберімен қосады; h биіктігі центрге тік түседі. Сондықтан r,h,l тікбұрышты үшбұрыш құрайды. Бүйір жазбасы — радиусы l дөңгелек секторы.'),b('l²=r²+h²; V=πr²h/3; Sбок=πrl; Sпол=πr(l+r).','l²=r²+h²; V=πr²h/3; Sбүйір=πrl; Sтолық=πr(l+r).'),b('Образующая идёт по поверхности, высота — внутри вдоль оси.','Жасаушы бетпен, биіктік іште ось бойымен өтеді.'),b('Объём посчитан через l или боковая площадь через h.','Көлем l арқылы не бүйір аудан h арқылы есептелген.'),
 (i,n,l)=>l===1?num(b(`Конус r=${3*n},h=${4*n}. Образующая?`,`Конус r=${3*n},h=${4*n}. Жасаушысы?`),5*n,[step(`l²=${9*n*n}+${16*n*n}=${25*n*n}.`,`l²=${9*n*n}+${16*n*n}=${25*n*n}.`),step(`l=${5*n}.`,`l=${5*n}.`)]):num(b(`Конус r=${3*n},h=${4*n}. Найди коэффициент перед π в ${l===2?'объёме':'полной поверхности'}.`,`Конус r=${3*n},h=${4*n}. ${l===2?'Көлеміндегі':'Толық бетіндегі'} π коэффициентін тап.`),l===2?12*n**3:24*n*n,[step(`Образующая ${5*n}.`,`Жасаушысы ${5*n}.`),step(l===2?`r²h/3=${9*n*n}·${4*n}/3=${12*n**3}.`:`r(l+r)=${3*n}·${8*n}=${24*n*n}.`,l===2?`r²h/3=${9*n*n}·${4*n}/3=${12*n**3}.`:`r(l+r)=${3*n}·${8*n}=${24*n*n}.`)]));

